/* 자동 생성 — scripts/gen-server-content.mjs. 직접 고치지 말 것. */
// eslint-disable-next-line
export const UNITS: Record<string, any> = {"s1-g01":{"title":"세계화 시대, 지리의 힘","lessons":[{"id":"s1-g01-1","title":"위치와 환경으로 지역 읽기","standard":{"text":"세계 여러 지역의 특성을 해당 지역의 위치와 자연⋅인문환경을 고려하여 추론한다."},"sections":[{"title":"지역을 읽는 첫걸음, 위치","text":"위치는 지역의 특성을 이해하는 출발점이다. 어떤 곳이 지구 어디에 있는지 알면 그곳의 기후와 생활 모습을 짐작할 수 있다.\n\n위치를 나타내는 방법은 여러 가지다. 수리적 위치는 위도와 경도로 나타낸다. 위도는 적도를 0°로 하여 남북으로 각각 90°까지 나뉜다. 경도는 영국 그리니치 천문대를 지나는 본초 자오선을 0°로 하여 동서로 각각 180°까지 나뉜다.\n\n지리적 위치는 대륙·해양·반도처럼 주변 지형지물을 기준으로 나타낸다. 관계적 위치는 주변 국가나 지역과의 관계로 나타내며, 시대에 따라 달라질 수 있다. 세 가지 위치를 함께 살피면 그 지역을 더 입체적으로 이해할 수 있다."},{"title":"위치가 자연환경과 인문환경을 만든다","text":"위도는 기후에 큰 영향을 준다. 적도에 가까운 저위도는 태양 에너지를 많이 받아 덥다. 극지방에 가까운 고위도는 태양 에너지를 적게 받아 춥다. 그래서 적도에서 극으로 가면서 열대·온대·냉대·한대 기후가 차례로 나타난다.\n\n바다와의 거리도 중요하다. 바다에 가까운 곳은 여름과 겨울의 기온 차이가 작다. 대륙 내부는 기온 차이가 크다. 경도는 시간에 영향을 준다. 지구는 24시간에 360°를 돌기 때문에 경도 15°마다 1시간의 시차가 생긴다.\n\n사람들은 이러한 자연환경에 적응하며 인구 분포·산업·문화 같은 인문환경을 만들어 왔다. 자연환경과 인문환경이 어우러져 그 지역만의 특성, 곧 지역성이 나타난다."},{"title":"위치와 환경으로 지역 추론하기","text":"위치와 환경을 알면 지역의 모습을 추론할 수 있다. 적도 부근의 덥고 비가 많은 지역에서는 바닥을 땅에서 띄운 고상 가옥을 볼 수 있다. 습기와 해충을 피하고 바람이 잘 통하게 하기 위해서다. 비가 적은 건조 지역에서는 흙벽돌집과 오아시스 주변의 농업이 나타난다.\n\n우리나라도 같은 방법으로 읽을 수 있다. 우리나라는 북반구 중위도에 있어 사계절이 뚜렷하다. 유라시아 대륙 동쪽 끝의 반도에 있어 계절풍의 영향을 받는다. 또 대륙과 해양 양쪽으로 교류하기에 유리한 위치에 있다. 이처럼 위치에서 출발해 기후, 다시 생활 모습으로 생각을 이어 가면 지역의 특성을 추론할 수 있다."}],"concepts":[{"term":"위치","desc":"지구 위에서 어떤 장소가 있는 곳. 위도·경도로 나타내는 수리적 위치와 대륙·해양을 기준으로 한 지리적 위치가 있다."},{"term":"자연환경","desc":"지형·기후·식생처럼 사람이 만들지 않은 환경. 생활 모습과 산업에 영향을 준다."},{"term":"인문환경","desc":"인구·문화·산업·교통처럼 사람이 만든 환경."},{"term":"지역성","desc":"자연환경과 인문환경이 어우러져 나타나는 그 지역만의 특성."},{"term":"본초 자오선","desc":"영국 그리니치 천문대를 지나는 경도 0°의 선. 동경과 서경을 나누는 기준이다."}]},{"id":"s1-g01-2","title":"연결되는 세계","standard":{"text":"다양한 스케일에서 지역이 서로 연계되어 있음을 공간적 상호 작용의 사례를 통해 파악한다."},"sections":[{"title":"공간적 상호 작용이란","text":"공간적 상호 작용은 지역과 지역 사이에 사람·물자·정보·자본이 오가며 서로 영향을 주고받는 것이다. 어떤 지역도 홀로 존재하지 않는다.\n\n우리 생활 곳곳에서 공간적 상호 작용을 볼 수 있다. 다른 동네에 있는 학교로 통학하는 것, 다른 지역에서 온 택배를 받는 것, 외국 친구와 메시지를 주고받는 것이 모두 그 예다. 이동하는 것이 사람이든 물건이든 정보든, 지역은 이런 흐름을 통해 연결된다.\n\n상호 작용은 한쪽이 가진 것을 다른 쪽이 필요로 할 때 일어난다. 농촌의 농산물은 도시로 가고, 도시의 공산품과 서비스는 농촌으로 간다. 두 지역은 서로 부족한 것을 채우며 함께 변해 간다."},{"title":"다양한 스케일에서 나타나는 연결","text":"공간적 상호 작용은 여러 스케일에서 나타난다. 스케일은 현상을 바라보는 공간의 범위다. 동네 스케일에서는 집·학교·시장 사이를 사람들이 오간다. 국가 스케일에서는 고속 철도와 고속 도로가 대도시와 지방을 잇는다. 세계 스케일에서는 항공기·컨테이너선·해저 케이블이 대륙과 대륙을 잇는다.\n\n교통과 통신이 발달하면 상호 작용은 더 활발해진다. 같은 거리를 이동하는 데 걸리는 시간이 줄어들기 때문이다. 이렇게 시간 거리가 짧아지면서 세계가 가깝게 느껴지는 현상을 시공간 압축이라고 한다. 오늘날에는 인터넷 덕분에 정보가 지구 반대편까지 거의 실시간으로 전해진다."},{"title":"연결이 만든 변화","text":"지역 간 연결은 생활을 크게 바꾼다. 휴대 전화 한 대에는 여러 나라에서 만든 부품이 들어간다. 각 지역이 잘하는 일을 나누어 맡고, 완성품은 다시 세계로 팔려 나간다.\n\n고속 철도가 개통되면 중소 도시 주민이 대도시의 병원·백화점을 이용하기 쉬워진다. 반대로 지역 상권은 손님을 대도시에 빼앗길 수도 있다. 연결이 긴밀해지면 감염병처럼 원하지 않는 것도 빠르게 퍼진다. 지역 간 연결에는 기회와 위험이 함께 있다. 그래서 연결의 이익은 살리고 피해는 줄이는 지역의 대응이 중요하다. 우리 동네가 어느 지역과 어떻게 연결되어 있는지 살펴보면 이런 변화를 직접 확인할 수 있다."}],"concepts":[{"term":"공간적 상호 작용","desc":"지역과 지역 사이에 사람·물자·정보·자본이 이동하며 서로 영향을 주고받는 현상."},{"term":"스케일","desc":"지리 현상을 바라보는 공간의 범위. 동네·국가·세계처럼 범위에 따라 보이는 모습이 달라진다."},{"term":"시공간 압축","desc":"교통·통신의 발달로 이동과 소통에 걸리는 시간이 줄어 세계가 가깝게 느껴지는 현상."},{"term":"해저 케이블","desc":"바다 밑에 깔린 통신용 광케이블. 국제 인터넷 데이터의 대부분이 이를 통해 오간다."}]},{"id":"s1-g01-3","title":"세계화와 지역화","standard":{"text":"세계의 변화가 지역에 영향을 미치고 지역의 변화가 세계에 영향을 미치는 사례를 조사한다."},"sections":[{"title":"세계화와 지역화","text":"세계화는 상품·자본·사람·정보·문화가 국경을 넘어 자유롭게 이동하며 세계가 하나로 연결되는 현상이다. 교통·통신의 발달과 무역 확대가 세계화를 이끌었다. 오늘날 우리는 외국에서 만든 물건을 쓰고, 외국 음악과 영상을 실시간으로 즐긴다.\n\n지역화는 지역이 고유한 특성을 살려 경쟁력을 갖추고 세계 속에서 가치를 높이는 현상이다. 세계화와 지역화는 서로 반대되는 것이 아니다. 둘은 동시에 일어나며 서로 영향을 준다. 세계와 연결될수록 지역은 다른 곳과 구별되는 자기만의 매력을 찾으려 하기 때문이다. 이처럼 세계화와 지역화가 함께 나타나는 현상을 세계지역화(글로컬라이제이션)라고 한다."},{"title":"세계의 변화가 지역에 미치는 영향","text":"세계에서 일어난 변화는 우리 동네까지 영향을 준다. 국제 곡물 가격이 오르면 밀가루 값이 올라 동네 빵집의 빵값도 오른다. 다국적 기업이 공장을 다른 나라로 옮기면 그 공장이 있던 지역의 일자리가 줄어든다.\n\n나라 사이에 자유 무역 협정이 맺어지면 외국 농산물이 더 많이 들어온다. 소비자는 다양한 상품을 싸게 살 수 있다. 하지만 같은 작물을 기르는 국내 농가는 더 치열한 경쟁을 겪는다. 세계의 변화는 지역에 기회와 어려움을 함께 가져온다. 그래서 지역은 세계의 흐름을 읽고 이에 맞추어 대응해야 한다. 예를 들어 농가는 품질을 높이거나 새로운 작물을 기르며 변화에 적응한다."},{"title":"지역의 변화가 세계에 미치는 영향","text":"반대로 한 지역의 변화가 세계에 영향을 주기도 한다. 우리나라에서 만든 드라마·음악·음식이 세계로 퍼져 한국 문화에 관심을 갖는 사람이 늘었다. 한 지역의 반도체 공장이 재해로 멈추면 여러 나라의 자동차·전자 제품 생산이 줄어들 수 있다.\n\n지역은 고유한 특성을 브랜드로 만들어 세계와 만난다. 보령 머드 축제는 외국인 관광객을 끌어들이는 지역 축제다. 보성 녹차는 지리적 표시제에 등록되어 지역 이름 자체가 품질을 보증하는 브랜드가 되었다. 이처럼 지역의 특색을 살린 상품과 문화는 세계 시장에서 경쟁력이 된다. 지역은 세계의 영향을 받기만 하는 곳이 아니라 세계를 바꾸는 주체이기도 하다."}],"concepts":[{"term":"세계화","desc":"상품·자본·사람·정보·문화가 국경을 넘어 자유롭게 이동하며 세계가 하나로 연결되는 현상."},{"term":"지역화","desc":"지역이 고유한 특성을 살려 경쟁력을 갖추고 세계 속에서 가치를 높이는 현상."},{"term":"세계지역화(글로컬라이제이션)","desc":"세계화와 지역화가 동시에 나타나는 현상. 세계적 흐름에 지역의 특색을 결합하는 전략을 뜻하기도 한다."},{"term":"지리적 표시제","desc":"품질과 명성이 특정 지역의 환경에서 비롯된 상품에 그 지역 이름을 표시해 보호하는 제도."},{"term":"다국적 기업","desc":"여러 나라에 지사·연구소·공장을 두고 세계적으로 활동하는 기업."}]}]},"s1-g02":{"title":"아시아","lessons":[{"id":"s1-g02-1","title":"아시아의 위치와 자연환경","standard":{"text":"다양한 지리 정보와 매체를 활용하여 아시아의 국가와 주요 도시의 위치를 파악하고 자연환경의 특성을 지도로 표현한다."},"sections":[{"title":"아시아의 위치와 국가·도시","text":"아시아는 세계에서 가장 넓은 대륙이다. 세계 인구의 절반 이상이 아시아에 산다. 아시아는 유라시아 대륙의 동쪽 대부분을 차지하며, 서쪽은 우랄산맥 등을 경계로 유럽과 나뉜다. 동쪽은 태평양, 남쪽은 인도양, 북쪽은 북극해와 맞닿아 있다.\n\n아시아는 보통 다섯 지역으로 나누어 본다. 동아시아에는 한국·중국·일본·몽골이 있다. 동남아시아에는 베트남(하노이)·태국(방콕)·인도네시아(자카르타)·필리핀(마닐라) 등이 있다. 남아시아에는 인도(뉴델리)·파키스탄·방글라데시가, 서남아시아에는 사우디아라비아(리야드)·이란(테헤란)·튀르키예가 있다. 중앙아시아에는 카자흐스탄·우즈베키스탄(타슈켄트) 등이 있다."},{"title":"높은 산지와 큰 하천","text":"아시아의 지형은 높낮이 차이가 크다. 대륙 가운데에는 세계에서 가장 높은 에베레스트산이 있는 히말라야산맥과 '세계의 지붕'이라 불리는 티베트고원이 있다.\n\n이 높은 산지에서 큰 하천이 여러 방향으로 흘러 나간다. 황허·창장(양쯔강)·메콩강·갠지스강·인더스강이 대표적이다. 하천이 실어 온 흙이 하류에 쌓여 넓은 충적 평야가 만들어졌다. 이곳은 농사짓기 좋아 예로부터 인구가 많이 모였다.\n\n일본·필리핀·인도네시아는 환태평양 조산대에 속한다. 그래서 지진과 화산 활동이 잦다. 화산재가 쌓인 땅은 기름져 농업에 이용되기도 한다. 지형도에 산지·고원·평야를 색으로 나누어 칠하면 이런 특징을 한눈에 볼 수 있다."},{"title":"다양한 기후와 지도로 표현하기","text":"아시아는 남북으로 길고 넓어 기후가 다양하다. 적도 부근 동남아시아에는 일 년 내내 덥고 비가 많은 열대 기후가 나타난다. 동아시아에는 사계절이 뚜렷한 온대 기후가, 시베리아 등 북부에는 냉대·한대 기후가 나타난다. 서남아시아와 중앙아시아에는 비가 적은 건조 기후가 넓게 펼쳐져 사막과 초원이 있다.\n\n동아시아·동남아시아·남아시아는 계절풍의 영향을 크게 받는다. 여름에는 바다에서 습한 바람이 불어 비가 많이 온다. 겨울에는 대륙에서 차고 건조한 바람이 분다.\n\n이런 특성은 기후 구분도나 지형도 같은 주제도로 표현한다. 색과 기호를 범례로 정리하면 넓은 지역의 특징을 한눈에 비교할 수 있다. 위성 영상과 디지털 지도도 좋은 자료가 된다."}],"concepts":[{"term":"계절풍(몬순)","desc":"계절에 따라 방향이 바뀌는 바람. 여름에는 바다에서 대륙으로, 겨울에는 대륙에서 바다로 분다."},{"term":"환태평양 조산대","desc":"태평양 둘레를 따라 고리 모양으로 이어진 지각 변동 지역. 지진과 화산 활동이 활발하다."},{"term":"충적 평야","desc":"하천이 운반한 흙과 모래가 쌓여 만들어진 평야. 땅이 기름져 농업에 유리하다."},{"term":"건조 기후","desc":"증발량이 강수량보다 많아 물이 부족한 기후. 사막과 짧은 풀의 초원(스텝)이 나타난다."},{"term":"주제도","desc":"기후·지형·인구처럼 특정한 주제를 골라 나타낸 지도."}]},{"id":"s1-g02-2","title":"종교와 문화경관","standard":{"text":"종교와 관련된 아시아의 다양한 문화경관과 생활양식을 파악하고, 세계시민으로서 문화 다양성에 대한 이해와 수용성을 높인다."},"sections":[{"title":"종교가 만든 문화경관","text":"문화경관은 사람이 자연환경 위에 자신들의 문화를 더해 만든 경관이다. 건물·마을·농경지·거리 모습이 모두 문화경관에 속한다. 종교는 문화경관을 만드는 중요한 요소다. 종교는 건축 양식뿐 아니라 음식·옷차림·하루 일과에도 영향을 준다.\n\n아시아는 여러 세계 종교가 생겨난 곳이다. 힌두교와 불교는 남아시아의 인도에서 시작되었다. 이슬람교와 크리스트교는 서남아시아에서 시작되었다. 이 종교들은 교역과 이동을 따라 아시아 곳곳과 세계로 퍼졌다. 그래서 같은 종교라도 퍼져 나간 지역의 환경과 문화에 따라 조금씩 다른 모습을 띤다. 오늘날 아시아에서는 지역마다 주로 믿는 종교가 달라 다양한 종교 경관을 볼 수 있다."},{"title":"아시아의 종교별 경관과 생활 모습","text":"이슬람교 지역에서는 둥근 지붕(돔)과 높은 첨탑(미너렛)이 있는 모스크를 볼 수 있다. 신자들은 하루 다섯 번 성지 메카를 향해 기도한다. 돼지고기와 술을 먹지 않으며, 율법에 맞게 만든 할랄 음식을 먹는다. 라마단 기간에는 해가 떠 있는 동안 금식한다.\n\n불교 지역에는 사원과 불탑이 많다. 태국·미얀마 등에서는 아침에 승려가 음식을 공양받는 탁발 모습을 볼 수 있다. 힌두교도가 많은 인도에서는 소를 신성하게 여겨 쇠고기를 먹지 않는 사람이 많다. 갠지스강에서 몸을 씻는 의식도 힌두교 문화경관이다. 이처럼 종교는 눈에 보이는 건물뿐 아니라 먹고 입고 생활하는 방식까지 바꾼다."},{"title":"문화 다양성을 존중하는 세계시민","text":"다른 문화를 이해하려면 그 문화가 만들어진 환경과 역사를 함께 살펴야 한다. 이런 태도를 문화 상대주의라고 한다. 자기 문화만 우월하다고 보는 자문화 중심주의는 편견과 갈등을 낳는다.\n\n우리나라에도 아시아 여러 나라에서 온 유학생·노동자·이주민이 늘고 있다. 할랄 음식점이 생기고, 공항과 일부 대학에는 기도실이 마련되기도 한다. 세계시민은 낯선 문화를 이상하게 여기기보다 그 의미를 묻고 함께 지낼 방법을 찾는다. 다만 문화 상대주의가 인권을 해치는 관습까지 무조건 인정하자는 뜻은 아니다. 인간의 존엄이라는 보편적 가치 안에서 다양성을 존중해야 한다."}],"concepts":[{"term":"문화경관","desc":"사람이 자연환경 위에 종교·생활 방식 등 문화적 요소를 더해 만든 경관."},{"term":"모스크","desc":"이슬람교의 예배 시설. 둥근 지붕(돔)과 높은 첨탑(미너렛)이 특징이다."},{"term":"할랄","desc":"이슬람 율법에서 허용된 것이라는 뜻. 율법에 맞게 만든 음식을 할랄 음식이라고 한다."},{"term":"문화 상대주의","desc":"각 문화를 그 사회의 환경과 역사적 맥락 속에서 이해하려는 태도."},{"term":"자문화 중심주의","desc":"자기 문화만 우월하다고 여기고 다른 문화를 낮추어 보는 태도."}]},{"id":"s1-g02-3","title":"인구 구조의 변화","standard":{"text":"아시아의 인구 특징을 파악하고 지역별 인구 구조 변화를 비교하여 지역 발전의 가능성 및 변화 모습을 추론한다."},"sections":[{"title":"아시아의 인구 특징","text":"아시아에는 세계 인구의 약 60%가 산다. 인도와 중국은 인구가 각각 14억 명 안팎인 인구 대국이다. 인도네시아·파키스탄·방글라데시도 인구가 많은 나라다.\n\n인구는 고르게 분포하지 않는다. 계절풍의 영향을 받는 하천 하류의 평야와 해안에는 인구가 밀집한다. 벼농사를 짓기 좋고 물을 얻기 쉬워서다. 반면 사막·고산 지대·추운 북부 지역은 인구가 희박하다.\n\n한 지역의 인구를 성별·연령별로 나눈 것을 인구 구조라고 한다. 인구 구조는 인구 피라미드라는 그래프로 나타낸다. 피라미드의 모양을 보면 그 지역의 출생률과 고령화 정도를 짐작할 수 있다."},{"title":"지역마다 다른 인구 구조 변화","text":"아시아 안에서도 인구 구조는 지역마다 다르게 변하고 있다. 한국·일본·중국 등 동아시아는 출생률이 크게 낮아지고 기대 수명이 늘었다. 그 결과 저출산·고령화가 빠르게 진행되고 있다. 일본은 일찍이 초고령 사회가 되었고, 우리나라의 합계 출산율은 세계 최저 수준이다.\n\n남아시아와 서남아시아 일부 나라는 출생률이 비교적 높다. 그래서 유소년층 비율이 높은 피라미드형 인구 구조가 나타난다.\n\n카타르·아랍에미리트 같은 서남아시아 산유국은 독특하다. 석유 산업과 건설 현장에서 일할 외국인 남성 노동자가 많이 들어와 20~40대 남성 비율이 매우 높다."},{"title":"인구 구조로 지역의 미래 추론하기","text":"인구 구조를 보면 지역 발전의 가능성과 과제를 추론할 수 있다. 청장년층이 많은 나라는 일할 사람이 많고 소비 시장도 커진다. 이처럼 생산 가능 인구 비율이 높아 경제 성장에 유리한 상황을 인구 보너스라고 한다. 다만 일자리가 충분하지 않으면 청년 실업이 문제가 된다.\n\n고령화가 빠른 나라는 노동력이 부족해지고 연금·의료 등 복지 비용이 늘어난다. 그래서 로봇과 자동화 기술을 늘리고, 외국인 노동자를 받아들이고, 출산과 양육을 지원하는 정책을 펼친다. 많은 기업이 젊은 노동력이 풍부한 베트남·인도 등에 투자하는 것도 인구 구조와 관련 있다."}],"concepts":[{"term":"인구 구조","desc":"한 지역의 인구를 성별·연령별 등으로 나누어 본 구성."},{"term":"인구 피라미드","desc":"성별·연령별 인구 비율을 막대로 쌓아 나타낸 그래프. 모양을 보면 출생률과 고령화 정도를 알 수 있다."},{"term":"저출산·고령화","desc":"태어나는 아이 수가 줄고 전체 인구에서 노인 인구 비율이 높아지는 현상."},{"term":"초고령 사회","desc":"전체 인구 중 65세 이상 인구 비율이 20% 이상인 사회. 7% 이상은 고령화 사회, 14% 이상은 고령 사회라고 한다."},{"term":"인구 보너스","desc":"전체 인구에서 생산 가능 인구 비율이 높아 경제 성장에 유리한 상황."}]},{"id":"s1-g02-4","title":"산업 변화와 우리나라","standard":{"text":"글로컬 관점에서 아시아의 산업 특징과 변화를 파악하고, 이것이 우리나라 산업에 미치는 영향을 탐색한다."},"sections":[{"title":"아시아 산업의 다양한 모습","text":"아시아 나라들은 산업 발달 단계와 주력 산업이 다양하다. 일본과 한국은 일찍 공업화를 이루어 반도체·자동차·조선 같은 첨단·중화학 공업이 발달했다. 중국은 1970년대 말 개혁·개방 이후 '세계의 공장'으로 성장했고, 최근에는 전기차·배터리 등 첨단 산업도 빠르게 키우고 있다.\n\n베트남·인도네시아·태국 등 동남아시아는 풍부한 노동력과 외국 기업의 투자를 바탕으로 제조업이 성장하고 있다. 인도는 소프트웨어·IT 서비스 산업이 발달했다. 서남아시아 산유국은 석유·천연가스 수출에 크게 의존해 왔으나, 관광·금융·물류 등으로 산업을 넓히려 하고 있다."},{"title":"산업은 왜, 어떻게 이동할까","text":"기업은 이익을 높이기 위해 각 기능에 알맞은 곳을 찾는다. 다국적 기업은 본사와 연구소를 기술과 자본이 풍부한 나라에 둔다. 생산 공장은 임금이 비교적 낮고 노동력이 풍부한 나라에 세운다. 이를 공간적 분업이라고 한다.\n\n한 나라의 임금이 오르면 공장은 더 낮은 임금을 찾아 다른 나라로 옮겨 가기도 한다. 그래서 아시아의 제조 공장은 일본·한국에서 중국으로, 다시 동남아시아와 남아시아로 퍼져 나갔다. 오늘날 아시아 나라들은 소재·부품을 만들고, 조립하고, 수출하는 과정이 여러 나라에 걸친 공급망으로 연결되어 있다. 우리나라에서 만든 부품이 다른 아시아 나라에서 조립되어 세계로 팔리는 것이 그 예다."},{"title":"글로컬 관점에서 본 우리나라 산업","text":"아시아의 산업 변화는 우리나라 산업에 직접 영향을 준다. 우리 기업이 해외에 공장을 세우면 현지에 일자리가 생기고 우리 기업은 생산비를 줄인다. 하지만 국내 공장이 빠져나간 지역에서는 일자리가 줄어드는 산업 공동화가 우려된다. 아시아 나라들이 기술력을 키우면서 같은 분야의 경쟁도 치열해지고 있다.\n\n아시아 시장의 성장은 우리에게 기회이기도 하다. 글로컬 관점은 세계의 흐름을 읽으면서 지역의 강점과 현지의 특성을 함께 살피는 관점이다. 한국 식품 기업이 현지 입맛에 맞춘 제품을 내놓거나 할랄 인증을 받아 이슬람권에 수출하는 것이 그 예다."}],"concepts":[{"term":"다국적 기업","desc":"여러 나라에 본사·연구소·공장을 두고 세계적으로 활동하는 기업."},{"term":"공간적 분업","desc":"기업의 본사·연구·생산 기능이 각각 유리한 지역에 나뉘어 자리 잡는 현상."},{"term":"산업 공동화","desc":"공장이 해외 등으로 빠져나가 그 지역이나 국가의 제조업 기반이 약해지는 현상."},{"term":"공급망","desc":"원료·부품 생산부터 조립, 판매까지 상품이 만들어져 소비자에게 가는 과정 전체의 연결."},{"term":"글로컬","desc":"세계(global)와 지역(local)을 합친 말. 세계적 흐름 속에서 지역·현지의 특성을 함께 살리는 관점이다."}]}]},"s1-g03":{"title":"유럽","lessons":[{"id":"s1-g03-1","title":"유럽의 위치와 자연환경","standard":{"text":"다양한 지리 정보와 매체를 활용하여 유럽의 국가와 주요 도시의 위치를 파악하고 자연환경의 특성을 지도로 표현한다."},"sections":[{"title":"유럽의 위치와 국가·도시","text":"유럽은 유라시아 대륙의 서쪽에 있다. 동쪽은 우랄산맥·카스피해·캅카스산맥 등을 경계로 아시아와 나뉜다. 서쪽은 대서양, 남쪽은 지중해, 북쪽은 북극해와 맞닿아 있다. 유럽의 대부분은 우리나라보다 북쪽인 고위도에 있다.\n\n유럽은 여러 지역으로 나누어 볼 수 있다. 서부에는 영국(런던)·프랑스(파리)가, 중부에는 독일(베를린)이 있다. 남부에는 이탈리아(로마)·스페인(마드리드)·그리스(아테네)가 있다. 북부에는 노르웨이(오슬로)·스웨덴(스톡홀름)이, 동부에는 폴란드(바르샤바) 등이 있다. 벨기에의 브뤼셀에는 유럽연합의 주요 기관이 모여 있다."},{"title":"북부의 빙하 지형, 중부의 평야, 남부의 산지","text":"유럽의 지형은 지역마다 뚜렷이 다르다. 북부에는 오래된 산지와 빙하가 만든 지형이 많다. 노르웨이 해안에는 빙하가 깎은 골짜기에 바닷물이 들어와 생긴 좁고 긴 만, 피오르가 발달했다.\n\n중부에는 넓은 평야가 펼쳐져 농업과 도시가 발달했다. 라인강 같은 하천은 경사가 완만하고 운하로 연결되어 배로 물자를 나르는 내륙 수운에 이용된다.\n\n남부에는 알프스산맥·피레네산맥처럼 높고 험한 산지가 있다. 지중해 연안의 이탈리아·그리스는 지각이 불안정해 지진과 화산 활동이 나타난다. 알프스의 빙하와 호수, 아름다운 산악 경관은 관광 자원으로도 이용된다."},{"title":"바다가 만든 기후의 차이","text":"유럽은 고위도에 있지만 서부는 같은 위도의 다른 지역보다 겨울이 따뜻하다. 따뜻한 북대서양 해류 위를 지난 편서풍이 바다의 열을 육지로 옮겨 주기 때문이다. 영국·프랑스 북부·독일 서부에는 겨울이 온화하고 일 년 내내 비가 고르게 내리는 서안 해양성 기후가 나타난다.\n\n지중해 연안에는 여름이 덥고 건조하며 겨울이 온화하고 비가 오는 지중해성 기후가 나타난다. 그래서 건조에 강한 올리브·포도·오렌지를 많이 기른다. 바다에서 먼 동부 내륙은 냉대 기후가 나타나 겨울이 매우 춥다. 북극해 연안에는 한대 기후가 나타난다. 이처럼 유럽의 기후는 바다와 얼마나 가까운지에 따라 크게 달라진다."}],"concepts":[{"term":"서안 해양성 기후","desc":"편서풍과 난류의 영향으로 위도에 비해 겨울이 온화하고 연중 비가 고르게 내리는 기후."},{"term":"지중해성 기후","desc":"여름은 덥고 건조하며 겨울은 온화하고 비가 오는 기후. 올리브·포도 재배에 알맞다."},{"term":"편서풍","desc":"중위도 지역에서 일 년 내내 서쪽에서 동쪽으로 부는 바람."},{"term":"북대서양 해류","desc":"대서양을 건너 유럽 서부 해안으로 흐르는 따뜻한 해류."},{"term":"피오르","desc":"빙하가 깎아 만든 U자 모양 골짜기에 바닷물이 들어와 생긴 좁고 긴 만."}]},{"id":"s1-g03-2","title":"기후위기와 지속가능한 도시","standard":{"text":"다양한 유형의 유럽 도시를 탐색하고, 기후위기에 대응하여 지속가능한 도시를 만들기 위한 노력을 조사한다."},"sections":[{"title":"다양한 유형의 유럽 도시","text":"유럽에는 역할과 모습이 다른 여러 유형의 도시가 있다. 로마·아테네·프라하는 오랜 역사를 지닌 건축물이 남아 있는 역사·문화 도시로, 세계 곳곳에서 관광객이 찾아온다. 런던과 파리는 금융·기업 본사·국제 교류가 집중된 세계 도시다.\n\n브뤼셀에는 유럽연합의 주요 기관이, 스위스 제네바에는 여러 국제기구가 모여 있다. 네덜란드의 로테르담은 유럽 최대 규모의 항구 도시다. 독일 루르 지역의 도시들은 석탄·철강 산업으로 성장한 공업 도시였으나, 옛 산업 시설을 문화 공간으로 바꾸며 새로운 모습으로 변하고 있다. 도시의 유형은 그 도시가 걸어온 역사와 위치에 따라 달라진다."},{"title":"기후 위기와 도시의 역할","text":"기후 위기는 온실가스 증가로 지구 온난화가 심해져 폭염·홍수·가뭄 같은 피해가 커지는 상황이다. 유럽도 여름철 폭염과 집중 호우로 큰 피해를 겪었다.\n\n도시는 기후 위기의 원인이자 해결의 열쇠다. 도시에는 사람·건물·자동차가 몰려 있어 에너지를 많이 쓰고 온실가스를 많이 내보낸다. 아스팔트와 건물이 열을 품어 도심 기온이 주변보다 높아지는 열섬 현상도 나타난다. 그래서 유럽연합은 2050년까지 탄소 중립을 이루겠다는 목표를 세우고, 많은 도시가 그 실천에 나서고 있다. 도시의 교통·건물·에너지를 바꾸면 많은 사람의 생활 방식이 한꺼번에 바뀌어 효과가 크다."},{"title":"지속가능한 도시를 만드는 노력","text":"유럽의 여러 도시는 지속가능한 도시를 만들기 위해 노력하고 있다. 덴마크 코펜하겐은 촘촘한 자전거 도로망을 갖추어 자전거로 출퇴근하는 시민이 많다. 독일 프라이부르크의 보봉 지구는 태양광 주택과 트램을 활용하고 자동차 이용을 줄인 생태 주거 단지로 알려져 있다.\n\n프랑스 파리는 강변 차도를 보행자 공간으로 바꾸고 자전거 도로를 늘렸다. 영국 런던은 도심에 들어오는 차량에 혼잡 통행료를 받고, 오염 물질을 많이 내는 차량에 요금을 매기는 구역을 운영한다. 옥상 녹화와 빗물 저장 시설도 널리 쓰인다. 우리나라 도시의 공공 자전거와 탄소 중립 실천 정책도 같은 흐름에 있다."}],"concepts":[{"term":"기후 위기","desc":"온실가스 증가로 지구 온난화가 심해져 폭염·홍수·가뭄 등 피해가 커지는 위기 상황."},{"term":"탄소 중립","desc":"온실가스 배출량과 흡수·제거량을 같게 하여 실질적인 배출을 0으로 만드는 것."},{"term":"열섬 현상","desc":"건물·포장도로·인공 열 때문에 도시 중심부 기온이 주변 지역보다 높게 나타나는 현상."},{"term":"지속가능한 도시","desc":"환경을 보전하면서 경제가 활력을 유지하고, 주민 모두가 살기 좋은 상태를 미래까지 이어 가는 도시."},{"term":"생태 도시","desc":"자연과 사람이 공존하도록 에너지·교통·녹지를 계획한 도시."}]},{"id":"s1-g03-3","title":"유럽의 통합과 분리","standard":{"text":"지역 간 역학관계에 따른 유럽의 통합과 분리의 움직임이 유럽연합의 변화와 주민 생활에 미치는 영향을 탐색한다."},"sections":[{"title":"유럽은 왜 하나로 뭉쳤을까","text":"유럽 통합은 두 차례 세계 대전의 경험에서 시작되었다. 전쟁을 막고 경제를 함께 되살리기 위해 유럽 나라들은 협력의 틀을 만들었다. 1952년 6개국이 석탄과 철강을 공동 관리하는 유럽 석탄 철강 공동체를 출범시켰다. 1957년에는 유럽 경제 공동체를 만드는 조약을 맺었다.\n\n1993년 마스트리흐트 조약이 발효되면서 유럽연합(EU)이 출범했다. 이후 동유럽 나라들이 가입하며 회원국이 크게 늘었다. 2020년 영국이 탈퇴한 뒤 회원국은 27개국이 되었다. 유럽연합은 경제뿐 아니라 환경·안보 등 여러 분야에서 공동 정책을 펼치는 조직으로 커졌다."},{"title":"통합이 바꾼 주민의 생활","text":"유럽연합은 상품·서비스·자본·사람이 자유롭게 오가는 단일 시장을 만들었다. 솅겐 협정에 가입한 나라 사이에서는 국경 검문 없이 이동할 수 있다. 많은 회원국이 단일 화폐인 유로화를 쓴다. 그래서 주민들은 다른 회원국에서 일하거나 공부하기 쉬워졌다. 교환 학생 제도로 다른 나라 대학에서 공부하는 학생도 많다.\n\n통합에는 어려움도 따른다. 회원국 사이의 경제 격차가 커서 소득이 높은 나라로 노동자가 몰린다. 2010년대에는 그리스 등에서 재정 위기가 발생해 회원국 사이에 부담을 둘러싼 갈등이 생겼다. 난민 수용 문제를 두고도 의견이 엇갈렸다."},{"title":"분리의 움직임과 그 영향","text":"통합과 함께 분리의 움직임도 나타난다. 영국은 2016년 국민 투표를 거쳐 2020년 유럽연합을 탈퇴했다. 이를 브렉시트라고 한다. 탈퇴를 지지한 쪽은 이민 관리와 국가 결정권 회복을 강조했다. 반대한 쪽은 무역·일자리·이동의 자유가 줄어드는 손해를 우려했다. 탈퇴 뒤 영국과 유럽연합 사이에는 통관 절차가 생기는 등 주민 생활에 변화가 나타났다.\n\n한 나라 안에서 분리 독립을 요구하는 지역도 있다. 스페인의 카탈루냐는 고유한 언어와 문화, 경제적 이해관계를 바탕으로 독립 요구가 이어져 왔다. 영국의 스코틀랜드는 2014년 독립 주민 투표를 했으나 반대가 더 많았다. 언어·민족·경제력 같은 지역 간 역학 관계가 통합과 분리를 함께 움직인다."}],"concepts":[{"term":"유럽연합(EU)","desc":"1993년 출범한 유럽 국가들의 정치·경제 공동체. 단일 시장을 이루고 공동 정책을 펼친다."},{"term":"솅겐 협정","desc":"가입국 사이의 국경 검문을 없애 사람들이 자유롭게 이동할 수 있게 한 협정."},{"term":"유로화","desc":"유럽연합의 여러 회원국이 함께 쓰는 단일 화폐."},{"term":"브렉시트","desc":"영국(Britain)과 탈퇴(exit)를 합친 말. 영국이 국민 투표를 거쳐 유럽연합을 탈퇴한 일."},{"term":"분리 독립 운동","desc":"한 나라 안의 지역이 언어·문화·경제적 차이 등을 이유로 독립된 나라가 되려는 움직임."}]}]},"s1-g04":{"title":"아프리카","lessons":[{"id":"s1-g04-1","title":"아프리카의 위치와 자연환경","standard":{"text":"다양한 지리 정보와 매체를 활용하여 아프리카의 국가와 주요 도시의 위치를 파악하고 자연환경의 특성을 지도로 표현한다."},"sections":[{"title":"아프리카의 위치와 국가·도시","text":"아프리카는 세계에서 두 번째로 큰 대륙이다. 적도가 대륙의 가운데를 지나서 북반구와 남반구에 걸쳐 있다. 북쪽은 지중해, 서쪽은 대서양, 동쪽은 인도양과 홍해에 닿아 있다. 북동쪽은 수에즈 운하를 사이에 두고 아시아와 나뉜다.\n\n아프리카에는 50개가 넘는 나라가 있다. 북부에는 이집트(카이로)·모로코(라바트)가 있다. 서부에는 나이지리아가 있으며, 수도는 아부자이고 최대 도시는 라고스다. 동부에는 케냐(나이로비)·에티오피아(아디스아바바)가 있다. 아디스아바바에는 아프리카 연합 본부가 있다. 중부에는 콩고 민주 공화국(킨샤사), 남부에는 남아프리카 공화국(행정 수도 프리토리아, 입법 수도 케이프타운)이 있다. 남아프리카 공화국의 최대 도시는 요하네스버그다."},{"title":"고원 대륙과 큰 하천","text":"아프리카는 대체로 해발 고도가 높은 고원으로 이루어져 있고, 해안 평야는 좁다. 동부에는 땅이 갈라지며 생긴 길고 깊은 골짜기인 동아프리카 지구대가 있다. 이 주변에 아프리카에서 가장 높은 킬리만자로산과 큰 호수인 빅토리아호가 있다.\n\n나일강은 세계에서 가장 긴 강 가운데 하나로, 사막을 지나 지중해로 흘러간다. 콩고강과 니제르강도 큰 하천이다. 그러나 고원에서 해안으로 내려가는 곳에 폭포와 급류가 많아 배가 내륙 깊이 들어가기 어렵다.\n\n북부에는 세계에서 가장 넓은 열대 사막인 사하라 사막이 있다. 사막 곳곳의 오아시스와 나일강 주변에는 예로부터 사람들이 모여 살았다."},{"title":"적도를 중심으로 대칭을 이루는 기후","text":"아프리카의 기후는 적도를 중심으로 남북이 거의 대칭을 이룬다. 적도 부근의 콩고 분지에는 일 년 내내 덥고 비가 많은 열대 우림 기후가 나타난다. 그 남북에는 우기와 건기가 뚜렷한 사바나 기후가 펼쳐져 키 큰 풀과 드문드문한 나무 사이로 야생 동물이 산다.\n\n더 바깥쪽에는 비가 적은 스텝과 사막이 나타난다. 북부의 사하라 사막, 남부의 칼라하리 사막과 나미브 사막이 대표적이다. 대륙의 북쪽 끝과 남쪽 끝에는 지중해성 기후가 나타난다.\n\n나이로비·아디스아바바처럼 적도 가까이 있어도 해발 고도가 높은 고원 도시는 일 년 내내 온화한 고산 기후가 나타난다."}],"concepts":[{"term":"열대 우림 기후","desc":"일 년 내내 기온이 높고 비가 많이 내리는 기후. 울창한 밀림이 나타난다."},{"term":"사바나 기후","desc":"우기와 건기가 뚜렷한 열대 기후. 키 큰 풀 사이에 나무가 드문드문 자라는 초원이 나타난다."},{"term":"고산 기후","desc":"적도 부근이라도 해발 고도가 높아 일 년 내내 봄처럼 온화한 기후."},{"term":"동아프리카 지구대","desc":"아프리카 동부에 땅이 갈라지며 생긴 길고 깊은 골짜기. 주변에 화산과 호수가 많다."},{"term":"사하라 사막","desc":"아프리카 북부에 펼쳐진 세계에서 가장 넓은 열대 사막."}]},{"id":"s1-g04-2","title":"문화와 지역 잠재력","standard":{"text":"아프리카의 지리적 특성에 기반한 다양한 문화와 지역 잠재력을 탐구하고, 아프리카에 대한 자신의 인식을 성찰한다."},"sections":[{"title":"자연환경과 역사가 만든 다양한 문화","text":"아프리카는 하나의 나라가 아니다. 50여 개 나라에 수많은 민족이 살며, 쓰이는 언어도 수천 개에 이른다. 문화는 크게 사하라 사막을 경계로 나누어 볼 수 있다. 북부 아프리카는 서남아시아와 교류가 활발해 이슬람교와 아랍어가 널리 퍼졌다. 건조한 환경에서 오아시스 농업과 유목이 이루어진다.\n\n사하라 이남 아프리카에는 여러 민족의 전통 신앙과 크리스트교·이슬람교가 함께 나타난다. 동부 해안에서는 아랍 상인과의 교류 속에 스와힐리어가 널리 쓰이게 되었다.\n\n유럽의 식민 지배는 큰 흔적을 남겼다. 많은 나라가 영어·프랑스어·포르투갈어를 공용어로 쓴다. 유럽 나라들이 경위선 등을 기준으로 그은 직선 국경은 민족 분포와 맞지 않아 갈등의 원인이 되기도 했다."},{"title":"아프리카의 지역 잠재력","text":"아프리카는 성장 가능성이 큰 대륙이다. 먼저 자원이 풍부하다. 나이지리아·알제리는 석유를, 남아프리카 공화국은 금을 생산한다. 콩고 민주 공화국은 배터리 원료인 코발트의 세계 최대 생산국이다.\n\n인구도 잠재력이다. 아프리카는 세계에서 가장 젊은 대륙이라 일할 사람과 소비 시장이 함께 커지고 있다. 햇빛이 강해 태양광 발전에 유리하다. 사파리 관광과 피라미드 같은 관광 자원도 있다.\n\n새로운 산업도 성장하고 있다. 케냐에서는 은행 계좌가 없어도 휴대 전화로 돈을 주고받는 모바일 금융 서비스가 널리 쓰인다. 아프리카 나라들은 대륙 전체를 하나의 시장으로 묶는 자유 무역 지대도 출범시켰다."},{"title":"아프리카에 대한 나의 인식 돌아보기","text":"많은 사람이 아프리카를 '덥고 가난하며 전쟁이 잦은 하나의 나라'처럼 떠올린다. 이는 고정 관념이다. 언론은 기아·분쟁 같은 문제 상황을 주로 보도하기 때문에, 그 장면만 보면 아프리카 전체가 그렇다고 생각하기 쉽다.\n\n실제 아프리카는 훨씬 다양하다. 고원 도시는 일 년 내내 온화하다. 라고스·나이로비·카이로 같은 대도시에는 고층 건물과 새로운 기업이 들어서 있다. 물론 빈곤과 분쟁도 일부 지역이 겪는 현실이다. 중요한 것은 어려움과 가능성을 함께 보는 균형 잡힌 시선이다. 내가 가진 이미지가 어디서 왔는지 돌아보는 것이 그 출발점이다."}],"concepts":[{"term":"사하라 이남 아프리카","desc":"사하라 사막 남쪽의 아프리카 지역. 북부 아프리카와 문화·민족 구성이 다르다."},{"term":"인위적 국경","desc":"자연 지형이나 민족 분포와 상관없이 경위선 등을 기준으로 정한 국경. 식민 지배 시기에 많이 생겼다."},{"term":"지역 잠재력","desc":"한 지역이 가진 자원·인구·자연환경·문화 등에서 비롯되는 발전 가능성."},{"term":"모바일 금융","desc":"휴대 전화로 송금·결제 등 금융 서비스를 이용하는 것. 은행이 적은 지역에서 특히 유용하다."},{"term":"고정 관념","desc":"어떤 대상에 대해 사실을 충분히 확인하지 않고 굳어진 생각이나 이미지."}]},{"id":"s1-g04-3","title":"지속가능한 발전과 협력","standard":{"text":"지속가능한 발전을 위한 아프리카 각 지역의 노력과 세계 다양한 주체들의 협력 사례를 조사하고, 세계시민으로서 우리가 참여할 수 있는 방안을 모색한다."},"sections":[{"title":"아프리카의 과제와 지속가능한 발전","text":"지속가능한 발전은 미래 세대가 쓸 자원과 환경을 해치지 않으면서 현재 세대의 필요를 채우는 발전이다. 경제 성장, 사회적 형평, 환경 보전이 조화를 이루어야 한다.\n\n아프리카의 여러 지역은 지속가능한 발전을 위해 풀어야 할 과제를 안고 있다. 사헬 지역에서는 가뭄과 과도한 방목·벌목으로 사막화가 진행되고 있다. 일부 지역은 빈곤·식량 부족·분쟁을 겪고, 학교와 병원 같은 기반 시설이 부족하다. 또 원자재 수출에 크게 의존하는 나라는 국제 가격이 떨어지면 경제가 흔들린다.\n\n국제 사회는 2015년 유엔에서 2030년까지 이룰 17개의 지속가능발전목표(SDGs)를 채택했다."},{"title":"아프리카 각 지역의 노력","text":"아프리카 나라들은 스스로 문제를 해결하기 위해 노력하고 있다. 사헬 지역의 여러 나라는 아프리카 연합과 함께 그레이트 그린 월 사업을 추진해 나무를 심고 땅을 되살리고 있다.\n\n르완다는 2008년 비닐봉지 사용을 금지하는 등 환경 정책을 강하게 펼쳐 왔다. 케냐는 동아프리카 지구대의 땅속 열을 이용하는 지열 발전을 키우고 있다. 모로코는 사막에 대규모 태양열 발전소를 세웠다.\n\n원자재를 그대로 수출하는 대신 가공해 부가 가치를 높이려는 노력도 이어진다. 아프리카 연합은 대륙의 장기 발전 계획인 '아젠다 2063'을 세워 함께 나아갈 방향을 정했다."},{"title":"세계의 협력과 우리의 참여","text":"아프리카의 지속가능한 발전에는 다양한 주체가 함께한다. 유엔 세계 식량 계획·유니세프 같은 국제기구는 식량과 보건을 지원한다. 각국 정부는 공적 개발 원조(ODA)를 제공한다. 우리나라는 한국 국제 협력단(KOICA)을 통해 교육·보건·농업 사업을 펼친다. 비정부 기구(NGO)와 기업도 현지 주민과 함께 사업을 벌인다.\n\n우리나라는 원조를 받던 나라에서 주는 나라로 바뀐 대표적 사례로, 2010년 경제 협력 개발 기구(OECD)의 개발 원조 위원회(DAC) 회원국이 되었다.\n\n좋은 협력은 현지 주민이 참여하고 스스로 일어설 힘을 키우는 방식이다. 우리도 공정 무역 제품을 고르고, 캠페인과 후원에 참여하고, 아프리카에 대한 바른 정보를 나누는 방식으로 함께할 수 있다."}],"concepts":[{"term":"지속가능한 발전","desc":"미래 세대의 필요를 해치지 않으면서 현재 세대의 필요를 채우는 발전. 경제·사회·환경의 조화를 추구한다."},{"term":"지속가능발전목표(SDGs)","desc":"2015년 유엔이 채택한 17개 목표. 2030년까지 빈곤 퇴치, 교육, 기후 대응 등을 이루고자 한다."},{"term":"사막화","desc":"가뭄과 과도한 방목·벌목 등으로 건조 지역의 땅이 사막처럼 황폐해지는 현상."},{"term":"공적 개발 원조(ODA)","desc":"정부와 공공 기관이 개발 도상국의 경제 발전과 복지 향상을 위해 제공하는 원조."},{"term":"공정 무역","desc":"생산자에게 정당한 대가를 지불하고 환경과 노동 조건을 고려해 거래하는 무역 방식."}]}]},"s1-g05":{"title":"아메리카","lessons":[{"id":"s1-g05-1","title":"아메리카의 위치와 자연환경","standard":{"text":"다양한 지리 정보와 매체를 활용하여 아메리카의 국가와 주요 도시의 위치를 파악하고 자연환경의 특성을 지도로 표현한다."},"sections":[{"title":"아메리카는 어디에 있을까","text":"아메리카는 서반구에 있는 대륙이다. 동쪽은 대서양, 서쪽은 태평양과 맞닿아 있다. 파나마 지협을 경계로 북아메리카와 남아메리카로 나눈다. 멕시코 남쪽부터 파나마까지와 카리브해의 섬들은 따로 중앙아메리카와 카리브 지역이라고 부르기도 한다.\n\n문화를 기준으로 나누기도 한다. 영어를 주로 쓰는 미국과 캐나다를 앵글로아메리카라고 한다. 에스파냐어와 포르투갈어를 주로 쓰는 멕시코 이남은 라틴아메리카라고 한다. 두 지역의 경계는 대체로 미국과 멕시코 사이를 흐르는 리오그란데강이다.\n\n주요 도시의 위치도 지도에서 확인해 두자. 북아메리카에는 뉴욕, 워싱턴 D.C., 로스앤젤레스, 토론토, 멕시코시티가 있다. 남아메리카에는 상파울루, 리우데자네이루, 부에노스아이레스, 리마, 보고타 등이 있다."},{"title":"서쪽은 높고 험하며 동쪽은 낮고 완만하다","text":"아메리카의 지형은 서쪽과 동쪽이 뚜렷하게 다르다. 서쪽에는 로키산맥과 안데스산맥이 남북으로 길게 뻗어 있다. 이 산맥들은 환태평양 조산대에 속해 높고 험하며, 지진과 화산 활동이 활발하다. 동쪽에는 오래전에 만들어져 낮고 완만한 애팔래치아산맥과 브라질 고원 등이 있다.\n\n산지 사이에는 넓은 평원과 큰 강이 있다. 북아메리카 중앙에는 그레이트플레인스와 프레리 같은 대평원이 펼쳐지고 미시시피강이 흐른다. 남아메리카에는 유역 면적이 세계에서 가장 넓은 아마존강이 흐르고, 그 남쪽에는 팜파스라는 온대 초원이 있다.\n\n이러한 지형은 사람들의 생활에 영향을 준다. 평원은 밀·옥수수 농사와 목축에 유리하다. 험한 산지는 교통이 불편하지만 광물 자원이 풍부하다."},{"title":"남북으로 길어서 기후가 다양하다","text":"아메리카는 북극해 연안부터 남위 50°가 넘는 곳까지 걸쳐 있다. 그래서 한대, 냉대, 온대, 건조, 열대 기후가 모두 나타난다. 캐나다 북부는 매우 춥고, 적도 부근 아마존 분지에는 열대 우림이 넓게 펼쳐진다.\n\n고도도 기후를 바꾼다. 높이 올라갈수록 기온이 낮아지기 때문에, 적도 가까운 안데스 고지대에는 연중 봄과 같은 고산 기후가 나타난다. 그래서 키토, 보고타, 라파스 같은 도시가 해발 2,000m가 넘는 고지대에 자리 잡았다.\n\n자연환경의 특성은 지도로 표현하면 한눈에 보인다. 높이는 색의 진하기로, 기후 지역은 정해진 색과 기호로 나타낸다. 이렇게 만든 지도는 사람들이 어디에 많이 모여 사는지 설명하는 데에도 도움이 된다."}],"concepts":[{"term":"앵글로아메리카와 라틴아메리카","desc":"언어와 문화를 기준으로 아메리카를 나눈 것이다. 영어권인 미국·캐나다를 앵글로아메리카, 에스파냐어·포르투갈어권인 멕시코 이남을 라틴아메리카라고 한다."},{"term":"환태평양 조산대","desc":"태평양 둘레를 따라 높은 산맥이 이어진 지역이다. 지진과 화산 활동이 활발하며 로키산맥과 안데스산맥이 여기에 속한다."},{"term":"아마존강","desc":"남아메리카 적도 부근을 흐르는 강으로 유역 면적이 세계에서 가장 넓다. 유역에는 열대 우림이 넓게 분포한다."},{"term":"고산 기후","desc":"적도 부근의 높은 지대에서 나타나는 기후로, 연중 봄처럼 서늘하다. 키토·보고타·라파스 같은 고산 도시가 발달했다."},{"term":"팜파스","desc":"아르헨티나를 중심으로 펼쳐진 온대 초원이다. 밀 재배와 소 방목이 활발하다."}]},{"id":"s1-g05-2","title":"인구 구성과 문화 혼종성","standard":{"text":"다양한 민족(인종)으로 구성된 아메리카의 인구 특징을 살펴보고, 사례를 들어 아메리카의 문화 혼종성을 설명한다."},"sections":[{"title":"여러 민족이 모여 이룬 인구","text":"아메리카의 인구는 원주민, 유럽계, 아프리카계, 아시아계로 이루어진다. 원주민은 유럽인이 오기 전부터 아메리카에 살던 사람들이다. 15세기 말 이후 유럽인이 들어와 식민지를 세우면서 인구 구성이 크게 바뀌었다.\n\n유럽인과 함께 들어온 전염병과 정복 전쟁으로 원주민 인구는 크게 줄었다. 유럽인은 부족한 노동력을 채우려고 아프리카 사람들을 강제로 끌고 와 노예로 부렸다. 이들은 사탕수수·목화 등을 대규모로 기르는 플랜테이션 농장에서 일했다. 19세기 이후에는 중국·일본 등 아시아에서도 노동자가 이주해 왔다.\n\n시간이 흐르며 여러 집단 사이에서 혼혈 인구도 늘었다. 유럽계와 원주민 사이의 혼혈 인구를 메스티소라고 부른다. 브라질과 카리브해 지역 등에는 유럽계와 아프리카계의 혼혈 인구도 많다."},{"title":"나라마다 인구 구성이 다른 이유","text":"아메리카 나라들은 인구 구성이 서로 다르다. 식민지 시기에 어느 나라가 지배했고, 어떤 사람들이 어디로 이주했는지가 달랐기 때문이다.\n\n미국과 캐나다에는 영국·프랑스 등 북서부 유럽 출신이 많이 이주했다. 그래서 유럽계 비율이 높고 영어를 주로 쓴다. 다만 캐나다 퀘벡주에서는 프랑스어를 주로 쓴다. 멕시코와 남아메리카 여러 나라는 에스파냐와 포르투갈의 지배를 받았다. 그래서 에스파냐어·포르투갈어와 가톨릭이 널리 퍼졌다.\n\n같은 라틴아메리카 안에서도 차이가 있다. 안데스 산지의 볼리비아·페루는 원주민 비율이 높다. 온대 초원이 넓은 아르헨티나·우루과이는 유럽계 비율이 높다. 플랜테이션이 발달했던 카리브해의 아이티·자메이카는 아프리카계 비율이 높고, 멕시코는 메스티소가 많다."},{"title":"섞여서 새로 태어난 문화","text":"문화 혼종성은 서로 다른 문화가 만나 섞이면서 새로운 문화가 생겨나는 것이다. 아메리카는 여러 민족이 함께 살아 온 덕분에 혼종 문화가 특히 풍부하다.\n\n음악이 대표적이다. 미국 남부 뉴올리언스에서 생겨난 재즈는 아프리카계의 리듬과 유럽의 악기·화음이 섞인 음악이다. 브라질의 삼바와 카니발에는 아프리카계 리듬과 포르투갈에서 전해진 가톨릭 축제 전통이 함께 담겨 있다. 아르헨티나 부에노스아이레스의 탱고도 유럽 이민자와 여러 집단의 음악이 섞여 탄생했다.\n\n종교와 음식에서도 혼종성을 볼 수 있다. 멕시코의 '망자의 날'은 원주민의 조상 숭배 전통과 가톨릭 기념일이 합쳐진 축제이다. 원주민이 기르던 옥수수·감자·고추는 유럽 요리와 만나 새로운 음식을 만들었다."}],"concepts":[{"term":"원주민","desc":"유럽인이 오기 전부터 아메리카에 살던 사람들이다. 안데스 산지와 멕시코 등에 많이 산다."},{"term":"플랜테이션","desc":"열대 지역에서 값싼 노동력으로 사탕수수·목화·커피 같은 작물을 대규모로 기르는 농업 방식이다. 아프리카계 인구가 아메리카에 많아진 배경이 되었다."},{"term":"메스티소","desc":"유럽계와 원주민 사이의 혼혈 인구이다. 멕시코 등 라틴아메리카에 많다."},{"term":"문화 혼종성","desc":"서로 다른 문화가 만나 섞이면서 새로운 문화가 만들어지는 성질이다. 재즈, 삼바, 망자의 날 등이 사례이다."}]},{"id":"s1-g05-3","title":"초국적 기업과 지역 변화","standard":{"text":"초국적 기업의 글로벌 생산체제에 대한 이해를 바탕으로, 초국적 기업의 아메리카 지역 내 입지와 해외 이전의 이유, 그에 따른 해당 지역의 변화를 분석한다."},"sections":[{"title":"초국적 기업과 글로벌 생산 체제","text":"초국적 기업은 여러 나라에 회사와 공장을 두고 국경을 넘어 생산과 판매를 하는 기업이다. 교통과 통신이 발달하고 무역 장벽이 낮아지면서 초국적 기업이 크게 늘었다.\n\n초국적 기업은 기능에 따라 입지를 다르게 정한다. 본사는 자본과 정보가 모이는 선진국 대도시에 둔다. 연구소는 대학과 우수한 인력이 많은 곳에 둔다. 생산 공장은 임금과 땅값이 싸거나 판매 시장과 가까운 곳에 둔다.\n\n이처럼 한 제품의 기획·연구·생산·판매가 여러 나라에 나뉘어 이루어지는 구조를 글로벌 생산 체제라고 한다. 우리가 쓰는 휴대 전화나 운동화도 설계한 나라와 만든 나라가 다른 경우가 많다."},{"title":"아메리카에서 기업은 어디에 자리 잡을까","text":"미국은 많은 초국적 기업의 본사가 있는 나라이다. 뉴욕에는 금융 기업의 본사가, 캘리포니아의 실리콘밸리에는 정보 통신 기업의 본사와 연구소가 모여 있다. 대학과 연구 기관, 투자 자본이 함께 모여 있기 때문이다.\n\n공장은 생산비가 싼 곳으로 옮겨 가는 경우가 많다. 멕시코 북부의 미국 국경 지역에는 마킬라도라라고 불리는 조립 공장이 많다. 임금이 미국보다 낮고, 미국 시장과 가까워 운송비가 적게 든다. 미국·멕시코·캐나다가 맺은 자유 무역 협정으로 관세 부담이 줄어든 것도 공장 이전을 부추겼다.\n\n남아메리카에는 광산과 대규모 농장을 개발하는 기업이 많이 들어와 있다. 우리나라 자동차·전자 기업도 시장 가까이에서 생산하고 무역 장벽을 줄이려고 미국과 멕시코에 공장을 세웠다."},{"title":"기업이 오고 갈 때 지역은 어떻게 변할까","text":"초국적 기업의 공장이 들어온 지역은 일자리가 늘고 기술이 전해진다. 도로·항만 같은 기반 시설이 갖추어지고 도시가 성장하기도 한다. 멕시코 국경 도시들은 공장이 모이면서 인구가 크게 늘었다.\n\n하지만 문제도 생긴다. 이윤의 상당 부분이 본사가 있는 나라로 빠져나가고 환경 오염이 생길 수 있다. 낮은 임금과 열악한 노동 환경이 지적되기도 한다. 기업이 더 싼 곳을 찾아 다시 떠나면 일자리가 한꺼번에 사라질 수 있다.\n\n공장이 빠져나간 지역도 변화를 겪는다. 미국 오대호 주변의 디트로이트 등은 자동차 공업으로 번성했으나, 외국 자동차와의 경쟁, 공장의 해외·다른 지역 이전, 교외로의 인구 이동 등 여러 원인이 겹치면서 실업자가 늘고 인구가 크게 줄었다. 이런 지역을 녹슨 공업 지대라는 뜻으로 러스트 벨트라고 부른다."}],"concepts":[{"term":"초국적 기업","desc":"둘 이상의 나라에 회사·공장을 두고 국경을 넘어 생산과 판매를 하는 기업이다."},{"term":"글로벌 생산 체제","desc":"한 제품의 기획·연구·생산·판매를 여러 나라에 나누어 맡기는 구조이다. 공간적 분업이라고도 한다."},{"term":"마킬라도라","desc":"멕시코 북부 미국 국경 지역에 있는 수출용 조립 공장이다. 낮은 임금과 미국 시장과의 근접성을 이용한다."},{"term":"러스트 벨트","desc":"제조업이 쇠퇴한 미국 오대호 주변의 공업 지역을 '녹슨 지대'라는 뜻으로 부르는 말이다."},{"term":"자유 무역 협정","desc":"나라 사이에 관세 등 무역 장벽을 줄이거나 없애기로 한 약속이다. 기업이 공장을 옮기는 데 영향을 준다."}]}]},"s1-g06":{"title":"오세아니아와 극지방","lessons":[{"id":"s1-g06-1","title":"오세아니아와 자원 연계","standard":{"text":"다양한 지리 정보와 매체를 활용하여 오세아니아의 국가와 주요 도시의 위치, 자연환경의 특성을 파악하고, 자원 수출을 중심으로 세계 다른 지역과의 상호연계성을 탐색한다."},"sections":[{"title":"오세아니아의 위치와 나라들","text":"오세아니아는 오스트레일리아 대륙과 뉴질랜드, 태평양의 많은 섬으로 이루어진 지역이다. 대부분 남반구에 있어서 우리나라와 계절이 반대이다. 우리가 겨울일 때 오스트레일리아는 여름이다.\n\n오스트레일리아는 대륙 하나가 한 나라를 이룬다. 수도는 캔버라이고, 시드니·멜버른·브리즈번 같은 큰 도시는 대부분 남동부 해안에 있다. 서부에는 퍼스가 있다. 뉴질랜드는 북섬과 남섬으로 이루어지며 수도는 웰링턴, 가장 큰 도시는 오클랜드이다.\n\n태평양의 섬들은 위치와 문화에 따라 멜라네시아, 미크로네시아, 폴리네시아로 나눈다. 파푸아뉴기니, 피지, 투발루 등 많은 섬나라가 있다."},{"title":"건조한 대륙과 온화한 섬","text":"오스트레일리아는 대륙의 많은 부분이 사막과 초원인 건조한 대륙이다. 내륙은 비가 적어 사람이 거의 살지 않는다. 동쪽 해안을 따라 그레이트디바이딩산맥이 뻗어 있고, 남동부 해안은 기후가 온화하고 비가 알맞게 내린다. 그래서 인구와 도시가 남동부 해안에 모여 있다.\n\n뉴질랜드는 대부분 편서풍의 영향으로 연중 기온과 강수가 고른 서안 해양성 기후가 나타난다. 화산과 온천, 빙하 지형이 함께 있다. 풀이 잘 자라 양과 소를 기르는 목축업이 발달했다.\n\n태평양의 섬은 화산섬과 산호초 섬이 많다. 열대 기후가 나타나며 관광업과 어업이 중요하다. 산호초 섬은 해발 고도가 낮아 해수면 상승에 취약하다."},{"title":"자원으로 세계와 연결되다","text":"오스트레일리아는 철광석, 석탄, 천연가스 같은 지하자원이 풍부하다. 북서부에서는 철광석, 동부에서는 석탄이 많이 난다. 땅 위에서 바로 파 들어가는 노천 채굴이 많아 생산비가 적게 든다.\n\n과거 오스트레일리아의 주요 무역 상대는 영국이었다. 영국의 식민지였기 때문이다. 오늘날에는 중국, 일본, 우리나라 등 가까운 아시아 나라들로 자원을 많이 수출한다. 아시아의 공업이 성장하면서 자원 수요가 크게 늘었기 때문이다.\n\n우리나라도 제철소와 발전소에 필요한 철광석·석탄과 천연가스를 오스트레일리아에서 많이 수입한다. 뉴질랜드에서는 유제품과 육류, 키위 같은 농산물을 들여온다. 이처럼 오세아니아는 자원과 농산물 수출을 통해 아시아와 긴밀하게 연결되어 있다."}],"concepts":[{"term":"남반구","desc":"적도의 남쪽 지역이다. 북반구와 계절이 반대여서 우리나라가 겨울일 때 오스트레일리아는 여름이다."},{"term":"서안 해양성 기후","desc":"편서풍의 영향으로 연중 기온 차가 작고 비가 고르게 내리는 기후이다. 뉴질랜드에서 목초지가 잘 발달하는 배경이다."},{"term":"노천 채굴","desc":"지하자원을 땅 위에서 바로 파 들어가 캐내는 방법이다. 갱도를 파는 방식보다 생산비가 적게 든다."},{"term":"상호 연계성","desc":"지역들이 자원·상품·사람의 이동을 통해 서로 영향을 주고받으며 연결되어 있는 성질이다."}]},{"id":"s1-g06-2","title":"태평양의 환경 문제","standard":{"text":"태평양 지역이 겪고 있는 환경 문제를 조사하고 그 해결에 참여할 수 있는 방안을 제안한다."},"sections":[{"title":"가라앉는 섬나라: 해수면 상승","text":"지구 온난화로 해수면이 높아지고 있다. 바닷물이 따뜻해지면 부피가 늘어나고, 육지의 빙하가 녹은 물이 바다로 흘러들기 때문이다.\n\n태평양의 투발루, 키리바시, 마셜 제도 같은 나라는 산호초로 이루어진 낮은 섬이 많다. 국토 대부분이 해발 고도 몇 m에 불과하다. 해수면이 높아지면 해안이 깎이고 바닷물이 넘쳐 들어온다. 땅속으로 바닷물이 스며들어 지하수가 짜지고 농작물이 자라기 어려워진다.\n\n이 때문에 살던 곳을 떠나 다른 나라로 옮겨 가는 사람들도 생겨났다. 기후 변화로 삶의 터전을 잃은 사람들을 기후 난민이라고 부른다. 섬나라들은 국제 사회에 온실가스 감축과 지원을 적극적으로 요구하고 있다."},{"title":"쓰레기와 뜨거워진 바다","text":"태평양에는 해류를 따라 떠다니던 쓰레기가 한곳에 모인 거대한 쓰레기 지대가 있다. 대표적으로 하와이와 미국 캘리포니아 사이의 북태평양에 넓게 형성되어 있다. 쓰레기의 대부분은 잘 썩지 않는 플라스틱이다.\n\n플라스틱은 햇빛과 파도에 부서져 아주 작은 미세 플라스틱이 된다. 바다 생물이 이를 먹이로 착각해 먹고, 먹이 사슬을 따라 사람의 식탁까지 돌아올 수 있다. 버려진 그물에 바다거북이나 물개가 걸려 다치기도 한다.\n\n바닷물 온도가 오르는 것도 문제이다. 수온이 높아지면 산호가 몸속에 함께 사는 조류를 잃고 하얗게 변하는 백화 현상이 일어난다. 오스트레일리아의 그레이트배리어리프에서도 백화 현상이 여러 차례 나타났다. 산호초가 죽으면 그곳에 기대어 사는 많은 바다 생물도 함께 줄어든다."},{"title":"해결을 위해 우리가 할 수 있는 일","text":"태평양의 환경 문제는 한 나라의 힘만으로 해결하기 어렵다. 해류와 대기는 국경을 가리지 않기 때문이다. 그래서 국제 협력이 필요하다. 세계 여러 나라는 2015년 파리 협정을 맺어 지구 평균 기온 상승을 산업화 이전보다 2℃보다 훨씬 낮게 억제하기로 약속했다. 태평양 섬나라들도 지역 협의체를 통해 함께 목소리를 내고 있다.\n\n정부와 기업은 온실가스 배출과 플라스틱 사용을 줄이는 제도를 만든다. 재생 에너지를 늘리고 재활용 체계를 갖추는 것도 중요하다.\n\n개인도 해결에 참여할 수 있다. 일회용 컵과 비닐봉지 사용을 줄이고 분리배출을 바르게 한다. 전기를 아껴 온실가스 배출을 줄인다. 해변 정화 활동이나 환경 캠페인에 참여하고, 알게 된 문제를 주변에 알리는 것도 좋은 방법이다."}],"concepts":[{"term":"해수면 상승","desc":"바닷물의 열팽창과 육지 빙하의 융해로 바다 수면이 높아지는 현상이다. 해발 고도가 낮은 섬나라에 큰 피해를 준다."},{"term":"기후 난민","desc":"해수면 상승, 가뭄 등 기후 변화로 살던 곳을 떠나야 하는 사람들이다."},{"term":"미세 플라스틱","desc":"크기가 5mm보다 작은 플라스틱 조각이다. 바다 생물이 먹고 먹이 사슬을 따라 이동한다."},{"term":"산호 백화 현상","desc":"수온 상승 등으로 산호가 함께 사는 조류를 잃고 하얗게 변하는 현상이다. 오래 지속되면 산호가 죽는다."},{"term":"파리 협정","desc":"2015년 채택된 기후 변화 대응 국제 협약이다. 모든 당사국이 온실가스 감축 목표를 스스로 정해 실천한다."}]},{"id":"s1-g06-3","title":"극지방 개발과 이해관계","standard":{"text":"극지방의 지리적 중요성과 지역 개발을 둘러싼 다양한 이해관계를 살펴보고, 이에 대한 자신과 상대방의 의견을 비판적으로 검토한다."},"sections":[{"title":"북극과 남극은 어떻게 다를까","text":"극지방은 북극과 남극 주변의 추운 지역이다. 1년 내내 기온이 낮고 얼음과 눈으로 덮인 곳이 많다. 여름에는 해가 지지 않는 백야, 겨울에는 해가 뜨지 않는 극야가 나타난다.\n\n북극은 대부분 바다이다. 북극해가 가운데 있고 그 주변을 러시아, 캐나다, 미국, 노르웨이, 덴마크령 그린란드 등이 둘러싸고 있다. 이누이트 등 원주민이 오래전부터 사냥과 고기잡이를 하며 살아왔다.\n\n남극은 두꺼운 빙하로 덮인 대륙이다. 원래 살던 주민은 없고, 여러 나라의 과학 기지에서 연구원들이 머문다. 남극의 빙하에는 수십만 년 전의 공기가 갇혀 있어 과거 기후를 연구하는 귀한 자료가 된다."},{"title":"극지방이 중요해진 까닭","text":"극지방은 지구의 기후를 조절한다. 하얀 얼음은 햇빛을 반사해 지구가 지나치게 더워지는 것을 막는다. 극지방의 얼음이 줄면 햇빛을 더 많이 흡수해 온난화가 더 빨라질 수 있다.\n\n극지방에는 자원도 많다. 북극 주변에는 석유와 천연가스가 많이 묻혀 있을 것으로 예상된다. 남극 주변 바다에는 크릴 같은 수산 자원이 풍부하다.\n\n교통로로서의 가치도 커졌다. 북극 바다 얼음이 줄면서 여름철에 배가 다닐 수 있는 기간이 길어졌다. 북극 항로를 이용하면 동아시아에서 유럽까지 수에즈 운하를 거치는 항로보다 거리를 크게 줄일 수 있다. 그래서 북극 항로의 경제적 가치가 주목받고 있다."},{"title":"개발을 둘러싼 다양한 이해관계","text":"극지방 개발에는 여러 집단의 이해관계가 얽혀 있다. 북극 연안국은 주변 바다의 자원과 항로를 개발하려 한다. 항로를 이용하려는 나라와 해운 기업은 북극 항로를 반긴다. 반면 원주민은 사냥터와 전통 생활이 위협받는다고 걱정한다. 환경 단체는 기름 유출 사고와 생태계 파괴를 우려한다.\n\n남극은 남극 조약에 따라 관리된다. 이 조약은 남극을 평화적 목적과 과학 연구에 이용하고, 나라들의 영유권 주장을 동결하도록 정했다. 이후 맺은 환경 보호 의정서로 과학 연구 외의 광물 자원 개발도 금지되었다.\n\n우리나라는 남극에 세종 과학 기지와 장보고 과학 기지, 북극에 다산 과학 기지를 두고 연구한다. 극지방 개발에 대한 의견을 낼 때는 개발의 이익, 환경 보전, 원주민의 권리를 함께 따져야 한다. 내 주장과 상대 주장의 근거를 비교하며 비판적으로 검토하는 태도가 필요하다."}],"concepts":[{"term":"백야와 극야","desc":"극지방에서 여름에 해가 지지 않는 현상을 백야, 겨울에 해가 뜨지 않는 현상을 극야라고 한다."},{"term":"북극 항로","desc":"북극해를 지나 동아시아와 유럽을 잇는 바닷길이다. 수에즈 운하를 거치는 항로보다 거리가 짧다."},{"term":"남극 조약","desc":"남극을 평화적 목적과 과학 연구에 이용하고 영유권 주장을 동결하기로 한 국제 조약이다."},{"term":"극지 과학 기지","desc":"극지방의 기후·생태·지질을 연구하는 시설이다. 우리나라는 남극에 세종·장보고 기지, 북극에 다산 기지를 운영한다."}]}]},"s1-s01":{"title":"인간과 사회생활","lessons":[{"id":"s1-s01-1","title":"사회화와 자아 정체성","standard":{"text":"사회화의 의미를 일상생활의 사례를 들어 설명하고, 사회화 과정에서 형성되는 자아 정체성에 대해 성찰한다."},"sections":[{"title":"사회화란 무엇인가","text":"사회화는 개인이 사회 구성원으로 살아가는 데 필요한 언어, 지식, 규범, 가치 등을 배우는 과정이다. 사람은 태어날 때 말하는 법이나 인사하는 법을 알지 못한다. 다른 사람과 함께 지내면서 이것들을 하나씩 익힌다.\n\n사회화를 통해 개인은 사회에 적응하고 다른 사람과 원활하게 어울릴 수 있다. 사회 쪽에서 보면 사회화는 문화가 다음 세대로 전해지는 통로이다. 사회화가 없다면 사회의 질서와 문화가 이어지기 어렵다.\n\n사회화는 사람과 사람 사이의 상호 작용으로 이루어진다. 부모가 아이에게 인사법을 가르치고, 아이가 이를 따라 하며 칭찬을 받는 과정이 그 예이다. 사람은 이렇게 사회 속에서 비로소 사회적 존재가 된다."},{"title":"사회화는 어디서, 언제 일어나는가","text":"사회화가 일어나는 곳을 사회화 기관이라고 한다. 가족은 어린 시절 기본적인 생활 습관과 언어를 가르치는 가장 중요한 기관이다. 또래 집단은 친구 사이의 규칙과 유행을 익히게 한다. 학교는 지식과 규범을 체계적으로 가르치기 위해 만들어진 기관이다. 대중 매체도 생각과 행동에 큰 영향을 준다.\n\n사회화는 평생 이어진다. 청소년기에는 자신의 역할을 고민하며 사회화가 활발하게 일어난다. 성인이 되어 직장에 들어가거나 부모가 되면 새로운 역할을 배운다. 이미 배운 것을 버리고 새 환경에 맞게 다시 배우는 것을 재사회화라고 한다. 노인이 무인 주문기 사용법을 익히거나, 이주민이 새 나라의 언어를 배우는 것이 재사회화의 예이다."},{"title":"사회화와 자아 정체성","text":"자아 정체성은 '나는 누구인가'에 대한 일관된 생각이다. 나의 성격, 관심, 가치관, 소속에 대한 이해가 모여 자아 정체성을 이룬다. 자아 정체성은 혼자 만들어지지 않는다. 다른 사람의 반응과 기대를 경험하면서 나를 비추어 보는 사회화 과정 속에서 형성된다.\n\n청소년기는 자아 정체성이 본격적으로 형성되는 시기이다. 이 시기에는 진로, 친구 관계, 외모 등을 두고 고민이 많아진다. 다른 사람의 시선만 따르기보다 내가 무엇을 중요하게 여기는지 스스로 돌아보는 성찰이 필요하다. 건강한 자아 정체성은 자신을 존중하고 다른 사람과 바람직한 관계를 맺는 바탕이 된다."}],"concepts":[{"term":"사회화","desc":"개인이 사회 구성원으로 살아가는 데 필요한 언어, 지식, 규범, 가치 등을 배우는 과정이다."},{"term":"사회화 기관","desc":"사회화를 담당하는 집단이나 기관이다. 가족, 또래 집단, 학교, 대중 매체 등이 있다."},{"term":"재사회화","desc":"급격한 변화나 새로운 환경에 적응하기 위해 새로운 지식이나 규범을 다시 배우는 것이다."},{"term":"자아 정체성","desc":"'나는 누구인가'에 대해 스스로 가지는 일관된 인식이다."},{"term":"또래 집단","desc":"나이나 관심이 비슷한 친구들의 집단으로, 청소년기 사회화에 큰 영향을 준다."}]},{"id":"s1-s01-2","title":"지위와 역할, 역할 갈등","standard":{"text":"사회적 지위와 역할의 의미를 설명하고, 일상생활에서 나타나는 역할 갈등 사례와 대응 방안을 탐색한다."},"sections":[{"title":"지위와 역할의 의미","text":"지위는 한 개인이 집단이나 사회 안에서 차지하는 위치이다. 한 사람은 동시에 여러 지위를 가진다. 예를 들어 한 중학생은 학생이면서 딸이고, 동아리 부원이면서 누나일 수 있다.\n\n지위는 얻는 방식에 따라 나뉜다. 귀속 지위는 태어나면서 자연스럽게 주어지는 지위로, 딸이나 아들이 그 예이다. 성취 지위는 개인의 노력이나 능력으로 얻는 지위로, 반장이나 교사가 그 예이다. 전통 사회에서는 신분처럼 태어날 때 정해진 귀속 지위가 삶을 크게 좌우했다. 현대 사회에서는 교육과 직업을 통해 얻는 성취 지위의 중요성이 커지고 있다. 지위는 그 자체로 높고 낮음을 뜻하지 않으며, 사회 속에서 맡는 자리를 가리킨다."},{"title":"역할과 역할 행동","text":"역할은 어떤 지위에 있는 사람에게 사회가 기대하는 행동 방식이다. 학생에게는 수업에 성실히 참여하기를, 교사에게는 학생을 가르치기를 기대한다. 지위가 같으면 기대되는 역할도 대체로 같다.\n\n역할 행동은 개인이 실제로 그 역할을 수행하는 방식이다. 같은 반장이라도 어떤 반장은 친구들 의견을 꼼꼼히 듣고, 어떤 반장은 빠르게 결정을 내린다. 역할 행동은 사람마다 다르며, 역할을 잘 수행하면 칭찬 같은 보상을, 그렇지 못하면 비난 같은 제재를 받기도 한다. 보상과 제재는 사람들이 역할을 기대에 맞게 수행하도록 이끄는 역할을 한다. 또한 역할에 대한 기대는 시대에 따라 달라진다. 예전에는 집안일을 주로 어머니의 역할로 여겼지만, 오늘날에는 가족 구성원이 함께 나누어야 할 일로 보는 경우가 많다."},{"title":"역할 갈등과 대응 방안","text":"역할 갈등은 한 사람이 가진 여러 지위의 역할이 동시에 요구되어 충돌하는 상황이다. 회사원인 부모가 야근과 자녀의 학교 행사 사이에서 고민하는 경우가 대표적이다. 하나의 지위 안에서 서로 다른 기대가 부딪히는 경우도 있다. 담임 교사가 엄격한 지도와 따뜻한 상담을 동시에 요구받는 상황이 그 예이다.\n\n역할 갈등에 대응하려면 먼저 상황에서 무엇이 더 중요하고 급한지 우선순위를 정한다. 관련된 사람과 대화하여 이해를 구하거나 시간을 나누어 조정할 수도 있다. 사회 차원에서는 유연 근무제나 돌봄 서비스처럼 개인이 역할 갈등을 덜 겪도록 돕는 제도를 마련할 수 있다."}],"concepts":[{"term":"지위","desc":"개인이 집단이나 사회 안에서 차지하는 위치이다."},{"term":"귀속 지위","desc":"성별, 가족 관계처럼 태어나면서 자연스럽게 주어지는 지위이다."},{"term":"성취 지위","desc":"반장, 교사처럼 개인의 노력이나 능력으로 얻는 지위이다."},{"term":"역할","desc":"특정 지위에 있는 사람에게 사회가 기대하는 행동 방식이다."},{"term":"역할 갈등","desc":"한 사람에게 요구되는 역할들이 서로 충돌하여 겪는 심리적 갈등이다."}]},{"id":"s1-s01-3","title":"갈등과 차별","standard":{"text":"우리 사회에 나타나는 다양한 갈등과 차별의 사례를 조사하고, 이에 대처하는 시민의 자질에 대해 토의한다."},"sections":[{"title":"갈등과 차별의 의미","text":"사회 갈등은 개인이나 집단이 서로 다른 이해관계나 가치관 때문에 대립하는 상황이다. 갈등은 어느 사회에나 존재한다. 잘 해결하면 문제를 드러내고 제도를 개선하는 계기가 되지만, 방치하면 사회 통합을 해칠 수 있다.\n\n차별은 합리적인 이유 없이 성별, 나이, 장애, 출신 지역, 인종 등을 이유로 특정 사람이나 집단을 불리하게 대우하는 것이다. 차별은 인간의 존엄과 평등을 침해한다. 대한민국 헌법 제11조는 모든 국민이 법 앞에 평등하며 성별·종교 또는 사회적 신분에 의하여 차별받지 않는다고 규정한다. 다만 모든 구별이 차별인 것은 아니다. 직무 수행에 꼭 필요한 능력을 기준으로 사람을 고르는 것처럼 합리적 이유가 있는 구별은 차별로 보지 않는다."},{"title":"갈등과 차별은 왜 생기는가","text":"갈등은 한정된 자원을 나누는 과정에서 이해관계가 엇갈릴 때 자주 생긴다. 세대 사이의 일자리와 복지 문제, 지역 사이의 시설 유치 문제가 그 예이다. 가치관의 차이도 갈등을 낳는다. 같은 문제라도 무엇을 더 중요하게 여기는지가 다르기 때문이다.\n\n차별은 편견과 고정 관념에서 시작되는 경우가 많다. 고정 관념은 어떤 집단에 대해 지나치게 단순하게 굳어진 생각이다. 편견은 충분한 근거 없이 갖는 부정적 태도이다. 고정 관념과 편견이 행동으로 나타나면 차별이 된다. 의도가 없더라도 제도나 관행이 특정 집단에 불리하게 작용하면 차별이 될 수 있다."},{"title":"갈등과 차별에 대처하는 시민의 자질","text":"갈등을 해결하려면 대화와 타협이 필요하다. 상대의 입장을 끝까지 듣고, 서로 받아들일 수 있는 방안을 찾는 자세가 중요하다. 당사자끼리 해결이 어려우면 제3자의 조정이나 법적 절차를 이용할 수 있다.\n\n차별에 대처하려면 먼저 나에게 고정 관념이나 편견이 없는지 돌아보아야 한다. 다른 사람의 처지에서 생각하는 공감 능력과 모든 사람을 동등하게 대하는 인권 감수성이 필요하다. 차별을 보았을 때 문제를 제기하고, 국가인권위원회 같은 기관에 도움을 구하는 것도 시민의 역할이다. 사회 차원에서는 차별을 금지하는 법과 제도를 갖추어야 한다. 장애인이 시설을 불편 없이 이용하도록 돕는 편의 시설 설치도 그 예이다. 나와 다른 사람을 있는 그대로 인정하는 관용의 태도가 이 모든 노력의 바탕이다."}],"concepts":[{"term":"사회 갈등","desc":"개인이나 집단이 서로 다른 이해관계나 가치관 때문에 대립하는 상황이다."},{"term":"차별","desc":"합리적인 이유 없이 특정 개인이나 집단을 불리하게 대우하는 것이다."},{"term":"고정 관념","desc":"어떤 집단이나 대상에 대해 지나치게 단순화되어 굳어진 생각이다."},{"term":"편견","desc":"충분한 근거 없이 특정 대상에 대해 갖는 부정적인 태도나 생각이다."},{"term":"인권 감수성","desc":"일상의 상황에서 인권과 관련된 문제를 알아차리고 공감하는 능력이다."}]}]},"s1-s02":{"title":"다양한 문화의 이해","lessons":[{"id":"s1-s02-1","title":"문화의 의미와 특징","standard":{"text":"일상생활에서 접하는 문화의 사례를 탐색하고, 이를 바탕으로 문화의 의미와 특징을 도출한다."},"sections":[{"title":"문화란 무엇인가","text":"문화는 한 사회의 구성원들이 공유하는 생활 양식이다. 무엇을 먹고, 어떤 집에 살며, 어떻게 인사하는지가 모두 문화에 속한다. 언어, 종교, 예술, 법, 관습, 기술도 문화에 포함된다.\n\n일상에서는 '문화'를 좁은 의미로 쓰기도 한다. 미술관이나 공연장에 가는 것을 '문화생활'이라고 부르는 경우가 그 예이다. 또 세련되고 교양 있는 상태를 뜻하기도 한다. 사회 과목에서 말하는 문화는 넓은 의미로, 한 사회의 생활 양식 전체를 가리킨다.\n\n넓은 의미의 문화에는 높고 낮음이 없다. 배고플 때 먹는 것처럼 누구에게나 나타나는 본능은 문화가 아니다. 그러나 무엇을 어떤 방식으로 먹는지는 사회마다 다르므로 문화이다."},{"title":"문화의 특징","text":"문화에는 몇 가지 공통된 특징이 있다. 첫째, 공유성이다. 문화는 사회 구성원이 함께 가지는 것이어서 서로의 행동을 예측하고 소통할 수 있게 한다. 둘째, 학습성이다. 문화는 태어날 때부터 갖는 것이 아니라 사회화 과정에서 배운다.\n\n셋째, 축적성이다. 사람은 언어와 문자로 문화를 다음 세대에 전하고, 다음 세대는 여기에 새로운 것을 더한다. 넷째, 변동성이다. 문화는 새로운 발명이나 다른 문화와의 접촉으로 계속 변한다. 다섯째, 총체성이다. 문화의 각 요소는 서로 연결되어 있어 한 요소가 바뀌면 다른 요소도 함께 바뀐다.\n\n스마트폰의 보급을 생각해 보자. 스마트폰은 연락 방식뿐 아니라 쇼핑, 학습, 여가 생활까지 함께 바꾸었다. 이것은 문화의 변동성과 총체성을 잘 보여 준다."},{"title":"생활 속에서 문화 찾기: 전통 가옥","text":"세계 여러 지역의 전통 가옥은 문화가 자연환경과 생활에 맞추어 만들어졌음을 보여 준다. 덥고 비가 많은 동남아시아에서는 바닥을 땅에서 띄운 고상 가옥을 지어 습기와 해충을 피했다. 건조한 지역에서는 흙벽돌로 벽을 두껍게 쌓고 창을 작게 내어 한낮의 열기를 막았다.\n\n우리나라 전통 가옥에는 온돌과 대청마루가 함께 있다. 온돌은 추운 겨울을 나기 위한 난방 방식이다. 대청마루는 무더운 여름에 바람이 잘 통하게 한다. 사계절이 뚜렷한 기후에 적응한 결과이다.\n\n이처럼 문화는 사람들이 주어진 환경에서 더 잘 살기 위해 함께 만들어 온 결과물이다. 그래서 겉모습이 낯선 문화라도 그 사회의 환경과 역사 속에서 보면 이해할 수 있다."}],"concepts":[{"term":"문화","desc":"한 사회의 구성원들이 공유하는 생활 양식의 총체이다."},{"term":"공유성","desc":"문화는 사회 구성원이 함께 가지는 것으로, 서로의 행동을 예측하고 소통하게 한다."},{"term":"학습성","desc":"문화는 타고나는 것이 아니라 태어난 후 사회화 과정을 통해 배운다는 특징이다."},{"term":"축적성","desc":"문화가 언어와 문자를 통해 다음 세대로 전해지며 새로운 내용이 더해져 풍부해지는 특징이다."},{"term":"총체성","desc":"문화의 각 요소가 서로 긴밀하게 연결되어 하나의 전체를 이루는 특징이다."}]},{"id":"s1-s02-2","title":"미디어와 문화","standard":{"text":"우리 주변에서 활용되는 미디어들을 탐색하고, 미디어를 통해 경험하는 다양한 문화와 정보들을 비판적으로 검토한다."},"sections":[{"title":"미디어란 무엇인가","text":"미디어는 정보와 생각을 전달하는 수단이다. 신문, 잡지 같은 인쇄 매체와 텔레비전, 라디오 같은 방송 매체가 오래전부터 쓰였다. 오늘날에는 인터넷, 누리 소통망(SNS), 동영상 플랫폼 같은 뉴 미디어가 생활 깊숙이 자리 잡았다.\n\n뉴 미디어의 가장 큰 특징은 쌍방향성이다. 예전에는 소수의 언론사가 정보를 만들고 다수는 받기만 했다. 지금은 누구나 글이나 영상을 만들어 올리고 댓글로 반응할 수 있다. 정보를 만드는 사람과 받는 사람의 경계가 흐려진 것이다.\n\n미디어는 우리가 세상을 보는 창이다. 직접 가 보지 못한 곳의 소식과 다른 나라 사람들의 생활도 미디어를 통해 접한다."},{"title":"미디어로 경험하는 다양한 문화","text":"미디어는 문화가 퍼지는 속도를 크게 높였다. 다른 나라의 음악, 드라마, 음식, 놀이가 미디어를 통해 거의 실시간으로 전해진다. 우리나라의 대중문화가 세계 여러 나라에서 사랑받게 된 데에도 동영상 플랫폼과 누리 소통망의 역할이 컸다.\n\n미디어 덕분에 우리는 다양한 문화를 쉽게 경험하고 이해의 폭을 넓힐 수 있다. 서로 다른 문화가 만나 새로운 문화가 생겨나기도 한다. 그러나 미디어가 보여 주는 모습이 그 문화의 전부는 아니다. 미디어는 일부를 골라 강조하기 때문에, 특정 집단을 지나치게 단순하게 보여 주면 고정 관념이 생길 수 있다.\n\n또 많은 사람이 같은 콘텐츠를 즐기면서 문화가 서로 비슷해지는 획일화가 나타나기도 한다."},{"title":"미디어를 비판적으로 읽는 법","text":"미디어 리터러시는 미디어의 정보를 비판적으로 이해하고, 책임감 있게 활용하고 만드는 능력이다. 미디어의 정보에는 만든 사람의 관점과 목적이 담겨 있다. 같은 사건도 어떤 장면을 고르고 어떤 제목을 붙이느냐에 따라 다르게 전달된다.\n\n정보를 볼 때는 몇 가지를 확인한다. 누가 만들었는가, 출처와 근거가 분명한가, 다른 매체도 같은 내용을 전하는가, 광고나 홍보가 섞여 있지 않은가를 살핀다. 사실이 아닌 내용을 사실처럼 꾸민 허위 정보는 빠르게 퍼지므로, 공유하기 전에 한 번 더 확인해야 한다.\n\n추천 알고리즘에도 주의해야 한다. 내가 좋아하는 정보만 계속 보게 되면 생각이 한쪽으로 치우칠 수 있다. 일부러 다양한 관점의 정보를 찾아보는 습관이 필요하다."}],"concepts":[{"term":"미디어","desc":"정보와 생각을 전달하는 수단으로, 인쇄 매체·방송 매체·뉴 미디어 등이 있다."},{"term":"뉴 미디어","desc":"인터넷과 디지털 기술을 바탕으로 한 미디어로, 누구나 정보를 생산하고 주고받는 쌍방향성이 특징이다."},{"term":"미디어 리터러시","desc":"미디어의 정보를 비판적으로 이해하고 책임감 있게 활용하며 만드는 능력이다."},{"term":"허위 정보","desc":"사실이 아닌 내용을 사실인 것처럼 꾸며 퍼뜨리는 정보이다."},{"term":"추천 알고리즘","desc":"사용자의 이용 기록을 분석해 관심 있을 만한 콘텐츠를 골라 보여 주는 방식이다."}]},{"id":"s1-s02-3","title":"문화를 이해하는 태도","standard":{"text":"여러 집단에서 나타나는 다양한 문화 사례들을 조사하고, 문화를 이해하는 바람직한 태도에 대하여 토의한다."},"sections":[{"title":"여러 집단의 다양한 문화","text":"문화는 나라마다 다를 뿐 아니라 한 사회 안에서도 집단에 따라 다르다. 세대에 따라 즐기는 음악과 말투가 다르고, 지역에 따라 사투리와 음식이 다르다. 청소년, 특정 직업 집단, 취미 동호회도 저마다 고유한 문화를 가진다.\n\n한 사회에서 다수가 공유하는 문화를 주류 문화라 한다. 사회 안의 특정 집단이 가진 고유한 문화를 하위문화라 한다. 하위문화는 사회 전체의 문화를 다양하고 풍부하게 만든다. 또 주류 문화에 새로운 활력을 주기도 한다.\n\n우리 사회에는 다른 나라에서 온 이주민도 함께 살고 있다. 서로 다른 문화를 가진 사람들이 어울려 사는 다문화 사회에서는 다른 문화를 이해하는 태도가 더욱 중요하다."},{"title":"문화를 바라보는 여러 태도","text":"자문화 중심주의는 자기 문화만 우월하다고 여기고 다른 문화를 낮추어 보는 태도이다. 구성원의 결속을 높일 수는 있다. 그러나 다른 문화를 무시하여 갈등을 낳고, 자기 문화의 발전 기회도 놓치기 쉽다.\n\n문화 사대주의는 다른 사회의 문화가 우월하다고 믿고 자기 문화를 낮추어 보는 태도이다. 다른 문화를 쉽게 받아들일 수 있지만, 자기 문화의 정체성을 잃을 위험이 있다.\n\n문화 상대주의는 각 문화를 그 사회의 자연환경과 역사적 맥락 속에서 이해하려는 태도이다. 어떤 문화가 낯설어도 그것이 생겨난 이유를 먼저 살핀다. 문화 상대주의는 다른 문화를 이해하는 바람직한 태도로 여겨진다."},{"title":"바람직한 태도와 그 한계","text":"문화 상대주의에도 한계가 있다. 인간의 생명과 존엄성을 해치는 관습까지 '그 사회의 문화'라는 이유로 인정해서는 안 된다. 이처럼 모든 문화를 무조건 옳다고 보는 태도를 극단적 문화 상대주의라고 한다. 다른 문화를 이해하되 인권, 생명 존중 같은 보편적 가치에 비추어 성찰해야 한다.\n\n일상에서 바람직한 태도를 실천하는 방법은 어렵지 않다. 낯선 음식이나 옷차림을 보고 바로 '이상하다'고 판단하지 않는다. 대신 '왜 그렇게 할까'를 먼저 질문한다. 다른 문화를 가진 친구의 이야기를 귀 기울여 듣는다.\n\n우리 문화를 소중히 여기면서 다른 문화도 존중하는 태도가 필요하다. 이러한 태도는 다문화 사회에서 갈등을 줄이고 함께 살아가는 바탕이 된다."}],"concepts":[{"term":"하위문화","desc":"한 사회 안의 특정 집단이 공유하는 고유한 문화이다."},{"term":"자문화 중심주의","desc":"자기 문화만 우월하다고 여기고 다른 문화를 낮추어 보는 태도이다."},{"term":"문화 사대주의","desc":"다른 사회의 문화가 우월하다고 믿고 자기 문화를 낮추어 보는 태도이다."},{"term":"문화 상대주의","desc":"각 문화를 그 사회의 환경과 역사적 맥락 속에서 이해하려는 태도이다."},{"term":"극단적 문화 상대주의","desc":"인간의 존엄성 같은 보편적 가치를 해치는 관습까지 문화라는 이유로 인정하는 태도이다."}]}]},"s1-s03":{"title":"민주주의와 시민","lessons":[{"id":"s1-s03-1","title":"정치의 역할과 민주주의","standard":{"text":"공동체 생활에 필요한 정치의 역할을 탐색하고, 다양한 정치 사례를 통해 민주주의의 의미와 필요성을 도출한다."},"sections":[{"title":"정치란 무엇인가","text":"정치는 좁은 의미와 넓은 의미로 나누어 볼 수 있다. 좁은 의미의 정치는 국가 기관이 정치권력을 얻고 행사하는 활동이다. 국회가 법을 만들고 정부가 정책을 집행하며 선거로 대표를 뽑는 일이 여기에 해당한다.\n\n넓은 의미의 정치는 사회 구성원들 사이의 의견 차이와 갈등을 조정하여 공동의 문제를 해결하는 모든 활동이다. 학급 회의에서 체육 대회 종목을 정하거나 아파트 주민들이 주차 규칙을 정하는 일도 넓은 의미의 정치이다.\n\n현대 사회는 구성원이 많고 이해관계가 복잡하다. 그래서 국가 기관뿐 아니라 일상의 여러 집단에서 일어나는 결정 과정도 정치로 보는 넓은 의미가 널리 쓰인다."},{"title":"공동체에서 정치가 하는 역할","text":"사람들이 함께 살면 생각과 이익이 부딪치는 일이 생긴다. 정치는 이러한 갈등을 대화와 타협, 정해진 절차를 통해 조정한다. 갈등이 폭력이 아닌 평화적 방법으로 해결되도록 하는 것이 정치의 중요한 역할이다.\n\n정치는 사회 질서를 유지한다. 모두가 지켜야 할 규칙을 정하고, 그 규칙에 따라 공동체가 안정적으로 운영되게 한다. 또 정치는 공동의 목표를 정하고 이를 이루기 위해 자원을 나눈다. 예산을 어디에 먼저 쓸지 정하는 일이 대표적이다.\n\n결국 정치는 서로 다른 사람들이 하나의 공동체로 살아갈 수 있게 하는 활동이다. 정치가 제대로 작동하지 않으면 갈등이 커지고 공동의 문제가 해결되지 못한 채 남는다."},{"title":"민주주의의 의미와 필요성","text":"민주주의는 국민이 나라의 주인이 되어 스스로 다스리는 정치 형태이다. '민주주의(democracy)'라는 말은 고대 그리스어로 '민중'과 '지배'를 뜻하는 말이 합쳐져 생겼다. 대한민국 헌법 제1조 제2항은 '대한민국의 주권은 국민에게 있고, 모든 권력은 국민으로부터 나온다'고 밝히고 있다.\n\n정치 사례를 비교하면 민주주의가 왜 필요한지 알 수 있다. 한 사람이나 소수가 모든 결정을 내리면 결정은 빠를 수 있다. 그러나 권력이 함부로 쓰여도 막을 방법이 없고 다수의 의견이 무시되기 쉽다. 민주주의에서는 구성원이 결정에 참여하고 권력을 감시할 수 있다.\n\n민주주의는 구성원 모두를 존엄한 존재로 대하는 정치 형태이다. 결정에 시간이 걸리더라도 여러 의견을 듣고 정당한 절차를 거친다는 점에서 의미가 크다."}],"concepts":[{"term":"정치(좁은 의미)","desc":"국가 기관이 정치권력을 얻고 유지하며 행사하는 활동이다."},{"term":"정치(넓은 의미)","desc":"사회 구성원 사이의 의견 차이와 갈등을 조정하여 공동의 문제를 해결하는 모든 활동이다."},{"term":"민주주의","desc":"국민이 나라의 주인으로서 정치에 참여하고 스스로 다스리는 정치 형태이다."},{"term":"주권","desc":"국가의 의사를 최종적으로 결정하는 최고의 권력이다. 우리 헌법은 주권이 국민에게 있다고 규정한다."}]},{"id":"s1-s03-2","title":"민주주의의 발전과 원리","standard":{"text":"민주주의의 발전 과정을 검토하고, 이를 토대로 민주주의의 이념과 기본 원리를 도출한다."},"sections":[{"title":"민주주의의 발전 과정","text":"민주주의는 고대 그리스 아테네에서 시작되었다. 아테네 시민들은 민회에 직접 모여 나라의 중요한 일을 토론하고 결정했다. 많은 공직자를 추첨으로 뽑아 시민이 돌아가며 맡게 했다. 그러나 참여할 수 있는 사람은 성인 남성 시민뿐이었고 여성, 노예, 외국인은 제외되었다.\n\n근대에 들어 시민 혁명이 민주주의의 바탕을 다졌다. 영국의 명예혁명(1688), 미국 독립 혁명(1776), 프랑스 혁명(1789)을 거치며 시민들은 왕의 절대 권력에 맞서 자유와 권리를 얻었다. 이 시기 사회 계약설과 천부 인권 사상이 혁명의 사상적 바탕이 되었다.\n\n시민 혁명 직후에도 선거권은 재산을 가진 남성에게만 주어졌다. 노동자의 선거권 요구 운동과 여성 참정권 운동을 거치며 일정한 나이가 되면 누구나 투표하는 보통 선거가 자리 잡았다. 이렇게 현대 민주주의가 확립되었다."},{"title":"민주주의의 이념","text":"민주주의가 궁극적으로 추구하는 가치를 민주주의의 이념이라 한다. 그 근본은 인간의 존엄성이다. 모든 사람은 인간이라는 이유만으로 존엄한 존재로 대우받아야 한다는 생각이다.\n\n인간의 존엄성을 실현하려면 자유와 평등이 보장되어야 한다. 자유는 다른 사람이나 국가의 부당한 간섭을 받지 않고 스스로 결정하고 행동하는 것이다. 다만 자유는 다른 사람의 자유를 침해하지 않는 범위에서 누려야 한다.\n\n평등은 모든 사람을 성별, 신분, 재산 등으로 부당하게 차별하지 않는 것이다. 처음에는 법 앞의 평등과 같은 형식적 평등이 강조되었다. 오늘날에는 사회적 약자도 실제로 동등한 기회를 누리도록 배려하는 실질적 평등도 중요하게 여긴다."},{"title":"민주주의의 기본 원리","text":"민주주의의 이념을 실제 정치에서 실현하기 위한 원칙을 기본 원리라 한다. 첫째, 국민 주권의 원리이다. 나라의 최종 결정권은 국민에게 있다. 둘째, 국민 자치의 원리이다. 국민이 스스로 나라를 다스린다는 것으로, 오늘날에는 주로 대표를 뽑아 정치를 맡기는 대의제로 실현된다.\n\n셋째, 입헌주의의 원리이다. 국가 권력은 헌법과 법에 따라 행사되어야 한다. 이로써 권력이 함부로 쓰이는 것을 막고 국민의 기본권을 지킨다. 넷째, 권력 분립의 원리이다. 국가 권력을 입법, 행정, 사법으로 나누어 서로 견제하고 균형을 이루게 한다.\n\n우리나라도 국회, 정부, 법원이 각각 입법, 행정, 사법을 맡는다. 한 기관이 모든 권력을 가지면 독재로 흐를 위험이 크기 때문이다."}],"concepts":[{"term":"직접 민주 정치","desc":"시민이 직접 모여 나라의 중요한 일을 토론하고 결정하는 정치 방식이다. 고대 아테네의 민회가 대표적이다."},{"term":"시민 혁명","desc":"근대에 시민들이 절대 왕정에 맞서 자유와 권리를 쟁취한 혁명이다. 영국 명예혁명, 미국 독립 혁명, 프랑스 혁명 등이 있다."},{"term":"인간의 존엄성","desc":"모든 사람이 인간이라는 이유만으로 존중받아야 한다는 민주주의의 근본 이념이다."},{"term":"입헌주의","desc":"국가 권력이 헌법과 법에 따라 행사되어야 한다는 원리이다."},{"term":"권력 분립","desc":"국가 권력을 입법·행정·사법으로 나누어 서로 견제하고 균형을 이루게 하는 원리이다."}]},{"id":"s1-s03-3","title":"현대 민주주의의 과제","standard":{"text":"현대 민주주의의 특징과 과제를 검토하고, 우리나라 민주주의의 발전을 위한 제도적 방안과 시민의 역할에 대해 토의한다."},"sections":[{"title":"현대 민주주의의 특징","text":"현대 국가는 인구가 많고 영토가 넓다. 국민 모두가 한자리에 모여 모든 일을 직접 결정하기는 어렵다. 그래서 현대 민주주의는 주로 대의 민주주의로 운영된다. 대의 민주주의는 국민이 선거로 대표를 뽑고, 그 대표가 국민을 대신해 결정하는 방식이다.\n\n대의 민주주의에서는 대표가 전문성을 가지고 복잡한 문제를 효율적으로 다룰 수 있다. 선거로 대표를 정기적으로 다시 뽑기 때문에 국민은 대표에게 책임을 물을 수 있다.\n\n현대 민주주의는 또 보통 선거를 바탕으로 한다. 일정한 나이가 된 국민은 재산이나 성별과 관계없이 누구나 투표할 수 있다. 다양한 의견을 가진 시민과 단체가 자유롭게 활동하는 것도 현대 민주주의의 특징이다."},{"title":"현대 민주주의가 마주한 과제","text":"대의 민주주의에도 한계가 있다. 대표가 국민의 뜻과 다르게 결정하거나 일부 집단의 이익만 대변할 수 있다. 선거와 선거 사이에는 국민의 목소리가 정치에 잘 전달되지 않기도 한다.\n\n정치 무관심도 과제이다. 정치에 관심을 잃은 사람이 많아지면 투표율이 낮아진다. 그러면 소수의 의견만으로 대표가 정해져 대표의 정당성이 약해질 수 있다.\n\n사회 갈등과 정보 문제도 있다. 의견이 다른 집단이 서로를 적으로 보면 대화와 타협이 어려워진다. 허위 정보가 빠르게 퍼지면 시민이 올바른 판단을 내리기 어려워진다. 이런 문제를 방치하면 민주주의에 대한 신뢰가 떨어진다."},{"title":"우리 민주주의를 위한 제도와 시민의 역할","text":"우리나라 민주주의는 시민의 노력으로 발전해 왔다. 4·19 혁명(1960), 5·18 민주화 운동(1980), 6월 민주 항쟁(1987)을 거치며 시민들은 독재에 맞섰다. 6월 민주 항쟁의 결과 대통령 직선제를 담은 헌법 개정이 이루어졌다.\n\n대의 민주주의의 한계를 보완하는 제도도 있다. 헌법 개정에는 국민 투표가 필요하다. 국민은 국회에 법률의 제정이나 개정 등을 요구하는 청원을 할 수 있고, 온라인에서 일정 수 이상 국민의 동의를 얻으면 국회가 심사하는 국민동의청원 제도도 있다. 지방에는 주민 투표, 주민 소환, 주민 조례 발안 같은 주민 참여 제도가 있다. 정보 통신 기술을 활용해 의견을 모으는 전자 민주주의도 확대되고 있다.\n\n제도가 잘 작동하려면 시민의 역할이 중요하다. 투표에 참여하고, 정책에 관심을 갖고 근거를 따져 판단해야 한다. 나와 다른 의견도 존중하며 대화와 타협으로 문제를 풀어 가는 태도가 필요하다."}],"concepts":[{"term":"대의 민주주의","desc":"국민이 선거로 대표를 뽑고 그 대표가 국민을 대신해 결정하는 방식이다."},{"term":"정치 무관심","desc":"정치에 관심을 갖지 않거나 참여하지 않는 태도이다."},{"term":"국민 투표","desc":"국가의 중요한 문제를 국민이 직접 투표로 결정하는 제도이다. 우리나라는 헌법 개정 시 국민 투표를 거친다."},{"term":"전자 민주주의","desc":"정보 통신 기술을 활용하여 시민이 정치 과정에 참여하고 의견을 나누는 민주주의이다."},{"term":"청원","desc":"국민이 국가 기관에 자신의 의견이나 희망을 문서로 제출하는 것이다."}]}]},"s1-s04":{"title":"정치과정과 시민 참여","lessons":[{"id":"s1-s04-1","title":"선거의 기능과 원칙","standard":{"text":"선거의 기능과 기본 원칙을 검토하고, 선거 과정에서 유권자와 정당이 수행하는 활동을 조사한다."},"sections":[{"title":"선거의 기능","text":"선거는 국민이 투표로 대표를 뽑는 제도이다. 대의 민주주의에서 선거는 국민이 주권을 행사하는 가장 대표적인 방법이다.\n\n선거에는 여러 기능이 있다. 첫째, 국민을 대신해 일할 대표를 뽑는다. 둘째, 뽑힌 대표에게 정당성을 준다. 국민이 직접 선택했기 때문에 대표의 권한 행사를 국민이 받아들이게 된다. 셋째, 대표를 통제한다. 대표가 일을 잘못하면 다음 선거에서 다시 뽑지 않을 수 있으므로 대표는 국민의 뜻에 책임감을 갖는다.\n\n넷째, 선거는 국민의 정치 참여를 이끌고 정치 교육의 기회가 된다. 유권자는 후보와 정당의 공약을 비교하며 사회 문제에 관심을 갖게 된다. 다양한 의견이 선거 과정에서 드러나고 조정되기도 한다."},{"title":"민주 선거의 기본 원칙","text":"선거가 공정하게 이루어지려면 네 가지 기본 원칙을 지켜야 한다. 대한민국 헌법은 국회의원과 대통령을 보통·평등·직접·비밀 선거로 뽑도록 규정한다.\n\n보통 선거는 일정한 나이가 된 국민이면 재산, 성별, 교육 수준과 관계없이 누구나 선거권을 갖는 원칙이다. 반대는 제한 선거이다. 평등 선거는 모든 유권자가 똑같은 수의 표를 행사하고 그 가치도 같아야 한다는 원칙이다. 선거구마다 인구 차이가 지나치게 크면 표의 가치가 달라져 평등 선거에 어긋난다.\n\n직접 선거는 유권자가 다른 사람을 거치지 않고 직접 투표하는 원칙이다. 비밀 선거는 누구에게 투표했는지 다른 사람이 알 수 없게 하는 원칙이다. 이 밖에 누구의 강요도 받지 않고 자유롭게 투표해야 한다는 자유 선거도 중요한 원칙으로 여긴다."},{"title":"선거 과정에서 유권자와 정당의 활동","text":"정당은 선거에서 후보자를 추천하고 공약을 만들어 유권자에게 알린다. 선거 운동을 통해 정책을 설명하고 지지를 호소한다. 선거 결과에 따라 정부를 운영하거나, 정부를 견제하는 역할을 맡는다.\n\n유권자는 선거 공보, 후보자 토론회, 공약 비교 자료 등으로 정보를 모은다. 공약이 실현 가능한지, 재원은 어떻게 마련하는지 따져 본 뒤 투표한다. 선거가 끝난 뒤에도 공약이 지켜지는지 지켜보는 것이 유권자의 몫이다.\n\n선거 제도에 따라 결과도 달라진다. 한 지역구에서 가장 많은 표를 얻은 한 명만 뽑는 방식은 대표를 분명히 정하지만, 떨어진 후보에게 간 표는 사표가 된다. 정당이 얻은 득표율에 비례해 의석을 나누는 비례 대표제는 사표를 줄이고 다양한 의견을 반영하는 데 도움을 준다. 공정한 관리를 위해 독립된 헌법 기관인 선거 관리 위원회가 선거를 관리한다."}],"concepts":[{"term":"보통 선거","desc":"일정한 나이가 된 모든 국민에게 재산·성별 등과 관계없이 선거권을 주는 원칙이다."},{"term":"평등 선거","desc":"모든 유권자가 같은 수의 표를 행사하고 그 표의 가치도 같아야 한다는 원칙이다."},{"term":"직접 선거와 비밀 선거","desc":"직접 선거는 유권자가 직접 투표하는 원칙이고, 비밀 선거는 투표 내용을 다른 사람이 알 수 없게 하는 원칙이다."},{"term":"사표","desc":"당선자를 결정하는 데 반영되지 못한 표이다."},{"term":"비례 대표제","desc":"정당이 얻은 득표율에 비례하여 의석을 나누는 제도이다."}]},{"id":"s1-s04-2","title":"정치 주체와 정치과정","standard":{"text":"정치활동에 참여하는 다양한 정치 주체의 역할을 탐색하고, 정치과정의 의미를 설명한다."},"sections":[{"title":"정치과정이란 무엇인가","text":"정치과정은 사회의 여러 요구가 정치 주체를 통해 표출되고, 정책으로 결정되어 집행되는 과정이다. 사회에는 다양한 요구와 갈등이 있다. 이 요구가 모이고 조정되어 정책이라는 결과로 나타난다.\n\n정치과정은 흔히 네 단계로 나누어 본다. 먼저 시민이나 단체가 의견과 요구를 드러내는 투입 단계가 있다. 다음으로 국회와 정부 같은 정책 결정 기관이 이를 검토해 법률과 정책을 만든다. 만들어진 정책은 산출되어 집행된다.\n\n마지막으로 집행된 정책에 대해 시민이 평가하고 새로운 요구를 내놓는다. 이를 환류(피드백)라고 한다. 환류를 통해 정책은 다시 고쳐지고, 정치과정은 끝없이 순환한다."},{"title":"공식적 정치 주체: 정책 결정 기관","text":"정치 주체는 정치과정에 참여하는 개인과 집단이다. 그중 법에 따라 정책을 결정하고 집행할 권한을 가진 기관을 공식적 정치 주체라 한다. 국회, 정부, 법원이 이에 해당한다.\n\n국회는 국민의 대표로서 법률을 만들고 예산을 심의한다. 정부는 법률에 따라 정책을 세우고 집행한다. 법원은 법을 해석하고 분쟁을 판단하여 정책이 법에 맞게 시행되는지를 판단한다.\n\n이들 기관은 서로 견제하며 정책을 결정한다. 예를 들어 정부가 정책을 위한 예산안을 내면 국회가 심의하여 확정한다. 공식적 주체는 비공식적 주체들이 투입한 요구를 받아 최종 결정을 내리는 역할을 한다."},{"title":"비공식적 정치 주체의 역할","text":"정당은 정치적 견해가 같은 사람들이 정권 획득을 목표로 모인 단체이다. 정당은 여러 의견을 모아 정책으로 만들고, 선거에 후보자를 추천한다. 정권을 잡지 못한 정당은 정부를 비판하고 견제한다.\n\n이익 집단은 같은 이해관계를 가진 사람들이 자신들의 특수한 이익을 실현하려고 만든 단체이다. 정권 획득은 목표로 하지 않는다. 전문 지식을 제공하는 장점이 있지만, 자기 이익만 지나치게 주장하면 공익을 해칠 수 있다. 시민 단체는 시민이 자발적으로 모여 환경, 인권 같은 공익을 추구하는 단체이다.\n\n언론은 정보를 전달하고 여론을 형성하며 권력을 감시한다. 개인도 투표, 청원, 민원 제기, 집회 참여 등으로 정치과정에 참여한다. 이처럼 다양한 주체가 참여할수록 정책에 사회의 여러 목소리가 반영된다."}],"concepts":[{"term":"정치과정","desc":"사회의 요구가 표출되어 정책으로 결정·집행되고 다시 평가받는 과정이다."},{"term":"환류","desc":"집행된 정책에 대한 평가와 반응이 새로운 요구로 다시 정치과정에 투입되는 것이다."},{"term":"정당","desc":"정치적 견해가 같은 사람들이 정권 획득을 목표로 모인 단체이다."},{"term":"이익 집단","desc":"같은 이해관계를 가진 사람들이 특수한 이익을 실현하려고 만든 단체로, 정권 획득을 목표로 하지 않는다."},{"term":"시민 단체","desc":"시민들이 자발적으로 모여 사회 전체의 공익을 추구하는 단체이다."}]},{"id":"s1-s04-3","title":"지방 자치와 시민 참여","standard":{"text":"민주주의의 발전을 위한 지방 자치의 중요성을 설명하고, 지역사회의 문제를 해결하기 위한 시민 참여 활동을 계획한다."},"sections":[{"title":"지방 자치란 무엇인가","text":"지방 자치는 지역 주민이 대표를 뽑아 그 지역의 일을 스스로 처리하는 제도이다. 지역 주민이 지역 문제를 가장 잘 알고, 그 결과를 직접 경험하기 때문이다.\n\n지방 자치를 실시하는 단위를 지방 자치 단체라 한다. 특별시·광역시·도 같은 광역 자치 단체와 시·군·구 같은 기초 자치 단체가 있다. 지방 자치 단체에는 지방 의회와 지방 자치 단체의 장이 있다. 지방 의회는 조례를 만들고 예산을 심의하며 단체장을 견제한다. 단체장은 지역의 행정을 맡아 집행한다.\n\n지방 의회 의원과 단체장은 모두 주민이 선거로 뽑는다. 우리나라의 지방 자치는 1960년대 초에 중단되었다가 1991년 지방 의회 의원 선거로 다시 시작되었고, 1995년 단체장과 지방 의회 의원을 함께 뽑는 전국 동시 지방 선거를 거쳐 본격적으로 실시되었다."},{"title":"지방 자치가 민주주의에 중요한 이유","text":"지방 자치는 '풀뿌리 민주주의'라고 불린다. 주민이 생활과 가까운 문제부터 직접 참여하며 민주주의를 실천하기 때문이다. 또 '민주주의의 학교'라고도 한다. 주민들은 지역 문제를 토론하고 결정하는 경험을 통해 민주 시민의 자질을 기른다.\n\n지방 자치는 권력을 나누는 효과도 있다. 중앙 정부에 집중된 권력을 지방으로 나누어 권력 남용을 막는다. 이것은 수평적 권력 분립과 함께 민주주의를 지키는 수직적 권력 분립에 해당한다.\n\n지역 실정에 맞는 정책을 펼 수 있다는 점도 중요하다. 바닷가 지역과 산간 지역, 대도시와 농촌은 필요한 정책이 다르다. 지방 자치를 통해 각 지역은 특성에 맞게 문제를 해결하고 지역 발전을 이룰 수 있다."},{"title":"지역 문제 해결을 위한 시민 참여","text":"주민이 지역 문제에 참여하는 방법은 다양하다. 지방 선거에서 투표하는 것이 기본이다. 주민 투표로 지역의 중요한 일을 직접 결정할 수 있다. 주민 조례 발안으로 필요한 조례를 만들거나 고치거나 없애 달라고 지방 의회에 직접 청구하고, 주민 소환으로 잘못한 단체장이나 지방 의원을 임기 중에 물러나게 할 수도 있다. 주민 참여 예산제를 통해 예산 편성에 의견을 낼 수도 있다.\n\n청소년도 참여할 수 있다. 지방 자치 단체의 누리집에 민원이나 제안을 올리고, 공청회에 참석하거나 청소년 참여 기구에서 활동할 수 있다.\n\n참여 활동은 순서대로 계획하면 좋다. 먼저 지역 문제를 찾고 원인을 조사한다. 다음으로 해결 방안을 정하고, 담당 기관에 제안하거나 캠페인을 벌이는 등 실천한다. 마지막으로 결과를 평가하고 부족한 점을 보완한다."}],"concepts":[{"term":"지방 자치","desc":"지역 주민이 대표를 뽑아 지역의 일을 스스로 처리하는 제도이다."},{"term":"지방 자치 단체","desc":"지방 자치를 실시하는 단위로, 광역 자치 단체와 기초 자치 단체가 있다."},{"term":"조례","desc":"지방 의회가 법령의 범위 안에서 그 지역에 적용하기 위해 만드는 규칙이다."},{"term":"주민 소환","desc":"주민이 투표로 지방 자치 단체장이나 지방 의원을 임기 중에 물러나게 할 수 있는 제도이다."},{"term":"주민 참여 예산제","desc":"지방 자치 단체의 예산 편성 과정에 주민이 의견을 내고 참여하는 제도이다."}]}]},"s1-s05":{"title":"일상생활과 법","lessons":[{"id":"s1-s05-1","title":"법의 의미와 목적","standard":{"text":"법의 의미와 특징을 설명하고, 일상생활에서 접하는 법의 사례를 통해 법의 목적을 도출한다."},"sections":[{"title":"법이란 무엇인가","text":"법은 국가가 만든 강제성 있는 사회 규범이다. 사회 규범이란 사람들이 함께 살아가기 위해 지켜야 할 행동 기준을 말한다. 사회 규범에는 법 말고도 도덕, 관습, 종교 규범 등이 있다.\n\n법은 다른 사회 규범과 구별되는 특징이 있다. 첫째, 국가 권력에 의해 강제된다. 법을 어기면 형벌, 과태료, 손해 배상 같은 제재를 받는다. 둘째, 대부분 문서로 명확히 정해져 있다. 셋째, 국민 모두에게 똑같이 적용된다.\n\n도덕은 개인의 양심에 따라 지키는 규범이다. 어겨도 양심의 가책이나 주변의 비난을 받을 뿐 국가가 처벌하지는 않는다. 다만 법과 도덕은 많은 부분이 겹친다. 살인이나 도둑질은 법으로도 금지되고 도덕적으로도 잘못된 일이다."},{"title":"법은 왜 필요한가: 법의 목적","text":"법의 목적은 정의를 실현하고 사회 질서를 유지하는 것이다. 사람들의 이해관계는 서로 부딪치기 쉽다. 이때 누구에게나 같은 기준이 적용되지 않으면 힘센 사람의 뜻대로 문제가 해결된다.\n\n정의는 각자에게 정당한 몫을 주는 것이다. 법은 같은 상황에 있는 사람을 같게 대우하고, 피해를 입은 사람이 정당한 보상을 받도록 한다. 이를 통해 약한 사람도 자신의 권리를 지킬 수 있다.\n\n질서 유지도 중요한 목적이다. 법은 무엇을 해도 되고 무엇을 하면 안 되는지 미리 알려 준다. 사람들은 이를 보고 자신의 행동 결과를 예측할 수 있다. 그래서 갈등이 줄고 사회가 안정된다. 오늘날에는 법이 공공복리, 곧 사회 구성원 전체의 행복을 높이는 역할도 한다."},{"title":"일상생활 속의 법","text":"우리는 하루 종일 법과 함께 생활한다. 아침에 신호등을 보고 길을 건너는 것은 「도로교통법」과 관련이 있다. 편의점에서 간식을 사는 것은 판매자와 맺는 매매 계약이며, 「민법」의 적용을 받는다.\n\n학교에 다니는 것도 법과 연결된다. 헌법은 모든 국민이 균등하게 교육을 받을 권리를 보장한다. 의무 교육의 근거도 헌법과 법률에 있다. 식품의 유통 기한 표시나 원산지 표시도 소비자를 보호하기 위해 법으로 정한 것이다.\n\n이처럼 법은 처벌만을 위한 것이 아니다. 법은 우리의 권리를 보호하고, 서로 믿고 거래할 수 있게 해 준다. 일상 속 법의 사례를 살펴보면 법이 정의와 질서, 공공복리를 위해 존재한다는 것을 알 수 있다."}],"concepts":[{"term":"사회 규범","desc":"사회 구성원이 함께 살아가기 위해 지켜야 할 행동 기준이다. 법, 도덕, 관습, 종교 규범 등이 있다."},{"term":"법","desc":"국가가 만들고 국가 권력으로 강제하는 사회 규범이다. 어기면 형벌이나 손해 배상 같은 제재가 따른다."},{"term":"강제성","desc":"규범을 지키도록 국가가 힘으로 강요할 수 있는 성질이다. 법을 도덕·관습과 구별하는 가장 중요한 특징이다."},{"term":"정의","desc":"각자에게 정당한 몫을 주는 것이다. 법이 추구하는 가장 중요한 가치이다."},{"term":"공공복리","desc":"사회 구성원 전체의 행복과 이익이다. 현대의 법은 질서 유지뿐 아니라 공공복리 실현도 목적으로 한다."}]},{"id":"s1-s05-2","title":"다양한 법과 사회법","standard":{"text":"우리의 일상을 규율하는 다양한 법을 탐색하고, 국내외 사례를 통해 사회법이 필요한 이유에 대해 토의한다."},"sections":[{"title":"공법과 사법","text":"법은 다루는 생활 영역에 따라 공법, 사법, 사회법으로 나눌 수 있다. 공법은 국가와 개인의 관계, 또는 국가 기관 사이의 관계를 규율한다. 헌법, 형법, 행정법, 소송법이 대표적이다.\n\n헌법은 국가 조직의 기본 원리와 국민의 기본권을 정한 최고법이다. 형법은 어떤 행위가 범죄이고 어떤 형벌을 받는지 정한다. 행정법은 세금, 인허가처럼 행정 기관이 일하는 방식을 다룬다.\n\n사법(私法)은 개인과 개인 사이의 관계를 규율한다. 민법과 상법이 대표적이다. 민법은 계약, 소유권, 가족, 상속 같은 일상적인 재산·가족 관계를 다룬다. 상법은 회사와 상거래에 관한 내용을 다룬다."},{"title":"사회법은 왜 등장했을까","text":"사회법은 사법의 영역에 국가가 개입해 사회적 약자를 보호하는 법이다. 근대 사법은 개인이 자유롭게 계약을 맺는 것을 존중했다. 이를 계약 자유의 원칙이라고 한다.\n\n그런데 산업 혁명 이후 문제가 생겼다. 기업과 노동자는 형식상 평등했지만 실제 힘은 크게 달랐다. 노동자는 일자리를 잃지 않으려고 긴 노동 시간과 낮은 임금도 받아들였다. 빈부 격차, 독과점, 실업 같은 문제도 심해졌다.\n\n그래서 국가가 계약 자유를 일부 제한하고 약자를 보호하는 법을 만들었다. 이것이 사회법이다. 영국의 공장법처럼 아동 노동 시간을 제한한 법이 초기 사례이다. 1919년 독일의 바이마르 헌법은 인간다운 생활을 보장하는 사회권을 본격적으로 규정한 대표적인 헌법이다."},{"title":"우리 생활 속 사회법","text":"사회법은 노동법, 경제법, 사회 보장법으로 나뉜다. 노동법은 근로자의 권리를 보호한다. 「근로기준법」, 「최저임금법」, 「노동조합 및 노동관계조정법」이 이에 속한다.\n\n경제법은 공정한 경쟁과 소비자 보호를 위한 법이다. 「독점규제 및 공정거래에 관한 법률」은 대기업이 시장 지배력을 남용하지 못하게 한다. 「소비자기본법」은 소비자의 권리를 정한다.\n\n사회 보장법은 질병, 노령, 실업 같은 위험에서 국민의 생활을 지킨다. 「국민건강보험법」, 「국민연금법」, 「국민기초생활 보장법」 등이 있다. 아르바이트를 할 때 근로 계약서를 쓰는 것, 병원비 일부를 건강 보험이 내 주는 것은 모두 사회법 덕분이다."}],"concepts":[{"term":"공법","desc":"국가와 개인, 국가 기관 사이의 관계를 규율하는 법이다. 헌법, 형법, 행정법, 소송법 등이 있다."},{"term":"사법(私法)","desc":"개인과 개인 사이의 재산·가족 관계를 규율하는 법이다. 민법과 상법이 대표적이다."},{"term":"사회법","desc":"사적 관계에 국가가 개입해 사회적 약자를 보호하는 법이다. 공법과 사법의 성격을 함께 가진다."},{"term":"계약 자유의 원칙","desc":"개인이 계약 상대, 내용, 방식을 자유롭게 정할 수 있다는 근대 사법의 원칙이다. 사회법은 이 원칙을 일부 수정한다."},{"term":"노동법·경제법·사회 보장법","desc":"사회법의 세 갈래이다. 각각 근로자 보호, 공정한 경쟁과 소비자 보호, 국민의 생활 보장을 목적으로 한다."}]},{"id":"s1-s05-3","title":"재판과 공정성","standard":{"text":"재판의 의미와 종류를 설명하고, 공정한 재판의 중요성에 대해 토의한다."},"sections":[{"title":"재판의 의미와 종류","text":"재판은 법원이 법을 적용해 분쟁을 해결하거나 범죄 여부를 판단하는 활동이다. 재판은 독립된 법관이 법과 증거에 따라 판단하므로 당사자끼리 다투는 것보다 공정하다.\n\n민사 재판은 개인 사이의 재산이나 권리 다툼을 해결한다. 돈을 빌려주고 받지 못했을 때가 그 예이다. 소송을 제기한 사람을 원고, 상대방을 피고라고 한다. 형사 재판은 범죄를 저질렀는지 판단하고 형벌을 정한다. 검사가 공소를 제기하고, 재판을 받는 사람을 피고인이라고 한다.\n\n이 밖에도 여러 재판이 있다. 행정 재판은 행정 기관의 위법한 처분으로 권리를 침해당했을 때 다툰다. 가사 재판은 이혼, 상속 같은 가족 관계 분쟁을 다룬다. 헌법 재판은 법원이 아닌 헌법재판소가 법률의 위헌 여부 등을 판단하는 재판이다."},{"title":"공정한 재판을 위한 제도","text":"공정한 재판을 위해 여러 제도가 마련되어 있다. 먼저 사법권의 독립이다. 법관은 헌법과 법률, 양심에 따라 독립하여 심판한다. 국회, 정부, 여론 등 외부의 압력을 받지 않아야 한다.\n\n심급 제도는 한 사건을 여러 단계의 법원에서 재판받게 하는 제도이다. 우리나라는 원칙적으로 3심제를 둔다. 1심 판결에 불복하면 2심 법원에 항소하고, 2심 판결에 불복하면 대법원에 상고한다. 잘못된 판결을 바로잡을 기회를 주는 것이다.\n\n재판 공개의 원칙도 있다. 재판의 심리와 판결은 원칙적으로 공개한다. 국민이 재판을 지켜볼 수 있어야 공정성이 확보된다. 형사 재판에서는 증거에 의해서만 범죄 사실을 인정하는 증거 재판주의를 따른다."},{"title":"공정한 재판이 중요한 이유","text":"공정한 재판은 국민의 권리를 지키는 마지막 보루이다. 재판이 공정하지 않으면 억울한 사람이 처벌받거나 정당한 권리를 잃게 된다. 그러면 사람들은 법을 믿지 않고, 사회 질서도 흔들린다.\n\n형사 재판에서는 특히 피고인의 인권 보호가 중요하다. 피고인은 유죄 판결이 확정될 때까지 무죄로 추정된다. 이를 무죄 추정의 원칙이라고 한다. 피고인은 변호인의 도움을 받을 권리도 가진다.\n\n국민이 재판에 직접 참여하는 제도도 있다. 국민 참여 재판은 국민 중에서 선정된 배심원이 형사 재판에 참여해 유죄·무죄에 대한 의견을 내는 제도이다. 배심원의 평결은 판사에게 권고적 효력만 있다. 그래도 국민의 시각을 재판에 반영해 재판에 대한 신뢰를 높인다."}],"concepts":[{"term":"민사 재판","desc":"개인 사이의 재산·권리 다툼을 해결하는 재판이다. 소송을 제기한 사람을 원고, 상대방을 피고라고 한다."},{"term":"형사 재판","desc":"범죄 여부를 판단하고 형벌을 정하는 재판이다. 검사가 공소를 제기하며, 재판을 받는 사람을 피고인이라고 한다."},{"term":"심급 제도(3심제)","desc":"급이 다른 법원에서 여러 번 재판받을 수 있게 한 제도이다. 1심에 불복하면 항소, 2심에 불복하면 상고한다."},{"term":"사법권의 독립","desc":"법관이 외부 간섭 없이 헌법과 법률, 양심에 따라 재판하도록 보장하는 원칙이다."},{"term":"국민 참여 재판","desc":"국민 중에서 선정된 배심원이 형사 재판에 참여해 의견을 내는 제도이다. 배심원 평결은 판사에게 권고적 효력을 가진다."}]}]},"s1-s06":{"title":"인권과 기본권","lessons":[{"id":"s1-s06-1","title":"인권과 기본권의 종류","standard":{"text":"일상생활에서 인권이 침해되는 사례를 조사하고, 우리 헌법에 보장된 기본권의 종류를 탐색한다."},"sections":[{"title":"인권과 기본권","text":"인권은 사람이라면 누구나 태어날 때부터 가지는 기본적인 권리이다. 인권은 국가나 다른 사람이 준 것이 아니다. 이를 천부 인권이라고 한다. 인권은 성별, 나이, 인종, 장애, 국적과 관계없이 모든 사람에게 보장된다. 또한 누구도 함부로 빼앗을 수 없다.\n\n인권이 실제로 보장되려면 법적인 근거가 필요하다. 그래서 국가는 헌법에 인권을 명시한다. 헌법으로 보장된 인권을 기본권이라고 한다.\n\n우리 헌법 제10조는 모든 국민이 인간으로서의 존엄과 가치를 가지며 행복을 추구할 권리를 가진다고 정한다. 이것은 모든 기본권의 바탕이 되는 원리이다. 국가는 개인이 가지는 기본적 인권을 확인하고 보장할 의무를 진다."},{"title":"우리 헌법이 보장하는 기본권의 종류","text":"우리 헌법은 인간의 존엄과 가치를 바탕으로 다섯 가지 기본권을 보장한다. 평등권은 성별, 종교, 사회적 신분 등에 따라 부당하게 차별받지 않을 권리이다. 자유권은 국가 권력의 간섭을 받지 않고 자유롭게 생활할 권리이다. 신체의 자유, 거주·이전의 자유, 직업 선택의 자유, 언론·출판·집회·결사의 자유, 종교의 자유 등이 있다.\n\n참정권은 국민이 국가 정치 과정에 참여할 권리이다. 선거권, 공무 담임권, 국민 투표권이 있다. 사회권은 인간다운 생활을 위해 국가에 적극적인 배려를 요구할 권리이다. 교육을 받을 권리, 근로의 권리, 환경권 등이 이에 속한다. 사회권은 현대 복지 국가에서 강조되었다.\n\n청구권은 기본권이 침해되었을 때 국가에 구제를 요구할 권리이다. 청원권, 재판 청구권, 국가 배상 청구권 등이 있다. 청구권은 다른 기본권을 지키기 위한 수단적 권리이다."},{"title":"일상생활 속 인권 침해","text":"인권 침해는 특별한 곳이 아니라 일상에서 자주 일어난다. 외모나 출신 지역을 이유로 놀리는 것은 인격권 침해이자 차별이다. 허락 없이 다른 사람의 사진이나 개인 정보를 온라인에 올리는 것은 사생활의 비밀과 자유를 침해한다.\n\n장애인이 이용할 수 있는 시설이 없어 이동하지 못하는 것도 인권 문제이다. 이는 평등권과 이동할 자유를 제약한다. 외국인 근로자나 이주민이 국적을 이유로 부당한 대우를 받는 사례도 있다.\n\n인권 침해는 국가 기관이 일으킬 수도 있고, 개인이나 기업이 일으킬 수도 있다. 중요한 것은 일상 속 침해를 알아차리는 감수성이다. 나의 권리만큼 다른 사람의 권리도 존중해야 인권이 보장되는 사회가 된다."}],"concepts":[{"term":"인권","desc":"사람이라면 누구나 태어날 때부터 가지는 기본적인 권리이다. 누구도 함부로 빼앗을 수 없다."},{"term":"기본권","desc":"헌법으로 보장된 인권이다. 우리 헌법은 인간의 존엄과 가치를 바탕으로 평등권·자유권·참정권·사회권·청구권을 보장한다."},{"term":"자유권","desc":"국가 권력의 간섭을 받지 않고 자유롭게 생활할 권리이다. 가장 오래된 기본권이며 소극적 권리라고도 한다."},{"term":"사회권","desc":"인간다운 생활을 위해 국가에 적극적인 배려를 요구할 권리이다. 교육을 받을 권리, 근로의 권리, 환경권 등이 있다."},{"term":"청구권","desc":"기본권이 침해되었을 때 국가에 구제를 요구하는 권리이다. 다른 기본권을 지키는 수단이 된다."}]},{"id":"s1-s06-2","title":"기본권 제한과 구제","standard":{"text":"기본권 제한의 요건과 한계가 헌법에 명시된 이유를 토의하고, 기본권 침해 시 구제 방법을 조사한다."},"sections":[{"title":"기본권은 왜, 어떻게 제한될까","text":"기본권은 소중하지만 무제한으로 보장되지는 않는다. 한 사람의 자유가 다른 사람의 권리나 사회 전체의 이익과 충돌할 수 있기 때문이다. 예를 들어 표현의 자유가 있어도 다른 사람의 명예를 훼손할 수는 없다.\n\n우리 헌법 제37조 제2항은 기본권 제한의 요건을 정하고 있다. 국민의 모든 자유와 권리는 국가 안전 보장, 질서 유지, 공공복리를 위해 필요한 경우에 한하여 법률로써 제한할 수 있다.\n\n이 조항에는 세 가지 요건이 담겨 있다. 첫째, 목적이 국가 안전 보장·질서 유지·공공복리여야 한다. 둘째, 꼭 필요한 경우에만 제한해야 한다. 셋째, 국민의 대표인 국회가 만든 법률에 근거해야 한다."},{"title":"제한에도 한계가 있는 이유","text":"헌법은 기본권 제한의 한계도 함께 정한다. 기본권을 제한하는 경우에도 자유와 권리의 본질적인 내용은 침해할 수 없다. 예를 들어 집회 시간이나 장소를 제한할 수는 있어도 집회의 자유 자체를 없애서는 안 된다.\n\n또한 제한은 필요한 최소한에 그쳐야 한다. 목적이 정당하고, 수단이 적절하며, 피해가 가장 적은 방법을 택하고, 얻는 공익이 잃는 사익보다 커야 한다. 이를 과잉 금지의 원칙이라고 한다.\n\n이런 요건과 한계를 헌법에 적어 둔 이유는 국가 권력의 남용을 막기 위해서이다. 제한 기준이 불분명하면 권력자가 마음대로 국민의 자유를 빼앗을 수 있다. 헌법에 명시된 기준은 국가가 넘지 말아야 할 선을 정해 기본권을 지킨다."},{"title":"기본권이 침해되었을 때의 구제 방법","text":"기본권이 침해되면 여러 방법으로 구제받을 수 있다. 행정 기관의 위법·부당한 처분으로 피해를 입었다면 행정 기관에 행정 심판을 청구할 수 있다. 법원에 행정 소송을 제기할 수도 있다.\n\n공무원의 위법한 직무 행위로 손해를 입었다면 국가 배상을 청구할 수 있다. 공권력 때문에 헌법상 기본권을 침해당했을 때는 헌법재판소에 헌법 소원 심판을 청구할 수 있다. 헌법 소원은 원칙적으로 다른 법률에 구제 절차가 있으면 그 절차를 먼저 거쳐야 한다.\n\n국가 인권 위원회에 진정하는 방법도 있다. 국가 인권 위원회는 인권 침해와 차별 행위를 조사하고 시정을 권고한다. 국민 권익 위원회는 행정 기관에 대한 고충 민원을 처리한다. 개인이나 기업이 권리를 침해했다면 민사 소송이나 형사 고소를 할 수 있다."}],"concepts":[{"term":"기본권 제한의 요건(헌법 제37조 제2항)","desc":"국가 안전 보장·질서 유지·공공복리를 위해 필요한 경우에 한하여 법률로써 기본권을 제한할 수 있다는 헌법 조항이다."},{"term":"본질적 내용 침해 금지","desc":"기본권을 제한하더라도 그 권리의 핵심 내용까지 없앨 수는 없다는 원칙이다."},{"term":"과잉 금지의 원칙","desc":"기본권 제한은 목적이 정당하고 수단이 적절하며 피해가 최소이고 공익이 사익보다 커야 한다는 원칙이다."},{"term":"헌법 소원 심판","desc":"공권력의 행사나 불행사로 기본권을 침해당한 사람이 헌법재판소에 구제를 청구하는 제도이다."},{"term":"국가 인권 위원회","desc":"인권 침해와 차별 행위에 대한 진정을 조사하고 시정을 권고하는 독립 기관이다."}]},{"id":"s1-s06-3","title":"근로자의 권리","standard":{"text":"근로자에게 보장되는 권리를 조사하고, 이러한 권리의 침해에 대처하는 국가와 시민의 노력에 대해 토의한다."},"sections":[{"title":"근로자에게 보장되는 권리","text":"근로자는 임금을 받기 위해 사용자에게 노동을 제공하는 사람이다. 근로자는 사용자보다 불리한 위치에 놓이기 쉽다. 그래서 헌법은 근로자의 권리를 특별히 보장한다.\n\n헌법 제32조는 근로의 권리를 보장한다. 국가는 고용 증진에 노력하고, 최저 임금제를 시행해야 한다. 근로 조건의 기준은 인간의 존엄성을 보장하도록 법률로 정한다. 「근로기준법」은 근로 시간, 휴게, 휴일, 임금 지급, 해고 제한 같은 최저 기준을 정한다.\n\n헌법 제33조는 근로 3권을 보장한다. 단결권은 근로자가 노동조합을 만들거나 가입할 권리이다. 단체 교섭권은 노동조합이 사용자와 근로 조건을 협상할 권리이다. 단체 행동권은 교섭이 잘 되지 않을 때 파업 등 쟁의 행위를 할 권리이다."},{"title":"청소년 근로자의 권리","text":"청소년도 근로자로서 법의 보호를 받는다. 원칙적으로 만 15세 이상이어야 일할 수 있다. 만 15세 미만이거나 중학교에 다니는 만 18세 미만 청소년은 고용 노동부 장관이 발급한 취직 인허증이 있어야 일할 수 있다. 만 18세 미만을 고용할 때 사용자는 친권자나 후견인의 동의서와 가족 관계 증명서를 갖추어야 한다.\n\n사용자는 임금, 근로 시간, 휴일 등 근로 조건을 적은 근로 계약서를 써서 근로자에게 주어야 한다. 청소년도 최저 임금 이상을 받을 권리가 있다. 임금은 원칙적으로 정해진 날짜에 돈으로 직접, 전액을 지급해야 한다.\n\n청소년에게는 추가 보호도 있다. 성인보다 근로 시간이 짧게 제한된다. 오후 10시부터 다음 날 오전 6시까지의 야간 근로와 휴일 근로는 원칙적으로 할 수 없으며, 본인 동의와 고용 노동부 장관의 인가가 있어야 예외가 허용된다. 술집처럼 청소년에게 유해한 업종에서는 일할 수 없다."},{"title":"권리 침해에 대처하는 국가와 시민의 노력","text":"근로자의 권리가 침해되면 국가 기관의 도움을 받을 수 있다. 임금을 받지 못했거나 근로 계약서를 받지 못했다면 고용 노동부에 진정을 제기할 수 있다. 근로 감독관이 사실을 조사해 사용자에게 시정을 요구한다. 정당한 이유 없이 해고되었다면 노동 위원회에 부당 해고 구제 신청을 할 수 있다. 법원에 소송을 제기할 수도 있다.\n\n국가는 예방에도 힘쓴다. 사업장의 법 위반을 점검하는 근로 감독을 하고, 노동 상담 창구를 운영한다. 청소년 근로 권익 보호를 위한 상담과 교육도 한다.\n\n시민의 노력도 필요하다. 근로자는 노동조합을 통해 함께 목소리를 낼 수 있다. 시민 단체는 상담과 캠페인으로 권리 침해를 알린다. 소비자는 노동권을 존중하는 기업에 관심을 가질 수 있다. 무엇보다 근로자 스스로 자신의 권리를 알고 근로 계약서와 근무 기록을 챙기는 것이 중요하다."}],"concepts":[{"term":"근로 3권","desc":"헌법 제33조가 보장하는 단결권, 단체 교섭권, 단체 행동권이다. 근로자가 사용자와 대등하게 협상할 수 있게 한다."},{"term":"근로기준법","desc":"근로 시간, 임금, 휴일, 해고 등 근로 조건의 최저 기준을 정한 법이다. 이 기준에 못 미치는 근로 계약 부분은 무효이다."},{"term":"최저 임금제","desc":"국가가 임금의 최저 수준을 정하고 사용자가 그 이상을 지급하도록 강제하는 제도이다. 헌법 제32조에 근거한다."},{"term":"근로 계약서","desc":"임금, 근로 시간, 휴일 등 근로 조건을 적은 문서이다. 사용자는 이를 서면으로 작성해 근로자에게 주어야 한다."},{"term":"부당 해고 구제 신청","desc":"정당한 이유 없이 해고된 근로자가 노동 위원회에 구제를 요청하는 제도이다."}]}]},"s2-g07":{"title":"대한민국, 우리가 살아가는 곳","lessons":[{"id":"s2-g07-1","title":"우리나라의 영역","standard":{"text":null},"sections":[{"title":"영역: 영토·영해·영공","text":"영역은 한 나라의 주권이 미치는 범위이다. 영역은 땅인 영토, 바다인 영해, 하늘인 영공으로 이루어진다. 영역이 있어야 국민이 안정적으로 생활하고 나라를 유지할 수 있다.\n\n대한민국 헌법 제3조는 \"대한민국의 영토는 한반도와 그 부속도서로 한다.\"라고 정하고 있다. 한반도는 남북으로 길게 뻗은 반도이며, 주변에 3,000개가 넘는 섬이 있다. 서·남해안에서는 간척 사업으로 바다를 메워 영토가 조금씩 넓어지기도 했다.\n\n영공은 영토와 영해의 수직 위 하늘이다. 일반적으로 대기권까지를 영공으로 본다. 다른 나라 항공기가 우리 영공을 지나려면 허가를 받아야 한다."},{"title":"영해는 기선에서부터 잰다","text":"영해는 기선으로부터 일정한 거리까지의 바다이다. 우리나라는 대부분 해역에서 기선으로부터 12해리까지를 영해로 정했다. 1해리는 1,852m이므로 12해리는 약 22km이다. 일본과 거리가 가까운 대한 해협은 예외로 3해리까지만 영해로 한다.\n\n기선은 해안의 모양에 따라 두 가지로 정한다. 해안선이 단조로운 동해안 대부분과 제주도·울릉도·독도는 썰물 때의 해안선인 최저 조위선을 기선으로 한다. 이를 통상 기선이라고 한다. 섬이 많고 해안선이 복잡한 서해안과 남해안, 그리고 동해안 일부(영일만·울산만)는 가장 바깥쪽 섬이나 육지의 끝점을 이은 직선 기선을 쓴다.\n\n기선 안쪽의 바다를 내수라고 한다. 직선 기선을 쓰는 서·남해안에는 기선 안쪽에 넓은 내수가 있다. 내수에는 영토와 마찬가지로 우리나라의 주권이 완전히 미친다."},{"title":"배타적 경제 수역과 바다의 이웃","text":"배타적 경제 수역은 기선으로부터 200해리까지의 바다 중 영해를 제외한 범위이다. 연안국은 이 바다에서 물고기와 해저 자원을 탐사·개발하고 관리할 권리를 가진다. 인공 섬이나 시설을 설치할 수도 있다.\n\n그러나 배타적 경제 수역은 영해가 아니다. 다른 나라 선박이 지나다니고 항공기가 위를 나는 것은 자유롭다. 해저 케이블이나 관을 설치하는 것도 허용된다.\n\n우리나라와 중국, 일본 사이의 바다는 폭이 400해리가 안 되는 곳이 많다. 그래서 각 나라의 200해리 범위가 서로 겹친다. 이 때문에 우리나라는 중국·일본과 어업 협정을 맺어 함께 관리하는 수역을 두고 있다. 바다의 경계를 지키고 자원을 지속 가능하게 이용하는 일은 우리의 생활과 직결된다."}],"concepts":[{"term":"영역","desc":"한 나라의 주권이 미치는 범위이다. 영토·영해·영공으로 이루어진다."},{"term":"기선","desc":"영해를 재기 시작하는 기준선이다. 썰물 때 해안선을 쓰는 통상 기선과, 바깥쪽 섬을 이은 직선 기선이 있다."},{"term":"영해","desc":"기선으로부터 12해리까지의 바다이다. 대한 해협 일부는 3해리를 적용한다."},{"term":"내수","desc":"기선 안쪽의 바다이다. 영토와 마찬가지로 주권이 완전히 미친다."},{"term":"배타적 경제 수역","desc":"기선으로부터 200해리까지 중 영해를 제외한 바다이다. 연안국이 자원 탐사·개발 권리를 가지지만 다른 나라의 항행은 자유롭다."}]},{"id":"s2-g07-2","title":"독도","standard":{"text":null},"sections":[{"title":"독도는 어디에 있고 어떤 섬일까","text":"독도는 우리나라 동쪽 끝에 있는 섬이다. 행정 구역은 경상북도 울릉군 울릉읍 독도리이다. 울릉도에서 동남쪽으로 약 87.4km 떨어져 있고, 일본 오키섬에서는 약 157.5km 떨어져 있다. 날씨가 맑으면 울릉도에서 맨눈으로 독도를 볼 수 있다.\n\n독도는 신생대(약 460만~250만 년 전)의 해저 화산 활동으로 만들어진 화산섬이며, 울릉도와 제주도보다 먼저 만들어졌다. 동도와 서도 두 개의 큰 섬과 89개의 부속 도서로 이루어져 있다. 오랜 세월 파도에 깎여 가파른 절벽과 독특한 바위가 많다.\n\n독도는 바다의 영향을 크게 받는 해양성 기후가 나타난다. 연중 기온 차가 작고 비가 자주 내리며 안개가 잦다. 괭이갈매기와 바다제비 같은 바닷새가 무리 지어 번식한다. 섬 전체가 천연기념물 '독도 천연보호구역'으로 지정되어 보호받고 있다."},{"title":"독도가 소중한 까닭","text":"독도는 영역 면에서 중요하다. 독도는 우리나라 영토의 동쪽 끝이다. 독도를 기준으로 주변에 영해가 설정되고, 동해에서 우리 바다의 범위를 정하는 중요한 기점이 된다.\n\n경제적 가치도 크다. 독도 주변은 북쪽에서 내려오는 한류와 남쪽에서 올라오는 난류가 만나는 조경 수역이다. 플랑크톤이 풍부해 오징어·꽁치 등 다양한 물고기가 모인다. 주변 해저에는 미래 에너지 자원으로 주목받는 메테인 하이드레이트가 묻혀 있을 것으로 추정된다. 깊은 바다의 깨끗한 해양 심층수도 활용 가치가 있다.\n\n독도는 생태와 지질 면에서도 가치가 있다. 바다 한가운데 솟은 화산섬이어서 해저 화산이 섬으로 자라는 과정을 연구하기 좋다. 동해의 바다와 날씨를 관측하는 기지로서의 가치도 크다."},{"title":"독도가 우리 땅인 근거","text":"독도는 역사적·지리적·국제법적으로 대한민국의 고유 영토이다. 『세종실록』 「지리지」(1454)에는 우산(독도)과 무릉(울릉도) 두 섬이 서로 멀지 않아 날씨가 맑으면 바라볼 수 있다고 기록되어 있다. 조선 숙종 때 안용복은 일본에 건너가 울릉도와 독도가 조선 땅임을 주장했다. 일본 메이지 정부의 최고 기관인 태정관도 1877년 '울릉도 외 한 섬(독도)은 일본과 관계없다'는 지령을 내렸다.\n\n1900년 대한 제국은 칙령 제41호를 반포해 울릉도를 울도군으로 승격하고 석도(독도)를 관할 구역에 포함했다. 그런데 일본은 러일 전쟁 중인 1905년 독도를 일방적으로 시마네현에 편입했다. 이는 한국 침탈 과정에서 이루어진 불법 행위로 효력이 없다.\n\n광복 후 1946년 연합국 최고 사령관 각서(SCAPIN) 제677호는 독도를 일본의 통치 범위에서 제외했다. 현재 독도에는 독도 경비대와 주민이 머물며 우리나라가 실효적으로 지배하고 있다."}],"concepts":[{"term":"독도","desc":"울릉도에서 동남쪽으로 약 87.4km 떨어진 우리나라 동쪽 끝의 섬. 동도와 서도, 89개의 부속 도서로 이루어진 화산섬이다."},{"term":"영해","desc":"기선으로부터 12해리까지의 바다. 대한해협 일부는 3해리를 적용한다."},{"term":"배타적 경제 수역","desc":"기선으로부터 200해리까지 영해를 제외한 바다. 연안국이 자원 탐사·개발 권리를 가진다."},{"term":"조경 수역","desc":"한류와 난류가 만나는 바다이다. 플랑크톤이 풍부해 어족 자원이 많으며, 독도 주변이 대표적이다."},{"term":"대한 제국 칙령 제41호","desc":"1900년 대한 제국이 울릉도를 울도군으로 승격하고 석도(독도)를 관할 구역에 포함한 법령이다. 독도 영유권의 중요한 근거이다."}]},{"id":"s2-g07-3","title":"우리나라의 위치와 지역","standard":{"text":null},"sections":[{"title":"수리적 위치: 위도와 경도로 본 우리나라","text":"수리적 위치는 위도와 경도로 나타낸 위치이다. 우리나라는 대략 북위 33°~43°, 동경 124°~132° 사이에 있다. 북쪽 끝은 함경북도 온성군 유원진, 남쪽 끝은 마라도, 서쪽 끝은 평안북도 용천군 마안도, 동쪽 끝은 독도이다.\n\n우리나라는 중위도에 있어서 사계절이 뚜렷하다. 계절마다 옷차림과 음식, 농사 시기가 달라진다.\n\n경도는 시간과 관련이 있다. 우리나라는 동경 135°를 표준 경선으로 쓴다. 경도 15°마다 1시간 차이가 나므로 세계 표준시보다 9시간 빠르다. 한반도 중앙을 지나는 경선은 동경 127.5° 부근이어서, 해가 가장 높이 뜨는 시각은 낮 12시 30분 무렵이다."},{"title":"지리적 위치와 관계적 위치","text":"지리적 위치는 대륙·해양·반도처럼 땅과 바다를 기준으로 나타낸 위치이다. 우리나라는 유라시아 대륙의 동쪽 끝에 있고 태평양과 맞닿은 반도국이다. 반도는 대륙과 해양 양쪽으로 나아가기 쉬워 두 방향의 문화를 받아들이고 전하기에 유리하다.\n\n대륙의 동쪽에 있어서 계절풍의 영향을 크게 받는다. 그래서 비슷한 위도의 다른 지역보다 여름은 덥고 겨울은 추워 기온의 연교차가 크다.\n\n관계적 위치는 주변 나라와의 관계로 나타낸 위치이다. 우리나라는 중국, 일본, 러시아 사이에 있다. 관계적 위치는 시대와 국제 정세에 따라 변한다. 과거에는 주변 강대국의 침략을 받기도 했지만, 오늘날에는 동아시아 교류의 중심지 역할을 한다. 인천 국제공항과 부산항은 여러 나라를 잇는 교통·물류의 중심지이다."},{"title":"지역 브랜드와 지역화 전략","text":"세계화가 진행되면서 각 지역은 세계의 다른 지역과도 경쟁하게 되었다. 그래서 지역의 특성을 살려 경쟁력을 높이는 지역화 전략이 중요해졌다.\n\n지역 브랜드는 지역의 이미지와 특산물, 축제 등을 하나의 상표처럼 만들어 알리는 것이다. 지방 자치 단체는 슬로건과 로고를 만들어 지역을 홍보한다. 장소 마케팅은 지역의 특별한 장소나 축제를 상품처럼 알려 관광객과 기업을 끌어들이는 전략이다. 보령 머드 축제, 함평 나비 축제, 화천 산천어 축제가 대표적이다.\n\n지리적 표시제도 지역화 전략의 하나이다. 품질이 그 지역의 자연환경이나 전통과 깊이 연결된 상품에 지역 이름을 붙여 보호한다. 보성 녹차는 2002년 우리나라에서 처음으로 지리적 표시 등록(제1호)을 받은 농산물이다. 이러한 전략은 주민의 소득을 높이고 지역에 대한 자부심을 키운다."}],"concepts":[{"term":"수리적 위치","desc":"위도와 경도로 나타낸 위치이다. 우리나라는 북위 33°~43°, 동경 124°~132°에 있다."},{"term":"지리적 위치","desc":"대륙·해양·반도 등 땅과 바다를 기준으로 나타낸 위치이다. 우리나라는 유라시아 대륙 동쪽 끝의 반도국이다."},{"term":"관계적 위치","desc":"주변 나라와의 정치·경제적 관계로 나타낸 위치이다. 시대와 국제 정세에 따라 변한다."},{"term":"지역 브랜드","desc":"지역의 이미지·특산물·축제 등을 상표처럼 만들어 알리는 것이다. 지역의 경쟁력을 높이는 지역화 전략의 하나이다."},{"term":"지리적 표시제","desc":"품질이 특정 지역의 환경이나 전통과 연결된 상품에 지역 이름을 붙여 법적으로 보호하는 제도이다."}]}]},"s2-g08":{"title":"우리나라의 자연환경과 인간 생활","lessons":[{"id":"s2-g08-1","title":"지형","standard":{"text":null},"sections":[{"title":"산지가 많고 동쪽이 높은 땅","text":"우리나라는 국토의 약 70%가 산지이다. 높은 산은 대부분 북부와 동부에 있고, 남부와 서부에는 낮은 산지와 평야가 많다.\n\n한반도는 동쪽이 높고 서쪽이 낮은 동고서저 지형이다. 오래전 지각 운동으로 동해 쪽이 높이 솟아오르고 서쪽은 완만하게 기울었기 때문이다. 그래서 태백산맥과 함경산맥 같은 높은 산줄기가 동쪽에 치우쳐 있다.\n\n산의 모습은 바위의 종류에 따라 다르다. 북한산·설악산처럼 화강암이 드러난 산은 봉우리가 뾰족한 돌산이다. 지리산·오대산처럼 흙으로 두껍게 덮인 산은 완만한 흙산이다. 대관령 일대에는 높은 곳인데도 평평한 고위 평탄면이 있어 고랭지 농업과 목축이 이루어진다."},{"title":"하천과 해안이 만든 지형","text":"동고서저 지형 때문에 큰 하천은 대부분 서해와 남해로 흐른다. 여름에 비가 몰려 내려 계절에 따라 하천의 물 양 차이가 크다. 그래서 댐을 만들어 홍수를 막고 물을 저장한다. 상류에는 산지 사이를 굽이쳐 흐르는 감입 곡류 하천이 나타난다. 하류에는 하천이 옮긴 흙이 쌓여 범람원과 삼각주 같은 충적 평야가 만들어진다. 충적 평야는 벼농사의 중심지이다.\n\n해안의 모습은 바다마다 다르다. 동해안은 해안선이 단조롭고 모래사장이 발달했다. 경포호 같은 석호와 계단 모양의 해안 단구도 볼 수 있다. 서해안과 남해안은 해안선이 복잡한 리아스 해안이며 섬이 많다. 특히 서해안은 밀물과 썰물의 차이가 커서 넓은 갯벌이 발달했다. 갯벌은 생물의 서식지이자 오염 물질을 정화하는 역할을 한다."},{"title":"화산 지형과 카르스트 지형","text":"화산 활동으로 만들어진 지형도 있다. 백두산 꼭대기에는 화산이 함몰되어 생긴 칼데라에 물이 고인 천지가 있다. 제주도에는 한라산을 중심으로 수많은 오름(기생 화산)과 용암 동굴, 주상 절리가 있다. 울릉도에는 칼데라 분지인 나리 분지가 있다. 제주의 화산섬과 용암 동굴은 유네스코 세계 자연 유산으로 등재되었다.\n\n석회암 지대에는 카르스트 지형이 나타난다. 석회암은 빗물이나 지하수에 잘 녹는다. 그래서 땅이 움푹 꺼진 돌리네와 땅속의 석회 동굴이 만들어진다. 강원특별자치도 남부와 충청북도 북동부의 영월·단양·삼척 일대가 대표 지역이며, 단양 고수동굴과 삼척 환선굴이 유명하다.\n\n지형은 사람들의 생활에 영향을 준다. 석회암 지대에서는 석회암을 원료로 하는 시멘트 공업이 발달했다. 화산 지형과 석회 동굴은 관광 자원으로 활용된다."}],"concepts":[{"term":"동고서저","desc":"동쪽이 높고 서쪽이 낮은 한반도의 지형 특징이다. 큰 하천이 대부분 서해와 남해로 흐르는 까닭이 된다."},{"term":"충적 평야","desc":"하천이 운반한 흙과 모래가 쌓여 만들어진 평야이다. 범람원과 삼각주가 있으며 벼농사에 유리하다."},{"term":"리아스 해안","desc":"해안선이 복잡하게 들쭉날쭉하고 섬이 많은 해안이다. 우리나라 서해안과 남해안에서 볼 수 있다."},{"term":"칼데라","desc":"화산 꼭대기가 함몰되어 생긴 커다란 우묵한 땅이다. 백두산 천지와 울릉도 나리 분지가 사례이다."},{"term":"카르스트 지형","desc":"석회암이 빗물이나 지하수에 녹아 만들어진 지형이다. 돌리네와 석회 동굴이 대표적이다."}]},{"id":"s2-g08-2","title":"기후","standard":{"text":null},"sections":[{"title":"우리나라 기후의 특징","text":"우리나라는 중위도의 대륙 동쪽에 있어 사계절이 뚜렷하다. 여름에는 덥고 비가 많으며, 겨울에는 춥고 건조하다. 그래서 가장 더운 달과 가장 추운 달의 기온 차이인 기온의 연교차가 크다.\n\n기온은 지역에 따라 다르다. 위도가 높은 북쪽으로 갈수록 기온이 낮다. 같은 위도라도 해발 고도가 높은 산지는 기온이 낮다. 또 위도가 비슷하면 동해안이 서해안보다 겨울에 따뜻하다. 태백산맥이 차가운 북서풍을 막아 주고, 수심이 깊은 동해가 열을 오래 간직하기 때문이다.\n\n이런 차이 때문에 남해안은 겨울이 온화하고, 북부 내륙과 높은 산지는 겨울이 몹시 춥다. 같은 나라 안에서도 김장 시기와 봄꽃이 피는 시기가 지역마다 다르다."},{"title":"계절풍과 강수","text":"계절풍은 계절에 따라 방향이 바뀌는 바람이다. 대륙과 바다가 데워지고 식는 속도가 다르기 때문에 생긴다. 겨울에는 시베리아 고기압의 영향으로 춥고 건조한 북서 계절풍이 분다. 여름에는 북태평양 고기압의 영향으로 덥고 습한 남동·남서 계절풍이 분다.\n\n남한의 대부분 지역은 연 강수량이 1,000mm를 넘는 습윤한 기후이다. 그러나 비가 고르게 내리지 않는다. 연 강수량의 절반 이상이 장마와 태풍, 집중 호우가 있는 여름에 내린다. 반면 겨울과 봄에는 비가 적어 가뭄이 들기도 한다.\n\n강수량은 지역마다도 다르다. 바다에서 오는 습한 바람이 산지에 부딪혀 올라가는 곳은 비가 많다. 제주도와 남해안이 대표적인 다우지이다. 반면 산지로 둘러싸인 영남 내륙 등은 비가 적은 소우지이다. 겨울에는 울릉도와 영동 지방에 눈이 많이 내린다."},{"title":"기후에 적응한 생활 모습","text":"우리 조상은 기후에 맞추어 생활 방식을 발전시켰다. 겨울 추위를 견디기 위해 방바닥을 데우는 온돌을 만들었다. 여름 더위를 피하기 위해 바람이 잘 통하는 대청마루를 두었다.\n\n가옥 구조도 지역의 기후에 따라 다르다. 추운 북부 지방은 열이 빠져나가지 않도록 방을 두 줄로 붙여 배치한 겹집이 많다. 따뜻한 남부 지방은 방을 한 줄로 배치해 바람이 잘 통하는 홑집이 많다. 눈이 많은 울릉도에서는 집 둘레에 우데기라는 벽을 둘러 눈을 막았다. 바람이 강한 제주도에서는 돌담을 쌓고 지붕을 줄로 묶었다.\n\n오늘날에도 기후는 생활에 영향을 준다. 겨울이 오기 전 김장을 하고, 여름 장마철에는 습기를 줄이는 데 신경 쓴다. 기후 특성은 농사 시기와 관광, 에너지 사용량에도 영향을 준다."}],"concepts":[{"term":"기온의 연교차","desc":"가장 더운 달과 가장 추운 달의 평균 기온 차이이다. 대륙 동쪽에 있는 우리나라는 연교차가 큰 편이다."},{"term":"계절풍","desc":"계절에 따라 방향이 바뀌는 바람이다. 우리나라는 겨울에 북서 계절풍, 여름에 남동·남서 계절풍이 분다."},{"term":"장마","desc":"초여름에 정체 전선이 머물며 오랫동안 비가 내리는 현상이다. 여름철 강수 집중의 중요한 원인이다."},{"term":"다우지와 소우지","desc":"강수량이 많은 지역을 다우지, 적은 지역을 소우지라고 한다. 제주도·남해안은 다우지, 영남 내륙은 소우지이다."},{"term":"우데기","desc":"눈이 많이 내리는 울릉도의 전통 가옥에서 집 둘레에 친 바깥벽이다. 눈이 쌓여도 집 안에서 움직일 공간을 확보해 준다."}]},{"id":"s2-g08-3","title":"자연재해와 기후 변화","standard":{"text":null},"sections":[{"title":"우리나라의 자연재해","text":"자연재해는 자연 현상 때문에 사람의 생명과 재산이 피해를 입는 것이다. 우리나라에서는 기후와 관련된 재해가 많다.\n\n여름에는 장마와 집중 호우로 홍수가 나고 산사태가 일어난다. 여름부터 초가을에는 열대 저기압인 태풍이 강한 바람과 많은 비를 몰고 온다. 비가 적은 봄과 겨울에는 가뭄이 들기도 한다. 겨울에는 폭설과 한파가, 여름에는 폭염이 생활을 위협한다. 봄에는 중국과 몽골의 건조 지역에서 날아오는 황사가 나타난다.\n\n땅의 움직임으로 생기는 재해도 있다. 한반도는 판의 경계에서 떨어져 있어 지진이 비교적 적다. 그러나 2016년 경주(규모 5.8)와 2017년 포항(규모 5.4)에서 큰 지진이 일어나 지진 대비의 중요성이 커졌다."},{"title":"자연재해에 대비하는 방법","text":"자연재해를 완전히 막을 수는 없지만 피해는 줄일 수 있다. 정부와 지방 자치 단체는 다목적 댐과 저수지, 빗물을 모아 두는 저류 시설, 하천 제방을 만든다. 산사태 위험 지역에는 사방 공사를 한다. 건물에는 내진 설계를 적용한다.\n\n예보와 경보 체계도 중요하다. 기상청은 태풍과 호우의 진로와 강도를 예보한다. 큰 재난이 예상되면 휴대 전화로 긴급 재난 문자가 발송된다.\n\n개인도 행동 요령을 알아 두어야 한다. 지진이 나면 탁자 밑에 들어가 몸을 보호하고, 흔들림이 멈추면 계단을 이용해 넓은 공터로 대피한다. 호우 때는 하천변과 지하 공간에 가지 않는다. 비상용품을 미리 준비하고 우리 동네 대피 장소를 알아 두는 것도 좋다."},{"title":"기후 변화와 우리 생활","text":"기후 변화는 오랜 기간에 걸쳐 기후가 달라지는 현상이다. 오늘날에는 화석 연료 사용으로 온실가스가 늘어 지구의 평균 기온이 오르는 지구 온난화가 대표적이다.\n\n우리나라도 기온이 오르고 있다. 여름은 길어지고 겨울은 짧아졌으며, 봄꽃이 피는 시기도 빨라졌다. 사과 같은 작물의 재배지는 점점 북쪽으로 옮겨 가고, 남부 지방에서는 아열대 작물을 기르기도 한다. 동해에서 잡히던 명태 같은 찬물 어종은 크게 줄었다. 어린 명태(노가리)까지 많이 잡은 남획과 바닷물 온도 상승이 함께 영향을 준 것으로 본다. 폭염과 집중 호우 같은 극한 기상 현상도 잦아지고 있다.\n\n기후 변화에 대응하는 방법은 두 가지이다. 온실가스 배출을 줄이는 완화와, 이미 일어나는 변화에 맞추는 적응이다. 재생 에너지를 늘리고 에너지를 아끼는 것은 완화에 해당한다. 더위에 강한 품종을 개발하고 방재 시설을 보강하는 것은 적응에 해당한다."}],"concepts":[{"term":"자연재해","desc":"자연 현상 때문에 사람의 생명과 재산이 피해를 입는 것이다. 기후적 재해와 지형적 재해로 나눌 수 있다."},{"term":"태풍","desc":"강한 바람과 많은 비를 동반하는 열대 저기압이다. 우리나라에는 주로 여름부터 초가을에 영향을 준다."},{"term":"내진 설계","desc":"지진의 흔들림을 견딜 수 있도록 건물이나 시설을 설계하는 것이다."},{"term":"지구 온난화","desc":"온실가스가 늘어 지구의 평균 기온이 올라가는 현상이다."},{"term":"완화와 적응","desc":"완화는 온실가스 배출을 줄여 기후 변화를 늦추는 것이고, 적응은 이미 나타난 변화에 맞추어 피해를 줄이는 것이다."}]}]},"s2-g09":{"title":"중부 지역","lessons":[{"id":"s2-g09-1","title":"수도권의 집중과 공간 변화","standard":{"text":null},"sections":[{"title":"수도권 집중이란","text":"수도권은 서울특별시, 인천광역시, 경기도를 합친 지역이다. 수도권의 면적은 국토의 약 12%에 불과하다. 그러나 전체 인구의 절반 이상이 이곳에 산다(2020년대 기준).\n\n수도권에는 인구만 모여 있는 것이 아니다. 중앙 행정 기관, 기업 본사, 금융 기관, 대학, 문화 시설도 많이 모여 있다. 이처럼 인구와 기능이 한 지역에 몰리는 현상을 집중이라고 한다.\n\n수도권 집중은 편리함과 문제를 함께 낳는다. 일자리와 서비스를 얻기 쉽지만 집값 상승, 교통 혼잡, 환경 오염이 심해진다. 반대로 지방은 인구가 줄어 지역 간 격차가 커진다."},{"title":"수도권이 커지고 넓어진 과정","text":"수도권 집중은 1960년대 이후 산업화와 함께 본격화되었다. 서울과 그 주변에 공장과 일자리가 늘었다. 그러자 농촌의 많은 사람이 일자리를 찾아 서울로 이동하였다. 이를 이촌 향도라고 한다.\n\n서울에 인구가 몰리자 주택이 부족해졌다. 정부는 1989년 계획을 발표하고 1990년대 초 분당, 일산 등 서울 주변에 대규모 1기 신도시를 건설하였다. 이후에도 판교, 동탄 등 신도시가 계속 생겼다. 사람들이 도시 중심에서 주변 지역으로 퍼져 나가는 현상을 교외화라고 한다.\n\n교외화로 서울 주변 도시는 서울과 긴밀하게 연결되었다. 서울로 출퇴근하는 사람이 많이 사는 주변 도시를 위성 도시라고 한다. 서울과 주변 도시가 하나의 생활권으로 묶이면서 수도권 대도시권이 형성되었다."},{"title":"수도권의 공간 변화와 균형 발전","text":"수도권의 공간 구조는 지금도 변하고 있다. 서울 도심에는 업무·상업 기능이 모이고, 주거 기능은 주변 신도시로 옮겨 갔다. 집과 직장이 멀어지면서 광역 버스와 광역 철도 같은 교통망이 확충되었다. 공장도 땅값이 비싼 서울을 떠나 경기도와 충청 지역으로 옮겨 갔다.\n\n정부는 수도권 집중을 완화하려고 여러 정책을 펼쳤다. 세종특별자치시에 행정 중심 복합 도시를 건설하여 중앙 행정 기관 일부를 옮겼다. 또 전국 여러 곳에 혁신 도시를 만들어 공공 기관을 지방으로 이전하였다.\n\n우리 생활에서도 수도권 집중의 영향을 확인할 수 있다. 출퇴근 시간의 붐비는 광역 버스, 명절과 주말의 고속 국도 정체는 수도권 집중과 관련이 깊다."}],"concepts":[{"term":"수도권","desc":"서울특별시, 인천광역시, 경기도를 합친 지역이다."},{"term":"집중","desc":"인구와 기업, 행정 기관 같은 기능이 특정 지역에 몰리는 현상이다."},{"term":"교외화","desc":"도시 중심의 주거 기능과 인구가 주변 지역으로 퍼져 나가는 현상이다."},{"term":"위성 도시","desc":"대도시 주변에 있으면서 대도시의 기능 일부를 나누어 맡는 도시이다. 대도시로 출퇴근하는 주민이 많다."},{"term":"혁신 도시","desc":"수도권의 공공 기관을 지방으로 옮겨 지역 발전의 거점으로 만들려고 조성한 도시이다."}]},{"id":"s2-g09-2","title":"강원·충청 지역의 변화","standard":{"text":null},"sections":[{"title":"강원 지역의 자연과 산업 변화","text":"강원 지역은 태백산맥을 경계로 동쪽의 영동 지방과 서쪽의 영서 지방으로 나뉜다. 영동 지방은 산맥이 차가운 북서풍을 막아 주어 같은 위도의 영서 지방보다 겨울이 덜 춥다. 대관령처럼 해발 고도가 높은 곳은 여름이 서늘하다.\n\n이런 환경 덕분에 강원 지역은 고랭지 농업이 발달하였다. 여름에 서늘한 기후를 이용해 배추, 무, 감자 등을 재배한다. 또 태백, 정선, 영월 일대는 과거 석탄 산업의 중심지였다.\n\n1980년대 후반 석탄 소비가 줄고 1989년 무렵부터 석탄 산업 합리화 정책이 시행되면서 많은 탄광이 문을 닫았다. 인구가 크게 줄자 폐광 지역은 리조트, 카지노, 탄광 체험 시설 같은 관광 산업으로 새로운 길을 찾았다."},{"title":"교통 발달과 강원 지역의 새로운 변화","text":"강원 지역은 산지가 많아 오랫동안 다른 지역과 오가기 어려웠다. 그러나 고속 국도와 고속 철도가 놓이면서 수도권과의 이동 시간이 크게 줄었다. 2018년 평창 동계 올림픽을 앞둔 2017년 12월, 서울과 강릉을 잇는 고속 철도(경강선)가 개통되었다.\n\n접근성이 좋아지자 관광객이 늘었다. 동해안의 해수욕장, 산지의 스키장, 계곡과 휴양림이 주요 관광지가 되었다. 깨끗한 자연환경을 활용한 휴양·레저 산업도 성장하고 있다.\n\n2023년에는 강원도가 강원특별자치도로 출범하였다. 지역의 특성에 맞는 발전 방안을 스스로 마련할 수 있는 권한이 넓어졌다. 앞으로는 자연환경 보전과 지역 개발 사이의 균형을 찾는 것이 중요한 과제이다."},{"title":"충청 지역의 성장","text":"충청 지역은 수도권과 맞닿아 있고 경부선, 호남선 같은 주요 교통로가 지나는 곳이다. 그래서 수도권의 기능이 옮겨 오기 좋은 위치에 있다.\n\n수도권의 땅값이 오르고 공장 신설이 제한되자 많은 공장이 충청 지역으로 옮겨 왔다. 천안, 아산 일대에는 전자·자동차 공업이 발달하였다. 서해안의 당진에는 제철 공업, 서산에는 석유 화학 공업이 발달하였다. 대전에는 대덕 연구 단지가 있어 과학 기술 연구의 중심지 역할을 한다.\n\n세종특별자치시에 행정 중심 복합 도시가 건설되면서 중앙 행정 기관이 옮겨 왔다. 충청 지역은 공업, 연구, 행정 기능이 모이며 인구가 늘어나는 지역이 되었다. 다만 성장은 수도권과 가까운 북부 지역에 더 집중되는 경향이 있다."}],"concepts":[{"term":"영동·영서 지방","desc":"태백산맥을 경계로 나눈 강원 지역의 동쪽과 서쪽 지방이다."},{"term":"고랭지 농업","desc":"해발 고도가 높은 곳의 서늘한 여름 기후를 이용해 배추, 무, 감자 등을 기르는 농업이다."},{"term":"석탄 산업 합리화 정책","desc":"1980년대 후반 석탄 수요가 줄자 경제성이 낮은 탄광을 정리한 정책이다."},{"term":"행정 중심 복합 도시","desc":"수도권 집중을 완화하려고 세종특별자치시에 건설한, 중앙 행정 기관이 모인 도시이다."},{"term":"대덕 연구 단지","desc":"대전에 있는 과학 기술 연구 기관 밀집 지역이다."}]}]},"s2-g10":{"title":"남부 지역","lessons":[{"id":"s2-g10-1","title":"영남·호남 지역의 특성","standard":{"text":null},"sections":[{"title":"남부 지역의 범위와 자연환경","text":"남부 지역은 영남 지방, 호남 지방, 제주도를 포함한다. 이 학습에서는 영남과 호남을 다룬다. 영남 지방은 부산, 대구, 울산과 경상남·북도이다. 호남 지방은 광주와 전라남도, 전북특별자치도이다. 두 지방은 소백산맥을 사이에 두고 있다.\n\n두 지방은 자연환경이 다르다. 영남 지방은 낙동강이 흐르며 분지와 산지가 많다. 대구처럼 분지에 있는 도시는 여름이 매우 덥다. 호남 지방은 서쪽에 넓은 평야가 펼쳐져 있다. 남해안과 서해안은 해안선이 복잡하고 섬이 많다.\n\n자연환경의 차이는 산업의 차이로 이어졌다. 평야가 넓은 호남은 농업이 발달하였다. 항구가 발달한 영남 해안은 공업이 먼저 크게 성장하였다."},{"title":"영남 지방: 우리나라 공업의 중심","text":"영남 지방의 남동 해안에는 공업 도시가 띠 모양으로 이어져 있다. 이를 남동 임해 공업 지역이라고 한다. 울산은 자동차·조선·석유 화학, 포항은 제철, 창원은 기계, 거제는 조선 공업이 발달하였다.\n\n이 지역에 공업이 모인 이유는 바다와 가깝기 때문이다. 원료를 수입하고 제품을 수출하기에 편리하다. 또 1970년대 정부가 중화학 공업을 육성하면서 이 지역에 공업 단지를 집중적으로 조성하였다.\n\n부산은 우리나라 최대의 항구 도시로, 컨테이너 화물이 많이 오가는 물류 중심지이다. 내륙의 대구는 섬유 공업으로 성장하였고, 구미는 전자 공업 도시로 발달하였다. 경주, 안동 등은 역사 문화 관광지로 유명하다."},{"title":"호남 지방: 농업과 바다, 새로운 산업","text":"호남 지방에는 만경강, 동진강, 영산강 유역을 따라 넓은 평야가 있다. 호남평야와 나주평야는 우리나라의 대표적인 쌀 생산지이다.\n\n서해안과 남해안에는 넓은 갯벌과 많은 섬이 있다. 갯벌에서는 조개 등을 채취하고, 남해안의 잔잔한 바다에서는 김, 미역, 전복 등을 양식한다. 충남 서천, 전북 고창, 전남 신안, 전남 보성·순천의 갯벌은 2021년 '한국의 갯벌'이라는 이름으로 유네스코 세계 자연 유산에 등재되었다.\n\n공업도 성장하였다. 여수에는 석유 화학, 광양에는 제철 공업이 발달하였다. 광주는 자동차 공업과 빛을 다루는 광산업을 키우고 있다. 전북 서해안에서는 새만금 간척 사업이 진행되고 있다."}],"concepts":[{"term":"영남·호남 지방","desc":"소백산맥 동남쪽의 경상도 일대를 영남, 서쪽의 전라도 일대를 호남이라고 한다."},{"term":"남동 임해 공업 지역","desc":"울산, 포항, 창원, 거제 등 남동 해안을 따라 발달한 중화학 공업 지역이다."},{"term":"갯벌","desc":"밀물 때 물에 잠기고 썰물 때 드러나는 해안의 넓고 평평한 땅이다. 생물이 많고 오염 물질을 정화한다."},{"term":"간척","desc":"바다나 호수에 둑을 쌓고 물을 빼서 육지로 만드는 일이다."}]},{"id":"s2-g10-2","title":"제주의 화산 지형과 생활","standard":{"text":null},"sections":[{"title":"제주도는 어떻게 만들어졌을까","text":"제주도는 화산 활동으로 만들어진 화산섬이다. 신생대에 여러 차례 화산이 분출하면서 용암과 화산 쇄설물이 쌓여 섬이 되었다. 섬 가운데에는 한라산이 솟아 있다. 한라산은 해발 1,947m로 남한에서 가장 높은 산이다.\n\n한라산 꼭대기에는 화구에 물이 고인 화구호인 백록담이 있다. 산기슭에는 오름이라고 부르는 작은 화산이 360여 개(약 368개) 흩어져 있다. 오름은 큰 화산의 주변에서 작은 분화가 일어나 생긴 기생 화산이다.\n\n제주의 화산 지형은 학술적 가치가 높다. 2007년 '제주 화산섬과 용암 동굴'이 유네스코 세계 자연 유산에 등재되었다."},{"title":"다양한 화산 지형","text":"용암이 흐르며 만든 지형도 있다. 용암 동굴은 흐르던 용암의 겉이 먼저 식어 굳고, 속의 뜨거운 용암이 빠져나가면서 생긴 긴 동굴이다. 만장굴, 김녕굴 등이 대표적이다.\n\n주상 절리는 뜨거운 용암이 식으면서 부피가 줄어 갈라져 생긴 기둥 모양의 바위이다. 서귀포 중문 해안의 주상 절리가 유명하다. 성산 일출봉은 얕은 바다에서 마그마가 물과 만나 격렬하게 폭발하며 만들어진 화산체이다.\n\n제주도를 이루는 대표 암석은 현무암이다. 현무암은 용암 속 가스가 빠져나가며 생긴 구멍이 많은 검은색 암석이다. 이 암석은 제주의 경관과 생활에 큰 영향을 주었다."},{"title":"화산 지형에 적응한 제주의 생활","text":"제주도는 비가 많이 내리는 지역이다. 하지만 현무암에 틈과 구멍이 많아 빗물이 땅속으로 잘 스며든다. 그래서 대부분의 하천은 평소 물이 흐르지 않는 건천이다. 땅속으로 스며든 물은 해안가에서 용천수로 솟아난다. 이 용천수 주변에 마을이 발달하였다.\n\n물이 잘 빠지는 땅은 논농사에 불리하다. 그래서 제주에서는 밭농사가 중심이다. 따뜻한 기후를 이용해 감귤을 재배한다. 밭과 집 둘레에는 현무암을 쌓은 돌담을 세워 강한 바람을 막았다. 바다에서 해산물을 채취하는 해녀 문화도 발달하였다.\n\n오늘날 제주는 독특한 화산 경관을 바탕으로 우리나라의 대표 관광지가 되었다. 동시에 관광객 증가에 따른 환경 보전 문제도 함께 고민하고 있다."}],"concepts":[{"term":"오름","desc":"큰 화산의 주변에서 작은 분화로 생긴 기생 화산을 제주에서 부르는 말이다."},{"term":"용암 동굴","desc":"흐르던 용암의 겉이 먼저 굳고 속의 용암이 빠져나가 생긴 동굴이다."},{"term":"주상 절리","desc":"용암이 식으면서 수축해 갈라진 기둥 모양의 바위이다."},{"term":"현무암","desc":"용암이 빨리 식어 만들어진 검은색 화산암이다. 가스가 빠져나간 구멍이 많다."},{"term":"용천수","desc":"땅속을 흐르던 물이 지표로 솟아 나오는 샘물이다. 제주에서는 주로 해안가에서 솟는다."}]}]},"s2-g11":{"title":"북부 지역","lessons":[{"id":"s2-g11-1","title":"북부 지역의 자연환경","standard":{"text":null},"sections":[{"title":"북부 지역의 지형","text":"북부 지역은 휴전선 북쪽의 한반도 지역을 말한다. 면적은 약 12만㎢로 남한(약 10만㎢)보다 넓다. 북부 지역은 남부보다 산지의 비율이 높고 평균 해발 고도도 높다.\n\n동북쪽에는 낭림산맥과 함경산맥이 뻗어 있다. 그 사이에는 해발 고도가 높고 평탄한 개마고원이 있어 '한반도의 지붕'이라고 부른다. 북쪽 끝에는 한반도에서 가장 높은 백두산(약 2,744m)이 있다. 백두산 꼭대기에는 분화구 주변이 꺼져 생긴 칼데라호인 천지가 있다.\n\n평야는 주로 서쪽에 있다. 대동강 유역의 평양평야, 황해도의 재령평야 등이 대표적이다. 북쪽 국경에는 압록강과 두만강이 흐른다."},{"title":"북부 지역의 기후","text":"북부 지역은 남부 지역보다 위도가 높고 대륙과 가깝다. 그래서 겨울이 길고 춥다. 가장 더운 달과 가장 추운 달의 기온 차이인 기온의 연교차도 크다.\n\n같은 북부 지역이라도 지역마다 기후가 다르다. 압록강 상류의 중강진 일대와 개마고원은 겨울에 매우 춥다. 중강진은 한반도에서 가장 낮은 기온이 관측된 곳으로 알려져 있다. 반면 동해안은 함경산맥이 차가운 북서풍을 막고 바다의 영향을 받아 같은 위도의 내륙보다 겨울이 덜 춥다.\n\n강수량은 대체로 남부 지역보다 적다. 특히 개마고원 일대 등은 비가 적게 내리는 소우지이다. 이러한 기후는 기를 수 있는 농작물의 종류와 주민의 생활 방식에 큰 영향을 준다."},{"title":"자연환경과 자원","text":"북부 지역에는 지하자원이 풍부하다. 석탄, 철광석, 마그네사이트 등이 많이 묻혀 있다. 이 자원은 북부 지역 공업 발달의 바탕이 되었다.\n\n산지가 많고 경사가 급한 하천은 수력 발전에 유리하다. 물이 높은 곳에서 낮은 곳으로 떨어지는 힘, 즉 낙차를 이용할 수 있기 때문이다. 그래서 압록강과 그 지류 등에 일찍부터 수력 발전소가 세워졌다.\n\n추운 기후와 산지는 농업에 제약이 된다. 벼농사는 서부 평야와 동해안 일부에서 이루어진다. 산지와 고원에서는 감자, 옥수수 같은 밭작물을 주로 기른다. 백두산과 개마고원 일대에는 침엽수림이 넓게 펼쳐져 있다."}],"concepts":[{"term":"개마고원","desc":"낭림산맥과 함경산맥 사이의 높고 평탄한 고원으로 '한반도의 지붕'이라 불린다."},{"term":"칼데라호","desc":"화산 꼭대기의 분화구 주변이 꺼져 생긴 큰 분지에 물이 고인 호수이다. 백두산 천지가 대표적이다."},{"term":"기온의 연교차","desc":"일 년 중 가장 더운 달과 가장 추운 달의 평균 기온 차이이다."},{"term":"소우지","desc":"주변 지역보다 강수량이 적은 지역이다."}]},{"id":"s2-g11-2","title":"북부 지역의 인문 환경과 통일 국토","standard":{"text":null},"sections":[{"title":"북부 지역의 인구와 도시","text":"북부 지역의 인구는 약 2,600만 명으로 추정된다. 인구는 기후가 비교적 온화하고 평야가 넓은 서부 지역에 많이 산다. 산지가 많은 동북부 내륙은 인구가 적다.\n\n가장 큰 도시는 평양이다. 평양은 대동강 유역의 평야에 자리 잡은 정치·경제·문화의 중심지이다. 남포는 대동강 하구의 항구 도시로 평양의 관문 역할을 한다. 신의주는 압록강을 사이에 두고 중국과 마주한 국경 도시로, 중국과의 교역 통로이다. 동해안에는 함흥, 청진 같은 공업 도시가 있다.\n\n북부 지역에 관한 통계는 공개된 자료가 적다. 그래서 인구나 생산량 같은 수치는 추정치가 많다는 점을 알고 읽어야 한다."},{"title":"북부 지역의 산업과 교통","text":"북부 지역의 공업은 풍부한 지하자원을 바탕으로 한 중화학 공업 중심으로 발달하였다. 지하자원이 많은 지역과 항구 주변에 공업 지역이 형성되었다.\n\n농업은 논보다 밭의 비중이 크다. 춥고 산지가 많기 때문이다. 식량을 늘리려고 산비탈을 개간해 계단 모양의 다락밭을 만들기도 하였다. 그러나 산림이 줄어 홍수와 산사태 피해가 커지는 문제가 생겼다.\n\n교통은 철도가 중심이고 도로는 보조 역할을 한다. 산지가 많은 동북부는 교통로를 놓기 어려워 다른 지역과의 연결이 불리하다. 또 외국과의 경제 협력을 위해 일부 지역을 경제특구로 지정하였다. 두만강 하구의 나선(라선) 지역과 신의주 등이 대표적이다."},{"title":"남북 교류와 통일 국토의 의미","text":"남북은 분단 이후에도 여러 차례 교류하였다. 1998년 금강산 관광이 시작되었다. 2000년대에는 개성 공업 지구가 조성되어 남측 기업이 북측 노동력과 함께 제품을 생산하였다. 금강산 관광은 2008년, 개성 공업 지구는 2016년에 중단되었다.\n\n통일은 국토 공간에 큰 변화를 가져올 수 있다. 한반도는 대륙과 해양을 잇는 반도이다. 막혀 있는 육로가 이어지면 철도로 중국, 러시아를 거쳐 유럽까지 사람과 물자가 오갈 수 있다. 남북의 자원과 기술이 서로 보완될 수 있다는 기대도 있다. 한편 통일 과정에는 비용 부담과 사회 통합 같은 과제도 따른다.\n\n군사 분계선 남북의 비무장 지대(DMZ)는 오랫동안 출입이 제한되어 생태계가 잘 보전되었다. 이 공간을 어떻게 보전하고 활용할지도 통일 국토의 과제이다."}],"concepts":[{"term":"다락밭","desc":"산비탈을 개간하여 계단 모양으로 만든 밭이다."},{"term":"경제특구","desc":"외국 자본과 기술을 끌어들이려고 세금·제도상 혜택을 주는 특별 지역이다."},{"term":"개성 공업 지구","desc":"개성에 조성되어 남측 기업과 북측 노동력이 함께 제품을 생산한 남북 경제 협력 공간이다. 2016년에 가동이 중단되었다."},{"term":"비무장 지대(DMZ)","desc":"군사 분계선을 기준으로 남북 각각 2km 구역에 군대와 무기 배치를 금지한 지대이다."}]}]},"s2-g12":{"title":"지속가능한 세계와 글로컬 시민","lessons":[{"id":"s2-g12-1","title":"지구적 불평등","standard":{"text":null},"sections":[{"title":"지구적 불평등이란","text":"지구적 불평등은 나라와 지역에 따라 소득, 건강, 교육 수준의 차이가 크게 나타나는 현상이다. 어떤 나라 사람들은 풍족한 생활을 누린다. 다른 나라 사람들은 깨끗한 물, 충분한 식량, 기본 교육조차 얻기 어렵다.\n\n소득이 높고 산업이 발달한 나라를 선진국, 경제 발전이 진행 중인 나라를 개발 도상국이라고 한다. 선진국은 주로 북반구에, 개발 도상국은 상대적으로 남반구에 많다. 그래서 이 격차를 남북 문제라고 부르기도 한다.\n\n불평등은 나라 사이에만 있지 않다. 한 나라 안에서도 도시와 농촌, 지역과 계층 사이에 격차가 나타난다. 그래서 지구적 불평등을 이해하려면 세계, 국가, 지역 등 여러 공간 규모에서 격차를 함께 살펴보아야 한다."},{"title":"발전 수준을 재는 지표","text":"나라의 발전 수준을 비교할 때는 여러 지표를 쓴다. 대표적인 경제 지표는 1인당 국내 총생산(GDP)이다. 한 나라에서 일정 기간 생산한 가치를 인구로 나눈 값이다.\n\n그러나 소득만으로 삶의 질을 다 알 수는 없다. 그래서 국제 연합 개발 계획(UNDP)은 인간 개발 지수(HDI)를 발표한다. 인간 개발 지수는 기대 수명, 교육 수준, 1인당 국민 총소득을 함께 반영한다. 이 밖에 영아 사망률, 성인 문해율, 안전한 식수 이용률 등도 발전 수준을 보여 준다.\n\n개발 도상국은 대체로 기대 수명이 짧고 영아 사망률이 높다. 여러 지표를 함께 보면 한 나라의 상황을 더 정확히 이해할 수 있다."},{"title":"불평등의 원인과 해결 노력","text":"지구적 불평등의 원인은 여러 가지이다. 과거 식민 지배를 받으며 자원을 빼앗기고 산업 기반을 갖추지 못한 나라가 많다. 농산물, 광물 같은 1차 산품 수출에 의존하는 나라는 국제 가격 변동에 취약하다. 내전과 분쟁, 정치 불안도 발전을 가로막는다.\n\n국제 사회는 격차를 줄이려고 노력한다. 국제 연합은 2015년 지속 가능 발전 목표(SDGs)를 채택하여 빈곤 퇴치, 교육, 보건 등 17개 목표를 세웠다. 각국 정부는 공적 개발 원조(ODA)를 제공하고, 비정부 기구(NGO)도 현장에서 활동한다. 생산자에게 정당한 대가를 주는 공정 무역도 해결 방법 중 하나이다.\n\n우리나라는 6·25 전쟁 이후 원조를 받던 나라였다. 지금은 다른 나라에 원조를 제공하는 나라가 되었다."}],"concepts":[{"term":"선진국·개발 도상국","desc":"소득이 높고 산업이 발달한 나라를 선진국, 경제 발전이 진행 중인 나라를 개발 도상국이라고 한다."},{"term":"인간 개발 지수(HDI)","desc":"기대 수명, 교육 수준, 1인당 국민 총소득을 종합해 삶의 질을 나타내는 지표로, 국제 연합 개발 계획이 발표한다."},{"term":"남북 문제","desc":"주로 북반구에 있는 선진국과 남반구에 많은 개발 도상국 사이의 경제적 격차 문제이다."},{"term":"공적 개발 원조(ODA)","desc":"정부가 개발 도상국의 경제 발전과 복지 향상을 위해 제공하는 원조이다."},{"term":"공정 무역","desc":"개발 도상국 생산자에게 정당한 가격을 보장하려는 무역 방식이다."}]},{"id":"s2-g12-2","title":"지구 환경 문제","standard":{"text":null},"sections":[{"title":"지구 환경 문제의 특징","text":"지구 환경 문제는 한 지역에서 시작되어도 국경을 넘어 지구 전체에 영향을 주는 환경 문제이다. 기후 변화, 사막화, 열대림 파괴, 오존층 파괴 등이 대표적이다.\n\n이 문제들은 원인을 만든 곳과 피해를 입는 곳이 다를 때가 많다. 예를 들어 온실가스는 주로 산업이 발달한 지역에서 많이 배출되었다. 그러나 해수면 상승의 피해는 해발 고도가 낮은 섬나라가 크게 입는다.\n\n그래서 지구 환경 문제는 한 나라의 노력만으로 해결하기 어렵다. 여러 나라가 함께 약속하고 협력해야 한다. 국제 협약을 맺고, 기술과 자금을 나누며, 각 나라가 정한 약속을 지키는 노력이 함께 이루어져야 한다."},{"title":"기후 변화와 온실 효과","text":"지구의 대기에는 이산화 탄소, 메테인(메탄) 같은 온실가스가 있다. 온실가스는 지표에서 우주로 나가는 열의 일부를 붙잡아 지구를 따뜻하게 한다. 이를 온실 효과라고 한다.\n\n문제는 온실가스가 지나치게 늘어난 것이다. 산업 혁명 이후 석탄, 석유 같은 화석 연료 사용이 크게 늘었다. 숲을 없애 이산화 탄소를 흡수하는 식물도 줄었다. 그 결과 지구의 평균 기온이 오르는 지구 온난화가 나타났다.\n\n지구 온난화로 빙하가 녹고 해수면이 높아진다. 폭염, 가뭄, 집중 호우 같은 극한 기상도 잦아진다. 우리나라에서도 사과 같은 작물의 재배 적지가 북쪽으로 옮겨 가는 등 변화가 나타나고 있다."},{"title":"여러 지구 환경 문제와 국제 협력","text":"사막화는 가뭄과 지나친 방목, 경작 등으로 땅이 메말라 사막처럼 변하는 현상이다. 사하라 사막 남쪽의 사헬 지대가 대표적이다. 열대림 파괴는 목축지나 농경지를 만들려고 아마존 등의 열대림을 베어 내는 것이다. 열대림이 줄면 생물 종이 줄고 이산화 탄소 흡수량도 줄어든다.\n\n국제 사회는 협약을 맺어 대응한다. 1987년 몬트리올 의정서는 오존층을 파괴하는 프레온 가스(염화 플루오린화 탄소) 사용을 규제하였다. 2015년 파리 협정에서는 지구 평균 기온 상승을 산업화 이전보다 2℃보다 훨씬 낮게 유지하고, 1.5℃로 제한하도록 노력하기로 하였다.\n\n국제 협약은 각 나라의 실천이 뒤따를 때 효과가 있다."}],"concepts":[{"term":"온실 효과","desc":"대기 중 온실가스가 지표에서 나가는 열의 일부를 붙잡아 지구를 따뜻하게 유지하는 현상이다."},{"term":"지구 온난화","desc":"온실가스 증가로 지구의 평균 기온이 오르는 현상이다."},{"term":"사막화","desc":"가뭄과 지나친 방목·경작 등으로 땅이 메말라 사막처럼 변하는 현상이다."},{"term":"파리 협정","desc":"2015년에 채택된 기후 변화 대응 국제 협정으로, 지구 평균 기온 상승을 산업화 이전보다 2℃보다 훨씬 낮게 유지하는 것을 목표로 한다."}]},{"id":"s2-g12-3","title":"글로컬 시민의 실천","standard":{"text":null},"sections":[{"title":"글로컬 시민이란","text":"글로컬(glocal)은 세계적(global)과 지역적(local)을 합친 말이다. 글로컬 시민은 지구 전체의 문제에 관심을 두면서 자신이 사는 지역에서 실천하는 시민이다. '세계적으로 생각하고 지역적으로 행동하라'는 말이 이 태도를 잘 보여 준다.\n\n오늘날 세계는 무역, 교통, 통신으로 촘촘히 연결되어 있다. 우리가 먹는 음식과 쓰는 물건은 여러 나라를 거쳐 온다. 그래서 지역에서의 선택이 지구 반대편 사람과 환경에 영향을 준다.\n\n글로컬 시민은 지역과 세계를 따로 보지 않는다. 지역 문제를 지구적 시각에서 이해하고, 지구 문제를 지역의 행동으로 풀어 간다."},{"title":"지속 가능한 발전","text":"지속 가능한 발전은 미래 세대가 필요를 충족할 능력을 해치지 않으면서 현재 세대의 필요를 충족하는 발전이다. 1987년 세계 환경 개발 위원회의 보고서 「우리 공동의 미래」를 통해 널리 알려졌다.\n\n지속 가능한 발전은 경제 성장, 사회 통합, 환경 보전의 균형을 강조한다. 경제만 성장하고 환경이 망가지면 미래 세대가 피해를 입는다. 환경만 지키고 빈곤을 내버려 두어도 지속 가능하지 않다.\n\n국제 연합은 2015년 17개의 지속 가능 발전 목표(SDGs)를 채택하였다. 빈곤 퇴치, 양질의 교육, 성평등, 기후 변화 대응 등이 포함된다. 이 목표는 국가뿐 아니라 지역 사회, 기업, 개인이 함께 이루어야 할 과제이다."},{"title":"생활 속 실천","text":"글로컬 시민의 실천은 일상에서 시작된다. 지역에서 생산한 로컬 푸드를 이용하면 운송 거리가 짧아 푸드 마일리지와 탄소 배출을 줄일 수 있다. 공정 무역 상품을 사면 개발 도상국 생산자가 정당한 대가를 받는 데 도움이 된다.\n\n자원을 아끼는 것도 중요한 실천이다. 일회용품을 줄이고, 분리배출을 정확히 하고, 쓰지 않는 전기 제품의 플러그를 뽑는다. 학교와 지역에서 환경 정화 활동이나 캠페인에 참여할 수도 있다.\n\n세계와 직접 연결되는 활동도 있다. 국제 비정부 기구의 활동을 알아보고 캠페인에 참여할 수 있다. 다른 문화를 존중하고 우리 지역에 사는 이주민과 함께 어울리는 것도 글로컬 시민의 자세이다."}],"concepts":[{"term":"글로컬","desc":"세계적(global)과 지역적(local)을 합친 말로, 지구적 관점과 지역적 실천을 함께 강조한다."},{"term":"지속 가능한 발전","desc":"미래 세대의 필요를 충족할 능력을 해치지 않으면서 현재 세대의 필요를 충족하는 발전이다."},{"term":"지속 가능 발전 목표(SDGs)","desc":"2015년 국제 연합이 채택한 17개의 공동 목표로, 빈곤·교육·환경 등 인류의 과제를 담고 있다."},{"term":"로컬 푸드","desc":"소비자가 사는 지역과 가까운 곳에서 생산된 농수산물이다."},{"term":"푸드 마일리지","desc":"식품이 생산지에서 소비자에게 오기까지 이동한 거리를 무게와 함께 나타낸 값이다. 클수록 운송 과정에서 에너지를 많이 쓴다."}]}]},"s2-s07":{"title":"헌법과 국가기관","lessons":[{"id":"s2-s07-1","title":"정부 형태와 행정부","standard":{"text":"우리나라의 정부 형태를 설명하고, 대통령과 행정부의 역할을 탐색한다."},"sections":[{"title":"정부 형태: 대통령제와 의원 내각제","text":"정부 형태는 입법부와 행정부의 관계에 따라 국가 권력을 조직하는 방식이다. 대표적으로 대통령제와 의원 내각제가 있다.\n\n대통령제는 입법부와 행정부가 엄격히 분리된 형태이다. 국민이 대통령과 의회 의원을 각각 선거로 뽑는다. 대통령은 정해진 임기 동안 안정적으로 정책을 추진할 수 있다. 미국이 대표적인 대통령제 국가이다.\n\n의원 내각제는 의회의 다수당이 내각을 구성하는 형태이다. 국민은 의회 의원을 선출하고, 보통 의회 다수당(또는 연립 정당)의 대표가 총리가 되어 내각을 이끈다. 의회는 내각을 불신임할 수 있고, 내각은 의회를 해산할 수 있다. 입법부와 행정부가 긴밀히 협력하는 구조이다. 영국, 일본이 대표적인 의원 내각제 국가이다."},{"title":"우리나라의 정부 형태","text":"우리나라는 대통령제를 기본으로 한다. 국민이 직접 선거로 대통령을 뽑는다. 대통령의 임기는 5년이며 중임할 수 없다. 대통령은 국가 원수이자 행정부 수반이다.\n\n동시에 의원 내각제 요소도 일부 받아들였다. 국무총리를 두고, 국회의 동의를 얻어 대통령이 임명한다. 정부의 중요 정책을 심의하는 국무 회의를 둔다. 정부도 국회에 법률안을 제출할 수 있다. 국무총리와 국무 위원은 국회에 출석해 질문에 답할 수 있다. 국회는 국무총리나 국무 위원의 해임을 대통령에게 건의할 수 있다.\n\n이런 요소를 둔 이유는 대통령에게 권력이 지나치게 집중되는 것을 견제하고 국회와 행정부의 협력을 돕기 위해서이다. 그래서 우리나라 정부 형태를 의원 내각제 요소가 가미된 대통령제라고 설명한다."},{"title":"대통령과 행정부의 역할","text":"대통령은 두 가지 지위를 가진다. 국가 원수로서 외국에 대해 나라를 대표하고 조약을 체결한다. 국군을 통수하고, 헌법재판소장과 대법원장 같은 헌법 기관의 장을 임명한다. 행정부 수반으로서 행정부를 지휘·감독하고, 공무원을 임명하며, 대통령령을 발한다.\n\n행정부는 법을 집행해 국민 생활에 필요한 일을 처리하는 기관이다. 국무총리는 대통령을 보좌하고 행정 각부를 통할한다. 국무 회의는 정부의 중요 정책을 심의하는 최고 심의 기관이다. 대통령이 의장, 국무총리가 부의장을 맡는다.\n\n행정 각부는 교육, 국방, 보건 등 분야별 업무를 맡는다. 감사원은 대통령 소속이지만 직무상 독립된 기관이다. 국가의 결산과 회계를 검사하고 공무원의 직무를 감찰한다. 우리가 받는 교육, 복지, 안전 서비스의 대부분은 행정부의 활동이다."}],"concepts":[{"term":"대통령제","desc":"입법부와 행정부를 엄격히 분리하고, 국민이 뽑은 대통령이 임기 동안 행정부를 이끄는 정부 형태이다."},{"term":"의원 내각제","desc":"의회의 다수당이 내각을 구성하고, 의회와 내각이 서로 불신임·해산으로 견제하는 정부 형태이다."},{"term":"국가 원수와 행정부 수반","desc":"대통령의 두 지위이다. 국가 원수로서 나라를 대표하고, 행정부 수반으로서 행정부를 지휘·감독한다."},{"term":"국무 회의","desc":"정부의 중요 정책을 심의하는 최고 심의 기관이다. 대통령이 의장, 국무총리가 부의장이다."},{"term":"감사원","desc":"대통령 소속의 독립 기관이다. 국가의 결산과 회계를 검사하고 공무원의 직무를 감찰한다."}]},{"id":"s2-s07-2","title":"국회와 입법","standard":{"text":"국회에서 법률이 만들어지는 사례를 탐색하고, 입법기관으로서 국회의 역할을 조사한다."},"sections":[{"title":"국회는 어떤 기관인가","text":"국회는 국민의 대표로 구성된 입법 기관이다. 우리나라 국회는 하나의 합의체로 이루어진 단원제이다. 국회 의원은 국민의 선거로 뽑히며 임기는 4년이다. 국회 의원에는 지역구에서 뽑힌 의원과 정당 득표율에 따라 배분되는 비례 대표 의원이 있다.\n\n국회의 가장 중요한 역할은 법률을 만드는 것이다. 국민의 대표가 법을 만들어야 그 법이 국민의 뜻을 반영하고 정당성을 가진다. 국회는 헌법 개정안을 의결하고, 중요한 조약의 체결·비준에 동의하는 권한도 가진다.\n\n국회는 주로 위원회 중심으로 운영된다. 교육, 국방, 보건 복지처럼 분야별로 상임 위원회가 있다. 대부분의 안건은 상임 위원회에서 자세히 심사한 뒤 본회의에서 최종 결정한다."},{"title":"법률은 어떻게 만들어질까","text":"법률은 정해진 절차를 거쳐 만들어진다. 먼저 법률안을 제출한다. 국회 의원 10인 이상 또는 정부가 법률안을 낼 수 있다. 국민은 청원을 통해 법 제정을 요청할 수 있다.\n\n제출된 법률안은 소관 상임 위원회에서 심사한다. 이어서 법제 사법 위원회가 다른 법과 충돌하지 않는지, 문구가 바른지 심사한다. 그다음 본회의에서 재적 의원 과반수가 출석하고 출석 의원 과반수가 찬성하면 의결된다.\n\n의결된 법률안은 정부로 보내지고 대통령은 15일 안에 공포한다. 대통령이 이의가 있으면 국회에 다시 의결해 달라고 요구할 수 있다. 이를 법률안 거부권이라고 한다. 이때 국회가 재적 의원 과반수 출석과 출석 의원 3분의 2 이상 찬성으로 다시 의결하면 법률로 확정된다. 법률은 특별한 규정이 없으면 공포 후 20일이 지나 효력이 생긴다."},{"title":"입법 사례와 국회의 다른 역할","text":"법은 사회 문제를 해결하려는 요구에서 출발하는 경우가 많다. 예를 들어 2019년 어린이 보호 구역에서 교통사고로 어린이가 숨진 일이 계기가 되어, 어린이 보호 구역에 과속 단속 장비 설치를 늘리고 사고를 낸 운전자의 처벌을 강화하는 법 개정이 이루어졌다. 처벌 수준이 적절한지를 두고는 찬반 의견이 엇갈리기도 했다. 이처럼 사회적 관심과 국민의 요구가 국회의 입법으로 이어진다. 입법 과정에서는 찬성과 반대 의견을 함께 듣고 조정한다.\n\n국회는 입법 외에도 중요한 역할을 한다. 재정에 관한 권한으로 정부가 낸 예산안을 심의·확정하고 결산을 심사한다. 세금의 종류와 세율은 법률로 정해야 하므로 국회가 결정한다.\n\n국회는 정부와 법원 같은 다른 국가 기관을 견제한다. 국정 감사와 국정 조사로 국정 운영을 점검한다. 국무총리와 대법원장 등의 임명에 동의권을 행사한다. 대통령이나 고위 공직자가 직무를 집행하면서 헌법이나 법률을 위반하면 탄핵 소추를 의결할 수 있다."}],"concepts":[{"term":"입법 기관","desc":"법률을 만드는 국가 기관이다. 우리나라에서는 국민의 대표로 구성된 국회가 입법권을 가진다."},{"term":"상임 위원회","desc":"분야별로 법률안과 예산안 등을 미리 자세히 심사하는 국회의 위원회이다."},{"term":"법률안 거부권","desc":"국회가 의결한 법률안에 이의가 있을 때 대통령이 국회에 다시 의결해 줄 것을 요구하는 권한이다."},{"term":"국정 감사·국정 조사","desc":"국회가 국정 운영 전반이나 특정 사안을 점검·조사하는 제도이다. 행정부를 견제하는 수단이다."},{"term":"탄핵 소추","desc":"대통령이나 고위 공직자가 직무 집행에서 헌법이나 법률을 위반했을 때 국회가 파면을 요구하는 절차이다. 최종 결정은 헌법재판소가 한다."}]},{"id":"s2-s07-3","title":"법원과 헌법재판소","standard":{"text":"사법기관으로서 법원의 역할을 검토하고, 헌법재판소의 성격에 대해 토의한다."},"sections":[{"title":"사법 기관으로서 법원의 역할","text":"법원은 재판을 통해 법을 적용하고 분쟁을 해결하는 사법 기관이다. 헌법은 사법권이 법관으로 구성된 법원에 속한다고 정한다. 법관은 헌법과 법률에 의하여 그 양심에 따라 독립하여 심판한다.\n\n법원의 가장 큰 역할은 국민의 권리를 보호하는 것이다. 억울한 일을 당한 사람은 재판으로 권리를 되찾는다. 법원은 범죄자를 처벌해 사회 질서를 유지한다. 또한 행정 기관의 위법한 처분을 바로잡아 국가 권력을 견제한다.\n\n법원은 명령·규칙·처분이 헌법이나 법률에 위반되는지 심사할 수 있다. 대법원이 이를 최종적으로 판단한다. 법률이 헌법에 위반되는지가 재판의 전제가 되면, 법원은 헌법재판소에 위헌 법률 심판을 제청한다."},{"title":"법원의 조직과 심급","text":"우리나라 법원은 대법원을 최고 법원으로 하는 여러 단계로 구성된다. 대법원은 주로 상고 사건을 다루며 법령 해석의 통일을 이끈다. 고등 법원은 주로 지방 법원 합의부의 1심 판결에 대한 항소 사건을 다룬다. 지방 법원은 대부분의 1심 사건을 다룬다. 지방 법원 단독 판사가 맡은 1심 판결에 대한 항소는 주로 지방 법원 본원 합의부(항소부)가 다룬다. 구체적인 관할은 사건의 종류와 규모에 따라 법률로 정해진다.\n\n특수한 사건을 다루는 법원도 있다. 가정 법원은 이혼, 상속, 소년 보호 사건 등을 다룬다. 행정 법원은 행정 사건을, 특허 법원은 특허 관련 사건을 다룬다. 회생 법원은 회생·파산 사건을 다룬다.\n\n이처럼 법원을 여러 단계로 나눈 것은 심급 제도를 운영하기 위해서이다. 하급 법원의 판결에 불복하면 상급 법원에서 다시 재판받을 수 있다. 이를 통해 잘못된 판결을 바로잡고 재판의 공정성을 높인다."},{"title":"헌법재판소의 성격","text":"헌법재판소는 헌법에 관한 분쟁을 심판하는 기관이다. 재판관 9명으로 구성되며 모두 대통령이 임명한다. 이 가운데 3명은 국회가 선출하고, 3명은 대법원장이 지명한다. 세 기관이 함께 구성에 참여해 어느 한쪽에 치우치지 않게 한다.\n\n헌법재판소는 다섯 가지 심판을 한다. 위헌 법률 심판, 탄핵 심판, 위헌 정당 해산 심판, 국가 기관이나 지방 자치 단체 사이의 권한 쟁의 심판, 헌법 소원 심판이다. 법률의 위헌 결정, 탄핵 결정, 정당 해산 결정, 헌법 소원 인용 결정에는 재판관 6명 이상의 찬성이 필요하다.\n\n헌법재판소는 헌법을 지키는 헌법 수호 기관이자 국민의 기본권을 보장하는 기관이다. 동시에 국회가 만든 법률이나 국가 기관의 결정을 판단하므로 정치적 영향이 큰 사법 기관이기도 하다. 그래서 헌법재판소의 판단이 민주적 정당성을 어떻게 갖출지에 대해 다양한 의견이 있다."}],"concepts":[{"term":"사법권의 독립","desc":"법관이 다른 국가 기관이나 외부의 간섭 없이 헌법과 법률, 양심에 따라 재판하도록 보장하는 원칙이다."},{"term":"명령·규칙·처분 심사권","desc":"행정 입법이나 처분이 헌법·법률에 위반되는지 법원이 심사하는 권한이다. 대법원이 최종 판단한다."},{"term":"위헌 법률 심판","desc":"법률이 헌법에 위반되는지를 헌법재판소가 판단하는 심판이다. 법원의 제청으로 시작된다."},{"term":"권한 쟁의 심판","desc":"국가 기관이나 지방 자치 단체 사이에 권한의 범위를 두고 다툼이 생겼을 때 헌법재판소가 판단하는 심판이다."},{"term":"헌법 수호 기관","desc":"헌법이 최고법으로 지켜지도록 감시하고 판단하는 기관이다. 헌법재판소의 핵심 성격이다."}]}]},"s2-s08":{"title":"경제생활과 선택","lessons":[{"id":"s2-s08-1","title":"합리적 선택","standard":{"text":"경제생활에서 합리적 선택의 필요성에 대해 검토하고, 비용과 편익을 고려한 합리적 선택 방안을 탐색한다."},"sections":[{"title":"희소성과 선택","text":"경제생활에서 선택이 필요한 이유는 자원의 희소성 때문이다. 희소성은 사람의 욕구에 비해 그것을 채워 줄 자원이 부족한 상태를 말한다. 돈, 시간, 물건, 노동력은 모두 한정되어 있다.\n\n희소성은 자원의 절대적인 양이 아니라 욕구와 비교한 상대적인 양으로 판단한다. 아무리 많아도 원하는 사람이 더 많으면 희소하다. 반대로 양이 적어도 원하는 사람이 없으면 희소하지 않다.\n\n자원이 희소하므로 우리는 무엇을 얼마나 쓸지 선택해야 한다. 용돈으로 간식을 살지 책을 살지, 주말에 공부를 할지 운동을 할지 고르는 것이 모두 경제적 선택이다. 기업과 정부도 한정된 자원으로 무엇을 생산하고 어디에 쓸지 선택한다."},{"title":"비용과 편익을 따지는 합리적 선택","text":"합리적 선택은 비용보다 편익이 큰 대안, 또는 같은 비용으로 가장 큰 편익을 얻는 대안을 고르는 것이다. 편익은 선택으로 얻는 만족이나 이익이다.\n\n경제학에서 비용은 기회비용으로 생각한다. 기회비용은 어떤 것을 선택해서 포기한 대안 가운데 가치가 가장 큰 것이다. 기회비용에는 실제로 지불한 돈뿐 아니라 포기한 시간이나 다른 기회의 가치도 포함된다. 예를 들어 아르바이트 대신 학원에 가면 학원비와 함께 아르바이트로 벌 수 있었던 돈도 기회비용이다.\n\n이미 지불해서 되돌릴 수 없는 비용은 매몰 비용이다. 매몰 비용은 어떤 선택을 해도 돌려받지 못하므로 앞으로의 선택에서 고려하지 않아야 한다. 합리적 선택은 문제 인식, 대안 탐색, 평가 기준 설정, 대안 평가, 선택과 평가의 순서로 이루어진다."},{"title":"생활 속 합리적 선택과 그 한계","text":"합리적 선택은 일상의 많은 결정에 쓰인다. 스마트폰을 고를 때 가격, 성능, 사용 기간을 기준으로 대안을 비교할 수 있다. 각 기준에 점수를 매기면 더 체계적으로 판단할 수 있다.\n\n그러나 합리적 선택에는 주의할 점이 있다. 나에게 이익이 되는 선택이 다른 사람이나 사회에 피해를 줄 수 있다. 일회용품을 많이 쓰는 것은 개인에게 편리하지만 환경 오염이라는 사회적 비용을 낳는다. 따라서 개인의 편익뿐 아니라 공동체에 미치는 영향도 함께 고려해야 한다.\n\n또한 사람은 정보가 부족하거나 감정에 휩쓸려 비합리적인 선택을 하기도 한다. 할인 문구에 끌려 필요 없는 물건을 사는 것이 그 예이다. 충분한 정보를 모으고 기준을 미리 정하면 더 나은 선택을 할 수 있다."}],"concepts":[{"term":"희소성","desc":"사람의 욕구에 비해 자원이 상대적으로 부족한 상태이다. 선택이 필요한 근본 원인이다."},{"term":"기회비용","desc":"어떤 것을 선택하면서 포기한 대안 가운데 가치가 가장 큰 것이다. 지불한 돈과 포기한 기회의 가치를 모두 포함한다."},{"term":"편익","desc":"어떤 선택을 통해 얻는 만족이나 이익이다."},{"term":"매몰 비용","desc":"이미 지불해서 어떤 선택을 해도 돌려받을 수 없는 비용이다. 합리적 선택에서는 고려하지 않는다."},{"term":"합리적 선택","desc":"기회비용보다 편익이 큰 대안, 또는 같은 비용으로 편익이 가장 큰 대안을 고르는 선택이다."}]},{"id":"s2-s08-2","title":"자산과 신용 관리","standard":{"text":"일생 동안 이루어지는 경제생활을 분석하고, 안정적인 금융 생활을 위한 자산 및 신용 관리 방안을 계획한다."},"sections":[{"title":"생애 주기와 경제생활","text":"사람의 경제생활은 생애 주기에 따라 달라진다. 생애 주기는 사람이 태어나서 죽을 때까지 거치는 단계이다. 유소년기, 청년기, 중장년기, 노년기로 나눌 수 있다.\n\n유소년기에는 소득이 거의 없고 부모의 도움으로 소비한다. 청년기에는 취업으로 소득이 생기고 결혼, 주거 마련 같은 큰 지출을 준비한다. 중장년기에는 소득이 가장 많지만 자녀 교육비, 주택 비용 등 지출도 많다. 노년기에는 은퇴로 소득이 크게 줄어든다. 반면 의료비 같은 소비는 계속된다.\n\n이처럼 소득이 생기는 시기와 소비가 필요한 시기는 일치하지 않는다. 그래서 소득이 많은 시기에 저축하고 자산을 관리해야 한다. 그래야 소득이 적은 시기에도 안정적으로 생활할 수 있다."},{"title":"자산 관리의 원칙","text":"자산 관리는 미래를 대비해 소득과 재산을 계획적으로 운용하는 활동이다. 자산 관리에서는 세 가지 기준을 살펴본다. 안전성은 원금을 잃지 않을 가능성이다. 수익성은 이자나 가격 상승으로 얻는 이익의 크기이다. 유동성은 필요할 때 쉽게 현금으로 바꿀 수 있는 정도이다.\n\n금융 상품마다 이 특성이 다르다. 예금과 적금은 안전성이 높지만 수익성은 비교적 낮다. 주식은 높은 수익을 기대할 수 있지만 가격 변동이 커서 안전성이 낮다. 채권은 대체로 예금보다 수익성이 높고 주식보다 안전성이 높다. 부동산은 거래에 시간이 걸려 유동성이 낮다.\n\n안전성과 수익성을 모두 높게 가진 상품은 찾기 어렵다. 그래서 자신의 목적과 기간, 감당할 수 있는 위험을 따져 여러 상품에 나누어 투자하는 분산 투자가 필요하다. 어떤 상품도 손실 가능성이 전혀 없다고 단정할 수 없으므로 상품의 특징을 충분히 알아본 뒤 스스로 판단해야 한다. 또한 이자에 이자가 붙는 복리의 효과를 누리려면 일찍부터 꾸준히 저축하는 것이 좋다."},{"title":"신용 관리","text":"신용은 미래에 갚을 것을 약속하고 현재 돈을 빌리거나 물건을 살 수 있는 능력이다. 신용 카드로 물건을 사거나 대출을 받는 것은 신용을 이용하는 것이다. 신용을 잘 이용하면 필요한 시기에 돈을 마련할 수 있다.\n\n그러나 신용은 결국 갚아야 할 빚이다. 갚을 능력을 넘어 신용을 쓰면 빚이 늘어난다. 정해진 날짜에 갚지 못하는 연체가 생기면 신용 점수가 낮아진다. 신용 점수가 낮으면 대출을 받기 어렵거나 더 높은 이자를 내야 한다.\n\n신용을 잘 관리하려면 소득 범위 안에서 계획적으로 소비해야 한다. 빌린 돈은 약속한 날짜에 갚고, 작은 금액이라도 연체하지 않는다. 고금리 대출이나 출처가 불분명한 대출 광고는 피한다. 용돈 기입장이나 가계부를 쓰는 습관도 신용 관리의 첫걸음이다."}],"concepts":[{"term":"생애 주기","desc":"사람이 태어나서 죽을 때까지 거치는 단계이다. 단계마다 소득과 소비의 크기가 다르다."},{"term":"자산 관리의 3원칙","desc":"안전성, 수익성, 유동성이다. 원금 보전, 이익의 크기, 현금화의 쉬움을 뜻한다."},{"term":"분산 투자","desc":"위험을 줄이기 위해 특성이 다른 여러 자산에 나누어 투자하는 방법이다."},{"term":"복리","desc":"원금뿐 아니라 이전에 받은 이자에도 이자가 붙는 방식이다. 기간이 길수록 효과가 커진다."},{"term":"신용","desc":"미래에 갚을 것을 약속하고 현재 돈을 빌리거나 물건을 살 수 있는 능력이다. 연체하면 신용 점수가 낮아진다."}]},{"id":"s2-s08-3","title":"기업의 역할과 책임","standard":{"text":"시장경제에서 기업의 역할과 사회적 책임을 설명하고, 우리 사회에 필요한 기업가 정신에 대해 토의한다."},"sections":[{"title":"시장 경제에서 기업의 역할","text":"기업은 이윤을 얻기 위해 재화와 서비스를 생산하는 경제 주체이다. 기업은 노동, 자본, 토지 같은 생산 요소를 결합해 상품을 만든다. 시장 경제에서 기업은 가계와 함께 경제를 움직이는 중심이다.\n\n기업은 여러 역할을 한다. 첫째, 사람들에게 필요한 재화와 서비스를 공급한다. 둘째, 일자리를 만들어 가계에 소득을 제공한다. 셋째, 세금을 내서 국가 재정을 뒷받침한다. 넷째, 새로운 기술과 상품을 개발해 생활을 편리하게 하고 경제 성장을 이끈다.\n\n기업은 다른 기업과 경쟁한다. 경쟁 속에서 더 좋은 품질과 더 낮은 가격의 상품을 만들려고 노력한다. 이 과정에서 소비자는 더 나은 상품을 선택할 수 있다. 이처럼 기업의 이윤 추구는 공정한 경쟁 안에서 사회 전체에 이익이 될 수 있다."},{"title":"기업의 사회적 책임","text":"기업의 사회적 책임은 기업이 이윤 추구를 넘어 사회 구성원으로서 다해야 할 책임이다. 기업이 커질수록 사회에 미치는 영향도 커졌다. 그래서 기업이 이윤만 추구하면 환경 오염, 불공정 거래, 근로자 권리 침해 같은 문제가 생길 수 있다.\n\n기업의 사회적 책임에는 여러 단계가 있다. 가장 기본은 법을 지키는 것이다. 공정하게 경쟁하고, 근로자의 권리를 보장하며, 세금을 성실히 내야 한다. 소비자에게 안전한 상품과 정확한 정보를 제공해야 한다. 나아가 환경을 보호하고, 지역 사회에 기여하는 활동도 한다.\n\n최근에는 환경, 사회, 지배 구조를 함께 고려하는 ESG 경영이 강조된다. 다만 기업의 책임이 어디까지인지에 대해서는 의견이 다양하다. 이윤을 잘 내고 법을 지키는 것이 핵심 책임이라는 견해와 사회 문제 해결에 더 적극적으로 나서야 한다는 견해가 있다."},{"title":"우리 사회에 필요한 기업가 정신","text":"기업가 정신은 위험을 무릅쓰고 새로운 기회를 찾아 도전하고 혁신하는 자세이다. 경제학자 슘페터는 혁신을 경제 발전의 원동력으로 보았다. 그는 새로운 상품, 새로운 생산 방법, 새로운 시장을 개척하는 기업가의 혁신을 강조했다.\n\n기업가 정신은 경제를 성장시킨다. 새로운 기술과 서비스는 생활을 편리하게 하고 새로운 일자리를 만든다. 오늘날 많은 신생 기업이 정보 통신 기술을 이용해 새로운 시장을 열고 있다.\n\n오늘날에는 사회 문제를 해결하려는 기업가 정신도 주목받는다. 사회적 기업은 취약 계층에게 일자리를 제공하거나 사회 서비스를 공급하는 등 사회적 목적을 추구하면서 영업 활동을 한다. 우리 사회에 필요한 기업가 정신은 혁신과 도전에 더해 윤리 의식과 공동체에 대한 책임을 함께 갖춘 자세이다."}],"concepts":[{"term":"기업","desc":"이윤을 얻기 위해 생산 요소를 결합해 재화와 서비스를 생산하는 경제 주체이다."},{"term":"기업의 사회적 책임","desc":"기업이 이윤 추구를 넘어 법 준수, 소비자·근로자 보호, 환경 보호, 지역 사회 기여 등 사회 구성원으로서 다해야 할 책임이다."},{"term":"ESG 경영","desc":"환경(Environmental), 사회(Social), 지배 구조(Governance)를 함께 고려하는 경영 방식이다."},{"term":"기업가 정신","desc":"위험을 무릅쓰고 새로운 기회를 찾아 도전하고 혁신하려는 자세이다."},{"term":"사회적 기업","desc":"취약 계층 일자리 제공이나 사회 서비스 공급 같은 사회적 목적을 추구하면서 영업 활동을 하는 기업이다."}]}]},"s2-s09":{"title":"시장과 가격","lessons":[{"id":"s2-s09-1","title":"시장의 의미와 필요성","standard":{"text":"일상생활에서 접하는 다양한 시장의 사례를 조사하고, 이를 토대로 시장의 의미와 필요성을 설명한다."},"sections":[{"title":"시장이란 무엇인가","text":"시장은 상품을 사려는 사람과 팔려는 사람이 만나 거래가 이루어지는 곳이다. 여기서 '곳'은 꼭 눈에 보이는 장소만 뜻하지 않는다. 거래가 이루어지는 관계와 방식 전체가 시장이다.\n\n전통 시장, 대형 마트, 편의점처럼 눈에 보이는 시장이 있다. 온라인 쇼핑몰, 중고 거래 앱, 주식 시장, 외환 시장처럼 눈에 보이지 않는 시장도 있다. 보이지 않는 시장에서는 사람들이 직접 만나지 않아도 통신망을 통해 거래한다.\n\n거래하는 대상에 따라 나눌 수도 있다. 옷, 음식, 영화 관람 같은 재화와 서비스가 거래되는 곳은 생산물 시장이다. 노동, 토지, 자본처럼 생산에 필요한 요소가 거래되는 곳은 생산 요소 시장이다. 아르바이트 구인·구직이 이루어지는 노동 시장이 대표적이다."},{"title":"시장은 왜 생겨났을까","text":"시장은 분업과 교환이 늘어나면서 생겨났다. 옛날 사람들은 필요한 것을 대부분 스스로 만들어 쓰는 자급자족 생활을 했다. 그러다 각자 잘하는 일에 집중하는 특화와 분업이 나타났다.\n\n특화를 하면 같은 시간에 더 많이 생산할 수 있다. 대신 자신이 만들지 않은 물건은 다른 사람과 바꿔야 한다. 처음에는 물건과 물건을 직접 바꾸는 물물 교환을 했다. 그러나 물물 교환은 서로 원하는 물건이 맞아야만 이루어져 불편했다.\n\n화폐가 등장하면서 이 불편이 크게 줄었다. 화폐로 물건 값을 매기고 주고받을 수 있게 되자 거래가 쉬워졌다. 거래가 늘어나자 사람들이 정해진 때와 곳에 모이는 시장이 발달했다."},{"title":"시장이 하는 일과 우리 생활","text":"시장은 거래 비용을 줄여 준다. 거래 비용은 거래 상대를 찾고 정보를 모으는 데 드는 시간과 노력이다. 시장에 가면 여러 판매자를 한곳에서 만날 수 있고, 온라인 시장에서는 가격을 쉽게 비교할 수 있다.\n\n시장은 특화와 분업을 더 활발하게 만든다. 만든 물건을 시장에서 팔 수 있다는 믿음이 있어야 사람들이 한 가지 일에 집중할 수 있다. 그 결과 사회 전체의 생산량이 늘어난다.\n\n시장은 가격이라는 정보도 알려 준다. 어떤 상품의 가격이 오르면 사람들은 그 상품이 귀해졌다는 신호로 받아들인다. 우리가 편의점에서 간식을 사거나 중고 거래 앱에서 물건을 파는 일도 모두 시장 활동이다. 다음 학습에서는 시장에서 가격이 어떻게 정해지는지 알아본다."}],"concepts":[{"term":"시장","desc":"상품을 사려는 사람과 팔려는 사람이 만나 거래가 이루어지는 곳이다. 눈에 보이는 장소가 아니어도 된다."},{"term":"생산물 시장","desc":"재화와 서비스 같은 생산물이 거래되는 시장이다. 가계는 주로 소비자로, 기업은 주로 공급자로 참여한다."},{"term":"생산 요소 시장","desc":"노동, 토지, 자본 같은 생산 요소가 거래되는 시장이다. 노동 시장이 대표적인 예이다."},{"term":"특화와 분업","desc":"특화는 자신이 잘하는 일에 집중하는 것이고, 분업은 일을 나누어 맡는 것이다. 둘 다 생산성을 높인다."},{"term":"거래 비용","desc":"거래 상대를 찾고 정보를 모으고 협상하는 데 드는 시간과 노력이다. 시장은 거래 비용을 줄여 준다."}]},{"id":"s2-s09-2","title":"수요·공급과 가격 결정","standard":{"text":"수요 법칙과 공급 법칙을 사례를 통해 도출하고, 이를 토대로 시장 가격이 결정되는 원리를 설명한다."},"sections":[{"title":"수요와 수요 법칙","text":"수요는 어떤 상품을 일정한 가격에 사려는 욕구이다. 단순히 갖고 싶은 마음이 아니라 실제로 살 수 있는 능력이 함께 있어야 한다. 수요량은 특정한 가격에서 사려고 하는 상품의 양이다.\n\n다른 조건이 같을 때 가격이 오르면 수요량이 줄고, 가격이 내리면 수요량이 늘어난다. 이를 수요 법칙이라고 한다. 가격이 오르면 같은 돈으로 살 수 있는 양이 줄고, 사람들이 더 싼 다른 상품으로 바꾸기 때문이다.\n\n가격과 수요량의 관계를 그래프로 나타낸 것이 수요 곡선이다. 세로축을 가격, 가로축을 수량으로 놓으면 수요 곡선은 오른쪽 아래로 내려가는 모양이 된다."},{"title":"공급과 공급 법칙","text":"공급은 어떤 상품을 일정한 가격에 팔려는 욕구이다. 공급량은 특정한 가격에서 팔려고 하는 상품의 양이다. 공급자는 주로 상품을 만들어 파는 기업이나 가게이다.\n\n다른 조건이 같을 때 가격이 오르면 공급량이 늘고, 가격이 내리면 공급량이 줄어든다. 이를 공급 법칙이라고 한다. 가격이 오르면 같은 양을 팔아도 이윤이 커지므로 공급자는 생산을 늘린다. 새로운 공급자가 시장에 들어오기도 한다.\n\n가격과 공급량의 관계를 그래프로 나타낸 것이 공급 곡선이다. 공급 곡선은 오른쪽 위로 올라가는 모양이다. 수요 곡선과 반대 방향이라는 점을 기억해 두자."},{"title":"시장 가격은 어떻게 정해질까","text":"시장 가격은 수요와 공급이 만나는 곳에서 정해진다. 수요 곡선과 공급 곡선이 만나는 점에서 수요량과 공급량이 같아진다. 이때의 가격이 균형 가격이고, 이때 거래되는 양이 균형 거래량이다.\n\n가격이 균형 가격보다 높으면 공급량이 수요량보다 많아 초과 공급이 생긴다. 팔리지 않은 상품이 남으므로 판매자는 가격을 내린다. 가격이 균형 가격보다 낮으면 수요량이 공급량보다 많아 초과 수요가 생긴다. 물건이 모자라므로 가격이 오른다. 이렇게 가격은 균형 가격 쪽으로 움직인다.\n\n랩에서 가격선을 위아래로 끌어 보면 초과 공급과 초과 수요가 생기는 모습을 직접 확인할 수 있다. 시장 가격은 무엇을 얼마나 만들고 살지 알려 주는 신호등 역할을 한다."}],"concepts":[{"term":"수요 법칙","desc":"다른 조건이 같을 때 가격이 오르면 수요량이 줄고, 가격이 내리면 수요량이 늘어난다."},{"term":"공급 법칙","desc":"다른 조건이 같을 때 가격이 오르면 공급량이 늘고, 가격이 내리면 공급량이 줄어든다."},{"term":"균형 가격","desc":"수요량과 공급량이 같아지는 가격. 시장은 이 가격으로 움직인다."},{"term":"초과 수요·초과 공급","desc":"가격이 균형보다 낮으면 초과 수요가 생겨 가격이 오르고, 높으면 초과 공급이 생겨 가격이 내린다."}]},{"id":"s2-s09-3","title":"가격 변동과 대응","standard":{"text":"시장경제에서 수요와 공급을 변화시키는 요인을 조사하고, 시장 가격의 변동에 대응하는 방안을 계획한다."},"sections":[{"title":"수요를 바꾸는 요인","text":"상품의 가격이 아닌 다른 요인이 바뀌면 수요 자체가 변한다. 이를 수요의 변동이라고 하며, 수요 곡선 전체가 오른쪽(증가)이나 왼쪽(감소)으로 이동한다. 상품 자체의 가격이 변해 곡선 위에서 움직이는 수요량의 변동과 구별해야 한다.\n\n수요를 바꾸는 요인에는 소득, 선호, 관련 상품의 가격, 인구, 미래 가격 예상이 있다. 소득이 늘거나 유행으로 선호가 커지면 수요가 증가한다. 대체재는 서로 대신 쓸 수 있는 상품이고, 보완재는 함께 쓰는 상품이다. 대체재의 가격이 오르면 수요가 늘고, 보완재의 가격이 오르면 수요가 준다.\n\n예를 들어 돼지고기 가격이 오르면 대체재인 닭고기의 수요가 늘어난다. 앞으로 가격이 오를 것이라고 예상해도 지금의 수요가 늘어난다."},{"title":"공급을 바꾸는 요인과 가격 변화","text":"가격 이외의 요인이 바뀌면 공급도 변한다. 원자재 가격이나 임금 같은 생산 비용, 생산 기술, 공급자 수, 날씨 등이 공급을 바꾸는 요인이다. 생산 비용이 내리거나 기술이 발달하면 공급이 증가해 공급 곡선이 오른쪽으로 이동한다. 태풍으로 농작물 생산이 줄면 공급이 감소해 공급 곡선이 왼쪽으로 이동한다.\n\n수요와 공급이 변하면 균형 가격과 균형 거래량도 바뀐다. 수요가 증가하면 가격이 오르고 거래량이 늘어난다. 수요가 감소하면 가격이 내리고 거래량이 줄어든다. 공급이 증가하면 가격은 내리고 거래량은 늘어난다. 공급이 감소하면 가격은 오르고 거래량은 줄어든다.\n\n랩에서 사건 버튼을 눌러 곡선이 어느 쪽으로 움직이는지 확인해 보자."},{"title":"가격 변동에 어떻게 대응할까","text":"가격이 크게 변하면 소비자, 생산자, 정부가 각자 대응한다. 소비자는 가격이 오른 상품 대신 대체재를 고르거나, 여러 판매처의 가격을 비교해 계획적으로 소비할 수 있다.\n\n생산자는 가격 변화에 맞춰 생산량을 조절한다. 저장 시설을 활용하거나 새로운 기술로 생산 비용을 줄이기도 한다. 농산물처럼 날씨에 따라 공급이 크게 흔들리는 상품은 계약 재배로 미리 거래 조건을 정해 두기도 한다.\n\n정부는 생활필수품 가격이 지나치게 오르면 미리 비축해 둔 물량을 시장에 내놓거나 수입을 늘려 공급을 늘린다. 다만 정부가 가격을 직접 낮게 묶으면 초과 수요가 생겨 물건이 부족해지는 부작용이 생길 수 있다. 그래서 가격 원리를 이해하고 대응 방안을 함께 비교해야 한다."}],"concepts":[{"term":"수요 변동 요인","desc":"소득, 선호, 대체재·보완재 가격, 인구, 미래 가격 예상이 바뀌면 수요 곡선 전체가 이동한다."},{"term":"공급 변동 요인","desc":"생산 비용, 기술, 공급자 수, 날씨 등이 바뀌면 공급 곡선 전체가 이동한다."},{"term":"수요량의 변동과 수요의 변동","desc":"상품 자체의 가격이 변해 곡선 위에서 움직이는 것은 수요량의 변동이다. 가격 이외의 요인이 변해 곡선 전체가 이동하는 것은 수요의 변동이다."},{"term":"대체재와 보완재","desc":"대체재는 서로 대신 쓸 수 있는 상품(돼지고기와 닭고기)이고, 보완재는 함께 쓰는 상품(프린터와 잉크)이다."}]}]},"s2-s10":{"title":"우리나라 경제와 세계화","lessons":[{"id":"s2-s10-1","title":"국민 경제와 경제 성장","standard":{"text":null},"sections":[{"title":"국민 경제와 국내 총생산","text":"국민 경제는 한 나라 안에서 가계, 기업, 정부가 생산, 분배, 소비 활동으로 서로 연결된 경제 전체이다. 국민 경제의 규모와 상태를 알려면 한 나라가 얼마나 생산했는지를 재야 한다. 이때 쓰는 대표 지표가 국내 총생산(GDP)이다.\n\n국내 총생산은 일정 기간 동안 한 나라 안에서 새롭게 생산된 최종 생산물의 시장 가치를 모두 더한 것이다. '한 나라 안에서'는 국적과 상관없이 그 나라 영토 안의 생산을 모두 포함한다는 뜻이다. 외국 기업이 우리나라에서 생산한 것은 우리나라 GDP에 들어간다.\n\n'최종 생산물'만 더하는 이유는 이중 계산을 막기 위해서이다. 빵을 만드는 데 쓰인 밀가루 같은 중간재의 가치는 이미 빵 가격에 들어 있다. '새롭게 생산된'이라는 조건 때문에 중고품 거래액도 포함되지 않는다."},{"title":"GDP로 알 수 있는 것과 없는 것","text":"GDP로는 한 나라 경제의 전체 규모를 알 수 있다. GDP를 인구수로 나눈 1인당 GDP는 국민 한 사람이 평균적으로 얼마나 생산했는지 보여 주므로 나라 사이의 생활 수준을 대략 비교할 때 쓰인다.\n\n그러나 GDP에는 한계가 있다. 시장에서 거래되지 않는 가사 노동이나 자원봉사 활동은 포함되지 않는다. 생산 과정에서 생기는 환경 오염이나 줄어든 여가 시간도 반영하지 못한다. 또 GDP가 같아도 소득이 고르게 나뉘었는지는 알 수 없다.\n\n그래서 GDP가 늘었다고 국민의 삶의 질이 반드시 높아졌다고 단정할 수는 없다. 경제의 크기를 보는 중요한 지표이지만, 다른 지표와 함께 살펴보아야 한다."},{"title":"경제 성장과 그 영향","text":"경제 성장은 한 나라의 생산 능력이 커져 실질 GDP가 늘어나는 것이다. 실질 GDP는 물가 변동의 효과를 빼고 계산한 GDP이다. 물가만 올라도 GDP 금액은 커지므로, 실제로 생산이 늘었는지 보려면 실질 GDP를 비교한다. 실질 GDP가 1년 동안 몇 퍼센트 늘었는지를 나타낸 것이 경제 성장률이다.\n\n경제가 성장하려면 노동과 자본 같은 생산 요소가 늘거나, 기술 발전으로 생산성이 높아져야 한다. 교육으로 사람들의 능력을 키우고, 기업이 투자하기 좋은 제도를 갖추는 것도 중요하다.\n\n우리나라는 1960년대 이후 수출 중심의 공업화로 빠르게 성장하였다. 경제 성장으로 일자리와 소득이 늘고 생활 수준이 높아졌다. 반면 환경 오염, 소득 격차 같은 문제도 함께 나타났다. 따라서 성장과 함께 그 혜택이 고르게 나뉘고 환경이 지켜지는지도 살펴야 한다."}],"concepts":[{"term":"국민 경제","desc":"한 나라 안에서 가계, 기업, 정부가 생산, 분배, 소비 활동으로 연결된 경제 전체이다."},{"term":"국내 총생산(GDP)","desc":"일정 기간 동안 한 나라 안에서 새롭게 생산된 최종 생산물의 시장 가치를 모두 더한 것이다."},{"term":"1인당 GDP","desc":"GDP를 그 나라의 인구수로 나눈 값이다. 나라 사이의 평균적인 생활 수준을 대략 비교할 때 쓴다."},{"term":"실질 GDP","desc":"물가 변동의 효과를 빼고 계산한 GDP이다. 실제 생산량이 늘었는지 확인할 때 쓴다."},{"term":"경제 성장률","desc":"실질 GDP가 전년도에 비해 몇 퍼센트 늘었는지를 나타낸 값이다."}]},{"id":"s2-s10-2","title":"물가와 실업","standard":{"text":null},"sections":[{"title":"물가와 인플레이션","text":"물가는 여러 상품의 가격을 종합해 평균한 수준이다. 떡볶이 값 하나가 올랐다고 물가가 올랐다고 하지는 않는다. 물가가 얼마나 변했는지 알기 위해 물가 지수를 쓴다. 물가 지수는 기준 연도의 물가를 100으로 놓고 다른 시기의 물가를 비교한 수치이다.\n\n우리나라는 통계청이 가계가 자주 사는 상품과 서비스의 가격을 조사해 소비자 물가 지수를 발표한다. 소비자 물가 지수가 105라면 기준 연도보다 물가가 5% 올랐다는 뜻이다.\n\n물가가 지속적으로 오르는 현상을 인플레이션이라고 한다. 인플레이션이 일어나면 같은 돈으로 살 수 있는 양이 줄어든다. 즉 화폐의 가치가 떨어진다."},{"title":"인플레이션의 원인과 영향","text":"인플레이션은 크게 두 가지 이유로 일어난다. 첫째, 경제 전체에서 상품을 사려는 수요가 생산보다 빠르게 늘 때이다. 시중에 돈이 많이 풀리거나 정부 지출이 크게 늘면 이런 일이 생길 수 있다. 둘째, 원자재 가격이나 임금 같은 생산 비용이 오를 때이다. 기업이 늘어난 비용을 상품 가격에 반영하기 때문이다.\n\n인플레이션은 사람마다 다른 영향을 준다. 월급처럼 소득이 정해진 사람, 현금이나 예금을 가진 사람, 돈을 빌려준 사람은 불리해진다. 반대로 집이나 땅 같은 실물 자산을 가진 사람, 돈을 빌린 사람은 상대적으로 유리해진다. 국내 상품 가격이 오르면 수출이 불리해지고 수입이 늘어날 수 있다.\n\n그래서 정부는 지출을 조절하고, 한국은행은 기준 금리를 올려 물가 안정을 꾀한다. 기준 금리가 오르면 은행의 대출·예금 금리도 따라 오르는 경향이 있어, 돈을 빌리는 사람은 줄고 저축하는 사람은 늘어난다. 그 결과 시중에 도는 돈이 줄고 소비와 투자가 줄어 물가 상승이 누그러진다. 기업의 생산성 향상과 소비자의 계획적인 소비도 도움이 된다."},{"title":"실업과 그 대책","text":"실업은 일할 의사와 능력이 있는데도 일자리를 얻지 못한 상태이다. 실업률은 경제 활동 인구 가운데 실업자가 차지하는 비율이다. 경제 활동 인구는 15세 이상 인구 중 취업자와 실업자를 합한 것이다. 학생, 전업주부처럼 일할 의사가 없거나 일자리를 찾지 않는 사람은 비경제 활동 인구로 분류된다.\n\n실업은 원인에 따라 나뉜다. 경기가 나빠져 생기는 경기적 실업, 산업 구조나 기술이 바뀌어 생기는 구조적 실업, 더 나은 일자리를 찾는 동안 잠시 생기는 마찰적 실업, 계절에 따라 일감이 줄어 생기는 계절적 실업이 있다.\n\n실업은 개인에게 소득을 잃게 하고, 사회 전체로는 생산할 수 있는 능력이 낭비되는 손실이다. 정부는 경기를 활성화하고, 직업 훈련으로 새로운 기술을 익히게 하며, 고용 정보를 제공해 실업을 줄이려 노력한다."}],"concepts":[{"term":"물가 지수","desc":"기준 연도의 물가를 100으로 놓고 다른 시기의 물가 수준을 비교해 나타낸 수치이다."},{"term":"인플레이션","desc":"물가가 지속적으로 오르는 현상이다. 화폐의 가치가 떨어진다."},{"term":"실업","desc":"일할 의사와 능력이 있는데도 일자리를 얻지 못한 상태이다."},{"term":"경제 활동 인구","desc":"15세 이상 인구 중 취업자와 실업자를 합한 것이다. 일할 의사가 없는 학생, 전업주부 등은 비경제 활동 인구이다."},{"term":"실업률","desc":"경제 활동 인구 가운데 실업자가 차지하는 비율이다. (실업자 수 ÷ 경제 활동 인구) × 100으로 구한다."}]},{"id":"s2-s10-3","title":"국제 거래와 환율","standard":{"text":null},"sections":[{"title":"국제 거래는 왜 일어날까","text":"국제 거래는 나라와 나라 사이에 상품, 서비스, 자본, 노동 등을 사고파는 것이다. 나라마다 자원, 기후, 기술, 노동력이 달라서 같은 상품을 만들어도 생산 비용이 다르다. 그래서 각 나라는 상대적으로 더 잘 만드는 상품을 특화해 생산하고 서로 교환한다.\n\n다른 나라보다 상대적으로 적은 비용으로 생산할 수 있는 것을 비교 우위라고 한다. 각 나라가 비교 우위가 있는 상품에 특화해 거래하면 모두 더 많은 상품을 쓸 수 있다.\n\n우리나라는 자원이 부족해 원유 같은 원자재를 수입하고, 반도체, 자동차, 선박 등을 수출한다. 무역이 경제에서 차지하는 비중이 큰 편이다. 세계 무역 기구(WTO)와 자유 무역 협정(FTA)으로 무역 장벽이 낮아지면서 국제 거래는 더욱 늘어났다."},{"title":"환율은 어떻게 정해질까","text":"환율은 우리나라 돈과 외국 돈을 바꾸는 비율이다. 보통 외국 돈 1단위를 얻는 데 필요한 우리 돈의 양으로 나타낸다. 예를 들어 '1달러 = 1,300원'처럼 표시한다.\n\n환율은 외국 돈이 거래되는 외환 시장에서 외화의 수요와 공급에 따라 정해진다. 수입, 우리 국민의 해외여행과 유학, 해외 투자가 늘면 외화를 사려는 수요가 늘어 환율이 오른다. 수출, 외국인 관광객의 국내 여행, 외국인의 국내 투자가 늘면 외화 공급이 늘어 환율이 내린다.\n\n환율이 오르면 원화의 가치는 떨어진다. 1달러를 얻는 데 원화가 더 많이 필요하기 때문이다. 반대로 환율이 내리면 원화의 가치는 오른다."},{"title":"환율 변동이 우리 생활에 미치는 영향","text":"환율이 오르면 수출 기업에 유리하다. 같은 원화 가격의 상품이라도 달러로 표시한 가격이 낮아져 외국에서 잘 팔리기 때문이다. 반대로 수입품의 원화 가격은 오른다. 원유, 곡물 같은 수입 원자재 가격이 오르면 국내 물가도 오를 수 있다.\n\n환율이 오르면 해외여행을 가거나 외국에 있는 자녀에게 학비를 보내는 가정의 부담이 커진다. 외국에서 빌린 돈을 갚아야 하는 기업도 더 많은 원화가 필요해진다. 반대로 외국인 관광객에게는 우리나라 여행 비용이 싸진다.\n\n환율이 내리면 이와 반대 현상이 나타난다. 수입품 가격과 해외여행 비용은 낮아지지만, 수출 기업은 가격 경쟁에서 불리해질 수 있다. 이처럼 환율 변동은 누구에게는 이익이 되고 누구에게는 손해가 된다."}],"concepts":[{"term":"국제 거래","desc":"나라와 나라 사이에 상품, 서비스, 자본, 노동 등을 사고파는 것이다."},{"term":"비교 우위","desc":"다른 나라보다 상대적으로 적은 비용으로 어떤 상품을 생산할 수 있는 것이다. 국제 거래가 일어나는 근거가 된다."},{"term":"환율","desc":"우리나라 돈과 외국 돈의 교환 비율이다. 외국 돈 1단위와 바꾸는 데 필요한 우리 돈의 양으로 나타낸다."},{"term":"외환 시장","desc":"외국 돈이 거래되는 시장이다. 외화의 수요와 공급에 따라 환율이 정해진다."},{"term":"환율 상승(원화 가치 하락)","desc":"외국 돈 1단위를 얻는 데 더 많은 원화가 필요해지는 것이다. 수출에는 유리하고 수입에는 불리하다."}]}]},"s2-s11":{"title":"국제 사회와 한반도","lessons":[{"id":"s2-s11-1","title":"국제 사회의 특성과 행위 주체","standard":{"text":null},"sections":[{"title":"국제 사회의 특성","text":"국제 사회는 주권을 가진 여러 국가가 서로 관계를 맺으며 이루는 사회이다. 각 국가는 자기 나라의 일을 스스로 결정하는 주권을 가지며, 다른 나라의 간섭을 받지 않는다.\n\n국제 사회에는 국가들 위에서 법을 만들고 강제로 집행하는 중앙 정부가 없다. 그래서 각 나라는 기본적으로 자국의 이익을 우선 추구한다. 이 때문에 힘이 센 나라의 영향력이 크게 작용하는 경우도 있다.\n\n그러나 힘의 논리만 통하는 것은 아니다. 국제법, 국제기구, 국제 여론이 나라들의 행동을 일정하게 이끈다. 세계화로 나라 사이의 상호 의존이 깊어지면서, 환경 문제나 감염병처럼 함께 해결해야 할 문제가 늘어나 협력의 중요성도 커지고 있다."},{"title":"국제 사회의 다양한 행위 주체","text":"국제 사회에서 활동하는 주체는 국가만이 아니다. 국가는 가장 기본적인 행위 주체로, 외교를 통해 다른 나라와 관계를 맺고 조약을 체결한다.\n\n국제기구는 크게 두 종류이다. 정부 간 국제기구는 여러 나라 정부가 모여 만든 기구로, 국제 연합(UN), 세계 보건 기구(WHO), 세계 무역 기구(WTO) 등이 있다. 국제 비정부 기구(NGO)는 개인이나 민간단체가 모여 국경을 넘어 활동하는 단체로, 국경 없는 의사회, 그린피스, 국제 앰네스티 등이 있다.\n\n여러 나라에 생산 공장이나 판매 지점을 두고 활동하는 다국적 기업도 중요한 행위 주체이다. 이 밖에 국제 분쟁을 중재하는 전직 국가 원수나 세계적인 영향력을 가진 개인, 다른 나라 도시와 교류하는 지방 자치 단체도 국제 사회에 영향을 준다."},{"title":"행위 주체들이 함께 움직이는 사례","text":"기후 변화 문제를 보면 여러 행위 주체가 함께 움직이는 모습을 알 수 있다. 국가들은 국제 연합의 회의에서 온실가스를 줄이기 위한 협약을 맺는다. 각국 정부는 협약에 따라 감축 목표를 세우고 정책을 만든다.\n\n국제 비정부 기구는 기후 변화의 위험을 알리고 각국이 약속을 지키는지 감시한다. 다국적 기업은 재생 에너지를 쓰거나 탄소 배출을 줄이는 생산 방식을 도입한다. 개인은 에너지를 아끼고 관련 캠페인에 참여한다.\n\n이처럼 오늘날 국제 문제는 한 주체만의 힘으로 해결하기 어렵다. 우리가 쓰는 물건, 보는 뉴스에도 여러 행위 주체의 활동이 담겨 있다. 국제 사회의 구성원으로서 이들의 역할을 이해하는 것이 국제 문제를 바라보는 첫걸음이다."}],"concepts":[{"term":"주권 국가","desc":"자기 나라의 일을 스스로 결정할 권리인 주권을 가진 국가이다. 국제 사회의 가장 기본적인 행위 주체이다."},{"term":"정부 간 국제기구","desc":"여러 나라 정부가 회원으로 모여 만든 국제기구이다. 국제 연합(UN), 세계 보건 기구(WHO) 등이 있다."},{"term":"국제 비정부 기구(NGO)","desc":"개인이나 민간단체가 모여 국경을 넘어 활동하는 단체이다. 국경 없는 의사회, 그린피스 등이 있다."},{"term":"다국적 기업","desc":"여러 나라에 생산 공장이나 판매 지점을 두고 세계적으로 활동하는 기업이다."},{"term":"국제법","desc":"국가 사이의 관계를 규율하는 법이다. 조약과 국제 관습법 등으로 이루어진다."}]},{"id":"s2-s11-2","title":"국제 갈등과 협력","standard":{"text":null},"sections":[{"title":"국제 갈등은 왜 일어날까","text":"국제 갈등은 국가나 집단이 서로의 이익이나 가치가 부딪혀 대립하는 것이다. 국제 사회에는 중앙 정부가 없고 각 나라가 자국의 이익을 우선하기 때문에 갈등이 생기기 쉽다.\n\n갈등의 원인은 다양하다. 영토나 석유, 물 같은 자원을 둘러싼 갈등이 있다. 큰 강 상류에 댐을 지으면 하류 나라의 물 이용이 줄어 갈등이 생기기도 한다. 민족과 종교의 차이, 과거 역사에 대한 서로 다른 인식도 갈등의 원인이 된다.\n\n무역에서 서로 더 많은 이익을 얻으려다 무역 분쟁이 생기기도 한다. 한 나라에서 생긴 대기 오염이 이웃 나라로 넘어가는 환경 문제도 국제 갈등이 될 수 있다. 실제 갈등은 여러 원인이 얽혀 나타나는 경우가 많다."},{"title":"국제 갈등을 해결하는 방법","text":"국제 갈등은 평화적인 방법으로 해결하는 것이 바람직하다. 가장 기본적인 방법은 외교이다. 외교는 대화와 협상으로 서로의 입장을 조정해 합의에 이르는 것이다.\n\n국제기구도 갈등 해결을 돕는다. 국제 연합은 분쟁 지역에 평화 유지 활동을 펼치고 당사국 사이를 중재한다. 국제 사법 재판소는 국가 사이의 법적 분쟁을 국제법에 따라 판단한다. 다만 원칙적으로 분쟁 당사국이 모두 동의해야 재판할 수 있다.\n\n여러 나라가 함께 지킬 규칙을 정하는 국제 협약도 중요하다. 오존층을 파괴하는 물질의 사용을 줄이기로 한 몬트리올 의정서(1987년 채택)는 국제 협력이 성과를 거둔 대표 사례로 꼽힌다. 2015년 채택된 파리 협정은 기후 변화에 대응하기 위해 모든 당사국이 온실가스 감축 목표를 정하도록 하였다."},{"title":"국제 협력과 세계 시민","text":"오늘날 많은 문제는 한 나라의 힘만으로 해결할 수 없다. 기후 변화, 감염병, 난민, 빈곤 문제는 국경을 넘어 영향을 주기 때문이다. 그래서 국가들은 정보를 나누고, 기술과 자금을 지원하며 협력한다.\n\n우리나라도 국제 협력에 참여한다. 국제 연합 평화 유지 활동에 참여하고, 개발 도상국에 공적 개발 원조를 제공한다. 한국은 원조를 받던 나라에서 원조를 주는 나라가 된 경험을 가지고 있다.\n\n개인도 세계 시민으로서 역할을 할 수 있다. 세계 시민은 자기 나라뿐 아니라 인류 전체의 문제에 관심을 갖고 책임감 있게 행동하는 사람이다. 국제 뉴스에 관심을 갖고, 공정 무역 제품을 고르고, 국제 캠페인에 참여하는 것이 그 예이다."}],"concepts":[{"term":"국제 갈등","desc":"국가나 집단의 이익과 가치가 부딪혀 대립하는 것이다. 영토, 자원, 민족, 종교, 역사 인식 등이 원인이 된다."},{"term":"외교","desc":"대화와 협상을 통해 다른 나라와 관계를 맺고 문제를 해결하는 활동이다."},{"term":"국제 사법 재판소(ICJ)","desc":"국가 사이의 법적 분쟁을 국제법에 따라 판단하는 국제 연합의 사법 기관이다. 원칙적으로 분쟁 당사국이 모두 동의해야 재판할 수 있다."},{"term":"국제 협약","desc":"여러 나라가 공동의 문제를 해결하기 위해 함께 지키기로 약속한 규칙이다. 몬트리올 의정서, 파리 협정 등이 있다."},{"term":"세계 시민","desc":"자기 나라를 넘어 인류 공동의 문제에 관심을 갖고 책임감 있게 행동하는 사람이다."}]},{"id":"s2-s11-3","title":"한반도와 국제 관계","standard":{"text":null},"sections":[{"title":"한반도의 위치와 남북 관계","text":"한반도는 유라시아 대륙과 태평양 사이에 있다. 대륙과 해양으로 모두 나아갈 수 있는 위치이지만, 주변 강대국의 이해관계가 맞부딪히는 곳이기도 하다. 그래서 한반도 문제에는 남북한뿐 아니라 미국, 중국, 일본, 러시아 같은 주변국도 관심을 가진다.\n\n한반도는 1945년 광복 이후 남북으로 분단되었다. 1950년에 6·25 전쟁이 일어났고, 1953년 정전 협정이 체결된 뒤 지금까지 휴전 상태가 이어지고 있다.\n\n남북한은 대화와 교류를 통해 평화를 이루려는 노력도 해 왔다. 1991년 남북 기본 합의서를 채택하였고, 2000년 이후 여러 차례 남북 정상 회담이 열렸다. 대한민국 헌법 제4조는 평화적 통일 정책을 수립하고 추진한다고 규정하고 있다. 한반도의 평화는 동아시아와 세계의 평화와도 연결된다."},{"title":"독도는 대한민국의 고유 영토","text":"독도는 역사적·지리적·국제법적으로 명백한 대한민국의 고유 영토이다. 독도는 울릉도에서 약 87.4km 떨어져 있어 맑은 날 맨눈으로 보인다. 『세종실록』 「지리지」(1454년)에는 우산(독도)과 무릉(울릉도) 두 섬이 멀지 않아 날씨가 맑으면 바라볼 수 있다고 기록되어 있다.\n\n1900년 대한제국은 칙령 제41호를 공포해 울릉도를 울도군으로 승격하고 석도(독도)를 관할하게 하였다. 당시 일본 정부의 최고 국가 기관인 태정관도 1877년 \"죽도(당시 일본이 울릉도를 부르던 이름) 외 1도(독도)는 일본과 관계없다\"는 지령을 내렸다. 일본은 1905년 시마네현 고시로 독도를 편입했다고 주장하지만, 이는 러일 전쟁 중 한국의 주권을 침탈하는 과정에서 이루어진 불법적인 조치이다.\n\n1946년 연합국 최고 사령관 각서(SCAPIN) 제677호는 독도를 일본의 통치 범위에서 제외하였다. 현재 대한민국은 독도에 경비대를 두고 주민이 거주하는 등 실효적으로 지배하고 있다. 정부는 독도에 영토 분쟁은 존재하지 않는다는 입장이다."},{"title":"동해 표기와 주변국과의 역사 갈등","text":"동해는 우리 민족이 오랫동안 써 온 이름이다. 고려 시대에 편찬된 『삼국사기』에는 고구려 건국 무렵의 일을 기록한 부분에 '동해'라는 이름이 나온다. 그러나 세계 여러 지도에는 일본식 명칭만 단독으로 쓰인 경우가 많다. 우리 정부와 민간은 국제 사회에 '동해' 표기, 또는 적어도 동해 병기를 알리는 노력을 이어 가고 있다.\n\n주변국과의 역사 갈등도 있다. 일본의 일부 역사 교과서는 일제 강점기의 침략과 강제 동원, 일본군'위안부' 피해 사실을 축소하거나 빠뜨려 서술했다는 비판을 받는다. 또 일본의 여러 교과서에는 독도가 일본 영토라는 주장이 실려 있으며, 우리 정부는 이에 항의하고 시정을 요구해 왔다. 중국의 동북 공정은 고구려와 발해의 역사를 중국 역사의 일부로 편입하려는 연구 사업으로, 우리 역사의 정체성을 훼손한다는 문제가 있다.\n\n이러한 갈등에 대응하려면 정확한 역사 연구와 자료를 바탕으로 국제 사회에 우리 입장을 알려야 한다. 동시에 주변국 시민과의 교류를 늘려 서로를 이해하는 노력도 필요하다. 학생도 올바른 지도 표기와 역사 사실에 관심을 가지는 것으로 참여할 수 있다."}],"concepts":[{"term":"지정학적 위치","desc":"지리적 위치 때문에 정치·군사·경제적으로 갖는 중요성이다. 한반도는 대륙과 해양 세력이 만나는 곳에 있다."},{"term":"독도","desc":"울릉도에서 약 87.4km 떨어진 대한민국 고유 영토이다. 동도와 서도, 그리고 여러 부속 바위섬으로 이루어져 있다."},{"term":"실효적 지배","desc":"한 국가가 어떤 영토에 대해 실제로 행정, 경비 등 통치권을 행사하고 있는 상태이다. 대한민국은 독도를 실효적으로 지배하고 있다."},{"term":"동해 표기","desc":"한반도와 일본 열도 사이 바다를 우리가 오래 써 온 이름인 '동해'로 표기하는 것이다. 정부는 국제 지도에 동해 표기를 알리고 있다."},{"term":"동북 공정","desc":"중국이 고구려, 발해 등 만주 지역의 역사를 중국 역사의 일부로 편입하려고 추진한 연구 사업이다."}]}]},"s2-s12":{"title":"사회 변동과 사회문제","lessons":[{"id":"s2-s12-1","title":"사회 변동의 양상","standard":{"text":null},"sections":[{"title":"사회 변동이란 무엇인가","text":"사회 변동은 사회 구조, 제도, 생활 양식, 가치관 등이 시간이 흐르면서 변하는 현상이다. 모든 사회는 끊임없이 변하지만, 변하는 속도와 방향은 사회마다 다르다.\n\n사회 변동을 일으키는 요인은 여러 가지이다. 새로운 기술의 발명과 발견은 생활 방식을 크게 바꾼다. 인구의 증가나 감소, 연령 구조의 변화도 사회를 바꾼다. 다른 사회와 접촉하며 새로운 문화가 들어오는 것, 사람들의 가치관이 바뀌는 것도 요인이 된다. 기후 같은 자연환경의 변화도 영향을 준다.\n\n대부분의 사회 변동은 한 가지 요인이 아니라 여러 요인이 함께 작용해 나타난다. 오늘날 사회 변동의 대표적인 양상으로 산업화, 정보화, 세계화를 들 수 있다."},{"title":"산업화와 정보화","text":"산업화는 농업 중심의 사회가 공업과 서비스업 중심의 사회로 바뀌는 과정이다. 기계를 이용한 대량 생산이 가능해지고, 일자리를 찾아 사람들이 도시로 모이는 도시화가 진행된다. 가족 형태도 여러 세대가 함께 사는 확대 가족에서 부부와 자녀 중심의 핵가족으로 바뀌는 경향이 나타난다. 우리나라는 1960년대 이후 짧은 기간에 빠르게 산업화를 이루었다.\n\n정보화는 정보와 지식이 사회의 가장 중요한 자원이 되는 과정이다. 컴퓨터, 인터넷, 스마트폰이 널리 퍼지면서 집에서 일하는 원격 근무, 온라인 쇼핑, 온라인 수업이 가능해졌다.\n\n정보화는 생활을 편리하게 만들었지만 문제도 낳았다. 개인 정보 유출, 사이버 폭력과 범죄가 늘었다. 정보 기기를 다루는 능력에 따라 정보 격차가 생기기도 한다."},{"title":"세계화와 우리 사회의 변화","text":"세계화는 교통과 통신의 발달로 상품, 자본, 사람, 문화가 국경을 넘어 자유롭게 이동하며 세계가 하나로 연결되는 현상이다. 우리는 외국에서 만든 물건을 쉽게 사고, 다른 나라의 영화와 음악을 즐긴다. 우리나라의 대중문화도 세계 여러 나라로 퍼지고 있다.\n\n세계화로 선택의 폭이 넓어지고 문화 교류가 활발해졌다. 외국인 근로자, 결혼 이민자, 유학생이 늘면서 우리 사회는 다문화 사회로 바뀌고 있다. 반면 국가 간 경제 격차가 커지거나, 고유문화가 약해지고 문화가 비슷해지는 문제도 나타난다.\n\n우리나라는 산업화, 정보화, 세계화를 짧은 기간에 한꺼번에 겪었다. 그래서 세대마다 자라 온 환경이 크게 달라 가치관의 차이도 크게 나타난다. 변화의 좋은 점은 살리고 문제는 함께 해결해 나가는 자세가 필요하다."}],"concepts":[{"term":"사회 변동","desc":"사회 구조, 제도, 생활 양식, 가치관 등이 시간의 흐름에 따라 변하는 현상이다."},{"term":"산업화","desc":"농업 중심 사회가 공업과 서비스업 중심 사회로 바뀌는 과정이다. 도시화와 핵가족화가 함께 나타난다."},{"term":"정보화","desc":"정보와 지식이 사회의 가장 중요한 자원이 되는 과정이다. 컴퓨터와 인터넷의 발달로 빨라졌다."},{"term":"세계화","desc":"상품, 자본, 사람, 문화가 국경을 넘어 자유롭게 이동하며 세계가 하나로 연결되는 현상이다."},{"term":"정보 격차","desc":"정보 기기와 정보에 접근하고 활용하는 능력의 차이 때문에 생기는 사회적·경제적 격차이다."}]},{"id":"s2-s12-2","title":"저출산·고령화","standard":{"text":null},"sections":[{"title":"저출산이란 무엇인가","text":"저출산은 아이를 적게 낳아 출생아 수가 줄어드는 현상이다. 저출산 정도는 합계 출산율로 나타낸다. 합계 출산율은 여성 한 명이 평생 낳을 것으로 예상되는 평균 자녀 수이다. 인구가 줄지 않고 유지되려면 합계 출산율이 약 2.1명은 되어야 한다.\n\n통계청 자료에 따르면 우리나라의 합계 출산율은 2018년에 0.98명으로 처음 1명 아래로 떨어졌고, 2023년에는 0.72명으로 경제 협력 개발 기구(OECD) 회원국 가운데 가장 낮은 수준이었다.\n\n저출산의 원인은 여러 가지이다. 결혼하는 나이가 늦어지고 결혼하지 않는 사람이 늘었다. 자녀를 키우는 데 드는 양육비와 교육비, 집값 부담이 크다. 일과 육아를 함께 하기 어려운 직장 환경, 결혼과 출산을 개인의 선택으로 보는 가치관의 변화도 영향을 준다."},{"title":"고령화란 무엇인가","text":"고령화는 전체 인구에서 65세 이상 노인 인구가 차지하는 비율이 높아지는 현상이다. 보통 노인 인구 비율이 7% 이상이면 고령화 사회, 14% 이상이면 고령 사회, 20% 이상이면 초고령 사회라고 한다.\n\n우리나라는 통계청 인구 통계 기준으로 2000년에 고령화 사회, 2017년에 고령 사회가 되었다. 2024년 12월에는 행정안전부 주민 등록 인구 기준으로 65세 이상 인구 비율이 20%를 넘어 초고령 사회에 들어섰다. 다른 나라에 비해 고령화 속도가 매우 빠른 편이다.\n\n고령화의 원인은 두 가지이다. 의학 발달과 생활 수준 향상으로 평균 수명이 늘었다. 동시에 저출산으로 어린이와 젊은 인구가 줄었다. 노인 수가 그대로여도 젊은 인구가 줄면 노인 인구의 비율은 높아진다."},{"title":"저출산·고령화의 영향과 대책","text":"저출산과 고령화가 함께 진행되면 일할 수 있는 15~64세 생산 가능 인구가 줄어든다. 일할 사람이 줄면 경제 성장이 느려질 수 있다. 일하는 세대가 부양해야 할 노인은 늘어나 노년 부양비가 높아지고, 연금과 의료비 부담도 커진다. 학생 수가 줄어 학교가 문을 닫거나, 젊은 인구가 빠져나간 지역의 인구가 크게 줄어드는 문제도 나타난다.\n\n이에 대응하기 위해 출산과 양육을 돕는 정책이 추진되고 있다. 육아 휴직 활성화, 보육 시설 확충, 양육비 지원, 일과 가정을 함께 돌볼 수 있는 근무 환경 만들기 등이 그 예이다.\n\n고령화에 대해서는 노인 일자리 확대, 건강하게 나이 드는 데 필요한 복지, 연금 제도 개선 등이 논의된다. 정년 연장이나 외국 인력 활용처럼 사회적으로 의견이 나뉘는 대책도 있어, 여러 입장을 함께 살펴볼 필요가 있다. 랩에서 1960년부터 2070년까지 인구 피라미드의 변화를 확인해 보자."}],"concepts":[{"term":"저출산","desc":"아이를 적게 낳아 출생아 수가 줄어드는 현상이다."},{"term":"합계 출산율","desc":"여성 한 명이 평생 낳을 것으로 예상되는 평균 자녀 수이다. 인구 유지에는 약 2.1명이 필요하다."},{"term":"고령화","desc":"전체 인구에서 65세 이상 노인 인구가 차지하는 비율이 높아지는 현상이다."},{"term":"초고령 사회","desc":"65세 이상 인구 비율이 20% 이상인 사회이다. 우리나라는 2024년 12월(행정안전부 주민 등록 인구 기준)에 초고령 사회가 되었다."},{"term":"노년 부양비","desc":"생산 가능 인구(15~64세) 100명이 부양해야 하는 65세 이상 인구의 수이다."}]},{"id":"s2-s12-3","title":"사회문제의 해결","standard":{"text":null},"sections":[{"title":"사회문제란 무엇인가","text":"사회문제는 사회 구성원 상당수가 바람직하지 않다고 여기고, 원인이 사회 구조나 제도와 관련되어 있으며, 여러 사람이 함께 노력해야 해결할 수 있는 문제이다. 청년 실업, 환경 오염, 주거 문제, 저출산·고령화 등이 그 예이다.\n\n사회문제는 개인 문제와 다르다. 한 사람의 실수나 습관으로 생긴 일은 개인 문제이다. 그러나 많은 사람이 같은 어려움을 겪고 그 원인이 사회 구조에 있다면 사회문제가 된다.\n\n사회문제는 시대와 사회에 따라 달라진다. 과거에는 문제로 여기지 않던 것이 가치관이 바뀌면서 사회문제가 되기도 한다. 반대로 사회가 변하면서 사라지는 문제도 있다. 또 같은 현상이라도 사람마다 문제로 보는 정도가 다를 수 있다."},{"title":"사회문제를 해결하는 과정과 주체","text":"사회문제는 일정한 과정을 거쳐 해결한다. 먼저 어떤 현상이 문제라는 것을 인식한다. 다음으로 그 문제가 왜 생겼는지 원인을 분석한다. 이어서 여러 해결 방안을 찾고, 각 방안의 비용과 효과, 영향을 받는 사람들을 비교한다. 가장 알맞은 방안을 선택해 실행한 뒤에는 결과를 평가하고 필요하면 고친다.\n\n사회문제를 해결하는 주체도 다양하다. 개인은 문제에 관심을 갖고 생활 속에서 실천하며 의견을 낸다. 시민 단체는 문제를 알리고 해결을 요구한다. 기업은 사회적 책임을 다하는 경영으로 기여한다.\n\n정부와 지방 자치 단체는 법과 정책을 만들어 문제를 제도적으로 해결한다. 국경을 넘는 문제는 국제 사회가 함께 협력한다. 여러 주체가 함께할 때 해결의 효과가 커진다."},{"title":"사례로 보는 사회문제 해결","text":"플라스틱 쓰레기 문제를 예로 들어 보자. 일회용품 사용이 늘면서 쓰레기가 많아지고 바다와 땅이 오염되었다. 이 문제는 한 사람의 노력만으로는 해결되지 않는다.\n\n개인은 텀블러나 장바구니를 쓰고 분리배출을 정확히 한다. 기업은 포장재를 줄이거나 재활용하기 쉬운 소재로 바꾼다. 정부는 일회용품 사용을 줄이는 제도를 만들고 재활용 체계를 갖춘다. 다만 규제가 생기면 불편을 겪거나 비용이 드는 사람도 있으므로, 여러 입장을 듣고 방안을 조정해야 한다.\n\n청소년도 사회문제 해결에 참여할 수 있다. 학생 자치회에서 학교 문제를 논의하고 개선을 건의할 수 있다. 지방 자치 단체나 정부에 온라인으로 민원과 제안을 낼 수도 있다. 캠페인에 참여하거나 문제를 주변에 알리는 것도 의미 있는 참여이다."}],"concepts":[{"term":"사회문제","desc":"사회 구성원 상당수가 바람직하지 않다고 여기고, 원인이 사회 구조와 관련되어 여러 사람이 함께 해결해야 하는 문제이다."},{"term":"사회문제 해결 과정","desc":"문제 인식 → 원인 분석 → 해결 방안 탐색·비교 → 방안 선택·실행 → 평가의 순서로 이루어진다."},{"term":"시민 참여","desc":"시민이 사회 문제에 관심을 갖고 의견 제시, 캠페인, 제안 등으로 공동체의 결정과 해결에 참여하는 것이다."},{"term":"기업의 사회적 책임","desc":"기업이 이윤 추구뿐 아니라 환경 보호, 소비자 보호 등 사회에 대한 책임을 다하는 것이다."},{"term":"공공 정책","desc":"정부나 지방 자치 단체가 사회문제를 해결하기 위해 만들어 실행하는 계획과 제도이다."}]}]}};
